/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160310-3","meetingId":"h28-c-budget","date":"2016年3月10日","dateIso":"2016-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年度品川区一般会計予算","agenda":"平成２８年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、３０９ページ、駅周辺等放置自転車対策、３４９ページ、空き家等対策事業についてお伺いいたします。駅周辺等放置自転車対策についてご質問をいたします。旗の台東口駅前の放置自転車には、商店街、そして周辺の住民、居住者の方々から、大変迷惑をしているとのお声をいただいております。現在の区のお考えをお聞かせください。","respondent":"田口交通安全担当課長","answer":"これは東急電鉄の用地になると思うのですが、ここの場所が非常に放置自転車が多いということで、先般も確認させていただきましたが、使用できない１０台ぐらいの自転車が放置されているという状況です。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"意見","question":"今、課長のご答弁のとおり、そういう状況です。そして、東急の用地の私道にかかるところ、商店街が花壇を置いて、いろいろとこういった放置自転車の対策を講じているのですけれども、区としてこれからの対策、そしてどういうふうにお考えになっているのか、改めてお考えをお聞かせいただくようお願いいたします。","respondent":"田口交通安全担当課長","answer":"繰り返し東急電鉄のほうには申し入れをしていますが、しかし現状のまままだ進展がないというのが現状ですので、区としましても引き続き働きかけ、また商店街もありますので、商店の方を交えた協議というのも必要になろうかと考えています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ東急に申し入れをしていただいて、東急の所有地ということもありますけれども、改めて区から駐輪場対策を講じていただきたいと思いますけれども、その辺のこと、これから東急、一事業者に対して、もう一回、再度ご質問いたしますけれども、東急に対して強く要望したいと思っているのですけれども、ぜひその辺をよろしくお願いいたしたいと思います。もう一回、そのことについてお聞かせお願いいたします。","respondent":"田口交通安全担当課長","answer":"引き続き東急電鉄には申し入れをしますし、また一鉄道事業者として、駐輪場の整備についてもあわせてお願いというか、してまいりたいと考えています。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ東急に要望していただいて、駅周辺の整備、そして美化、駐車場の整備をぜひよろしくお願いいたします。要望いたします。続きまして、空き家対策についてご質問いたします。区内在住の７０代の女性が所有する家屋が倒壊する危険があるとして行われたものであります。そこでお聞きいたします。品川区で近々行われるであろう空き家の行政代執行の所有者が特定できているのでしょうか。","respondent":"矢木住宅担当課長","answer":"旗の台四丁目の特定空き家についてですが、こちらについては、所有者は特定しておりますが、住所不定ということになっております。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"確認","question":"所有者が確認できるケース、そうでないケースが、いろいろ状況がありますけれども、個別での対応をしていかなければならないと思います。その辺についてお伺いしたいと思います。","respondent":"矢木住宅担当課長","answer":"特定空き家等の対策につきましては、こちら、物件の状況はもとより、所有者の抱えているいろんな問題・課題があります。そういった状況に応じて、きめ細やかな対応を行ってまいります。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"このようなことから、先日の私の質問でも申しましたけれども、特定空き家になる前に対応していくことが重要だと考えます。特定空き家になる前に品川区が援助し、地域コミュニティの場所をつくったり、若い子育て世代に入っていただくとか、有効に活用されることによって、少ない負担で特定空き家にしない取組みに力を入れていってはいかがかと考えておりますけれども、お考えをお聞かせください。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、特定空き家になる前に支援を行って、有効活用に結びつけていく、こういった施策が今後重要になっていくことと認識しております。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"意見","question":"空き家等の管理は当然、所有者の責任だと思います。区としても今後も対応、対策、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"私からは、３１９ページ、八潮団地内区道歩道拡幅整備工事、３３５ページ、しおじ公園改修工事費、３２５ページ、橋梁長寿命化修繕経費、３０９ページ、交通安全啓発費の普及啓発経費、３１５ページ、道路安全施設費の整備工事費についてお伺いします。昨年のご答弁では、まだ具体的な対策がないとのことでしたが、その後の対策に進展があったかお伺いします。","respondent":"稲田道路課長","answer":"その後におきまして、道路法なのですけれども改定がございまして、一定の交通量以上のものは危険だというところでございまして、設置できないという状況になりました。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"対策を検討いただいているということで確認がとれました。次に、しおじ公園の改修費です。そしてまた砂場も、おりて子どもが入るとすごく深いところにあって、大変危ないというような声を聞いておりまして、公園の改修をしてほしいという声がたくさん上げられておりました。そこで、このしおじ公園の今後の具体的なスケジュール等をお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"今後のスケジュールですが、まずは設計委託を行いまして、秋ごろから工事を着工というところで現在考えているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、課長からもお話がありました、わかば幼稚園の前にある公園です。そして、行く行くはここが幼保一体になるということでありまして、ぜひとも、このわかば幼稚園からの皆さんの声も聞いていただきながら進めていただきたいと思うのですが、地元の声をどのように反映させていただけるのでしょうか。","respondent":"多並公園課長","answer":"隣接するわかば幼稚園もありますので、園児の皆さんの遊び方、どのようなものがいいかという、遊具の今後の選定とか、その辺の細かい部分についても意見交換させていただきながら、よりよい公園づくりを進めていきたいと思っているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"中には、ここに水辺の噴水があったほうがいいねというような声も聞いております。ぜひとも地域のご要望を受けて進めていただきたいと思います。次に、橋の修繕費に移ります。今回ここに計上されております修繕費ですが、具体的にどこの橋の修繕費になりますでしょうか。","respondent":"稲田道路課長","answer":"この修繕費です。橋梁長寿命化修繕費ということで、勝島橋の修繕があります。それから耐震補強工事ですが、かもめ歩道橋、それから大井町のペデストリアンデッキ、それから大森駅歩道橋の修繕工事を実施予定です。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、東京都がオリンピック・パラリンピックの周辺会場の駅をバリアフリーにするという予算を平成２８年度で計上していると聞いておりますが、これは具体的に東京都に要望していただきたいところなのですけれども、まずは歩道橋のバリアフリー化についての品川区のお考え、そしてまた大井競馬場前駅のバリアフリー化を東京都に対して強くまた要望していただきたいことをお願いするのですけれども。","respondent":"稲田道路課長","answer":"ただし、ご指摘のとおり、会場に向かうほうのメインの入り口というのですか、そちらは階段になっておるというところでございまして、道路としてもバリアフリー、今後、これからちょっと検討していくですけれども、なかなか非常に構造が難しいという状況はありますが。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"非常に技術的には課題が多いかと思いますけれども、ぜひとも検討を進めていただきたいと思います。次に交通安全経費です。今回、この平成２８年度の予算の中に、昨年度と同じ内容での、ここに詳細が記されております。第１０次交通安全計画策定が追加になっておりますが、内容的に平成２７年度と、この交通安全の対策をとるにあたって新しい内容がありましたら、内容等お聞かせいただきたいと思います。","respondent":"田口交通安全担当課長","answer":"新しい内容につきましては、第１０次の交通安全計画の策定、この項目が新しい項目になります。なお、この内容につきましては、平成２８年度から平成３２年度までの５カ年間の当区におけます交通安全計画を策定し、交通安全対策の指針とするものです。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"続けまして、１月に会派として宇都宮へ、子ども自転車免許の視察に行ってまいりました。このことによって、この直近５年間、自転車事故が４割減少したという結果が出ておりまして、ぜひ品川区でも、子どもへの意識啓発のために、子ども自転車免許の導入をお考えいただきたいのですけれども、いかがでしょうか。","respondent":"田口交通安全担当課長","answer":"それと、免許証制度についてですが、東京都内は２３区内で１０区、実施していると聞いてあります。通常の免許と同様に、講義、筆記試験、また実技試験を行うことになりますので、時間がかかり、受講する人が制限されるということになるそうです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"３３７ページ、五反田地区コーディネート業務委託に関連して、五反田のまちづくり、第一日野小学校跡地について伺います。後ほど、３４９ページ、区営住宅についても伺いたいと思います。秋の決特では、ずっと協議を進めていると。伺いますけれども、今年８月からのＴＯＣ本体ビルの工事着工という予定、つまり解体工事が始まると説明していたのですが、このスケジュールに変わりはないのかどうか伺います。","respondent":"溝口都市開発課長","answer":"ＴＯＣの建替えの関係です。建設費の高騰等、いろいろ、また工法を含めて、ＴＯＣ側でさまざま検討している段階です。そういった中で、現在、夏頃の着工というのは現段階では難しいと聞いているものです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"変更がある、難しいということでしたけれども、いつになるのでしょうか。それと、これがずれてしまったので、全体の貸し出し計画、契約の期間がずれ込んでいくということも考えられるのではないかと思いますけれども、区として、ＴＯＣの貸し出しの契約の更新も考えているのでしょうか。私はやめるべきだと思いますけれども、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"工期の関係です。私どもとしては、五反田のにぎわいづくりという観点で、五反田ＴＯＣの建替えというのは必要だと考えておりますので、できるだけ早い時期に着手できるよう、ＴＯＣとの協議というのは引き続き検討していきたいと考えています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"できるだけ早い段階でということですが、これまでもそう言い続けながらここまで来ているわけです。本体計画が見えないまま、１月に第一日野小学校跡地には、仮設建物、ＴＯＣ五反田メッセがオープンしました。見に行きましたけれども、実態は単なる催事場です。常設店舗は１軒もありません。この状況は、当初の区の考え方とも違うのではないでしょうか。いかがでしょうか。","respondent":"柏原企画調整課長","answer":"いずれにいたしましても定期借地の契約ですので、その期間を超えてということでは考えているものではございません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、当初の区の考えと違うのではないかということなのですけれども、現状は先ほど説明したとおりです。とりわけ、先ほどもう一つの理由も紹介しましたけれども、第２ＴＯＣの補強工事のテナント代替とも言っておりましたが、実際には常設の店舗は１店もないのです。私の質問にまたお答えいただきたいと思います。区の考えと違うのではないでしょうか。","respondent":"柏原企画調整課長","answer":"今ある仮の店舗といいますか、建物ですけれども、先ほどもご説明いたしましたように、本体もしくは関係する建物、建替え等々のときの代替にも使うというところで聞いてございまして、今、催事場として建ててありますので、中が区切られて。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は大きく離れていると考えています。ここは学校跡地で区の土地です。保育園や特養ホームなど、切実な住民要望があふれている中、こうした学校跡地を、いわば塩漬け状態にするのではなく、今こそこうした住民要望に当てるべきだと求めますけれども、いかがでしょうか。あわせて、第２ＴＯＣのテナント代替地、補強工事のテナント代替地という理由はもはやなくなったのかどうかも伺います。","respondent":"柏原企画調整課長","answer":"それで、第２ＴＯＣビル等々のお話もございましたけれども、ＴＯＣの企業としての、中の計画等々、いろいろ考えているとは聞いてありますので、そういった状況も、こちらで情報をとりながら対応はしていきたいと思ってあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ理由を伺いますけれども、やはり私は公有地の活用の仕方としては間違っていると思いますので、地域から出されている認可保育園、特養ホーム、公園など、切実な住民要望のために使うべく、計画を変更していただきたいと強く求めておきます。次に、区営住宅、公営住宅の増設を求めて質問いたします。増設しない理由にはなっていないと思います。私は増設すべきだと思いますけれども、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"区営住宅を増設しない理由ですが、まず複合型と高度利用ができる適地がないことや、こちらの今年度予算にもありますように、８億円といった多額な建設コストおよび維持コストがかかるということで、現在の住宅戸数・棟数を維持した上で、これ以上。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"要するにコストの問題だということだと、今、私は聞いて思いました。とんでもないと思います。まちづくりマスタープランによれば、この公営住宅の必要性にかかわって、所得が１００万円未満の世帯の６割は借家暮らしをしている。それで、借家暮らしというと、品川区ですから、大変家賃が高いわけです。これで、住宅に困窮する世帯が救えると思っていらっしゃるのかどうか伺います。","respondent":"矢木住宅担当課長","answer":"住宅確保要配慮者に関する課題・問題については、多々あると認識しています。こちらにつきましては、居住支援協議会といった大きな枠組みの中で、総合的な問題解決を図る仕組みづくりが必要ではないかと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"総合的とは言えないし、これでは住宅に困窮する世帯が救えないと私は思うのですけれども、この中に、所得が１００万円未満、世帯の６割の借家暮らしの方々が救えないとしか思えないのですけれども、もう一度、そこら辺をしっかりとご答弁をお願いいたします。","respondent":"矢木住宅担当課長","answer":"先ほど申し上げた答弁の繰り返しになりますが、私どもといたしましては、情報提供、相談窓口以外にも、やはりきめ細やかにニーズがあると考えておりますので、そういった組織体の設置を検討してまいります。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、経済も大変な中、所得も上がらない大変な中、高い家賃で暮らして困窮している方々がたくさんいるというところに対しての、やはり私は、公営住宅の増設あるいは家賃助成の創設など、こうした具体的な対策こそ必要だと思いますので、これを求めたいと思います。あわせて、都営住宅の存続、公営住宅の存続ができるような対策、都営住宅の区移管を含めてやるべきだと思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"前面の道路の部分につきましては、４ｍの細い道路ですので、あそこを取得したにしても、大きな建物を建てる見込みというのはかなり厳しいという判断があります。そういった状況から購入を断念したというところもあります。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"私からは、３１５ページの街路灯管理の電気料について、３１９ページのオリンピック・パラリンピック施設周辺無電柱化事業について、３３３ページのしながわ区民公園改修工事、そしてしながわ水族館２５周年事業の支援について伺います。この５００万円の差というのは、ＬＥＤの効果を期待してこのような金額がつけられているのか伺います。そのほかに理由がありましたら教えてください。","respondent":"稲田道路課長","answer":"街路灯維持管理費の電気料です。平成２７年度と平成２８年度の予算の見込みにおきましては、５００万円ほどの差があります。これがほとんどの費用の減ですが、これはＬＥＤ化による減で、見込みで計算しますと、約４００万円ほど下がっていくです。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"本年度でも、街路灯建替え事業で、１,４４４基がＬＥＤ型に変わるということになっております。現段階で、品川区が所有する街路灯をＬＥＤ型に建て替えるにあたり、全体でどのぐらいの月日がかかって、完了予定なのか、目標について伺います。ＬＥＤ型にする建替えの順番というものはありますでしょうか。そうした危険箇所を優先的に建て替えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"稲田道路課長","answer":"要するに、古くなっているものを先に交換していくということで、この千四百数十基は建て替えていきます。それで、個々の暗い箇所等々におきましては、維持のほうで電球の取りかえなどということには対応していこうというふうにやっておりますので、ご了承願います。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"平成３１年度に終わる予定であるということでありますけれども、もしこうしたＬＥＤ型に全部建て替えた場合、どのぐらい電気料金が削減できるかというのを伺いたいと思います。逆にＬＥＤ型にしてまぶしいという意見もちょっと伺ったことが昔あったのですけれども、そういった方たちの対応についてどのように行われているのか伺います。","respondent":"稲田道路課長","answer":"これは５年間で掛けますと、約２,０００万円ぐらいは、これはいろいろと電気代は上下するので何とも言えないところなのですが、見込みとしてはそれぐらいになるのではないかと考えております。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"その削減された部分に関しては、ぜひそういった、例えば自転車レーン整備などに充ててほしいと思います。イルミネーションに関してですけれども、大井町周辺といいますか、ヤマダ電機側にもぜひお願いしたいと思います。次に３１９ページの、オリンピック・パラリンピック施設周辺無電柱化事業について伺いたいと思います。この道路詳細設計委託の３,６８０万円の内訳というか事業内容について伺います。","respondent":"稲田道路課長","answer":"オリンピック・パラリンピックに伴う詳細設計ですが、道路の基本的な構造の詳細設計というところで考えております。ただ、自転車の通行に関しても検討はしていくというところで、並行してこの中でやっていくというものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで今、自転車レーンというお話も出ました。次に、３３３ページのしながわ区民公園改修工事について伺います。プレス発表を拝見させていただきました。この公園の工事なのですが、いつごろから始められるのか伺います。","respondent":"多並公園課長","answer":"しながわ区民公園につきましては、大きく３分布に分けまして公園の再整備を行っていこうと考えているところです。来年度につきましては、そのうちの中央ゾーン、いわゆる、昔のクジラの噴水があったあたりの中央ゾーンを整備する予定です。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"そうした中で、今、結構利用されている東側に関しては、バーベキュー場があると思うのですけれども、主にこれは夏時期になると利用が多いと思うのですけれども、その方たちへの対策というのはどのようにとられていくのか。西側に関しては、毎日早朝、ラジオ体操をされているのですけれども、そうした方たちに対しての周知とか対策というのはどのようにとられていくのか伺いたいと思います。","respondent":"多並公園課長","answer":"ラジオ体操にお使いいただいている方も、先日、整備の説明会ということで住民の方々にご説明させていただいたときもご意見をいただきまして、やはり１００名以上の方がご利用いただいているということで、工事の段階で、さっきちょっとご説明が抜けたところがありまして。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問","question":"そうした方々に対しての周知をお願いいたします。最後に、同じページのしながわ水族館開館２５周年なのですけれども、これは事業予算が２,５００万円ということで、これは２５周年にということで２,５００万円つけたのか、それと、その内容について伺いたいと思います。","respondent":"多並公園課長","answer":"もう一つが、著名人の方にプロデュースしていただいた水槽を作りたいということで、すみだ水族館の例で言いますと、蜷川実花氏がやられた水槽もありますので、それのような、これから著名人の方ともお話しさせていただきながら。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問","question":"イルカとタッチで１,５００万円ということでありますけれども、これは来園者の……。工事ですか。すみません。失礼いたしました。工事にかかるということであります。このときに、イルカとタッチのところで料金というのはかかってくるのですか。特別だと思うので。それで滅多にできないことですので。１日何名とか、そういうのがちょっとわかったら教えてください。","respondent":"多並公園課長","answer":"イルカのふれあいスペースの件ですけれども、実は料金はいただく予定で今考えております。ただ、ほかの水族館の例などいろいろ確認するのと、この水族館の例と、そこら辺を考えながら、今、運営する企業とは調整しているところです。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"開館２５周年の記念イベントというのは、例えば式典などやられるのか、また期間というのは何月から何月か、ちょっと伺いたいと思います。もう一つは、有名人のイメージするプロデュース水槽なのですけれども、今、検討中ということでありますが、差し支えなければ、どなたを検討されているのか伺いたいと思います。","respondent":"多並公園課長","answer":"そこのイベントの中で、先ほどの１,０００万円を計上させていただいたプロデュース水槽という中に、そこの全体的なイベントの内容を考えておりまして、そこのお披露目も含めながらこの事業を進めていきたいと考えております。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"最後に、２５周年記念イベントの周知方法ですか、これは区内だけでやられるのか、それともいろんな鉄道各社とかと、タッグを組んでやられるのか、伺いたいと思います。","respondent":"多並公園課長","answer":"周知につきましても、もちろんホームページ等でも周知するところですけれども、それ以外の方法も、これまでも京急線との連携などもやっているところもありますので、その辺は今後、調整しながら進めていきたいと思っているところです。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"３２７ページの水辺利活用事業のにぎわい創出検討経費についてお伺いいたします。プレス発表資料によりますと、にぎわい創出検討委託は舟運社会実験等となっていますが、舟運社会実験とは具体的にどういうことでしょうか。その内容をお知らせください。","respondent":"和田河川下水道課長","answer":"にぎわい創出検討委託の舟運社会実験の内容です。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"次に３２１ページ、排水施設建設事業に関連して質問いたします。我が会派から再三質問していますが、西大井の下水道局の件はどうなっているでしょうか。お知らせください。","respondent":"和田河川下水道課長","answer":"したがいまして、１１月着工ですので、工事完了が当初の予定では今年の９月だったものが１年ぐらい延びるということで、今、下水道局では、平成２９年９月ごろ完成の目標で、鋭意、工事を進めていると聞いております。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。しっかりと進めていただきたいと考えております。次に３４９ページの分譲マンション管理支援についてお伺いいたします。この分譲マンション管理支援の内容をお知らせください。","respondent":"矢木住宅担当課長","answer":"年に１回、それぞれ行います、分譲マンションの管理セミナーやマンション管理組合防災対策等検討交流会という形で、大規模修繕ですとか、防災に対する備えですとか、そういったところの相互理解であったり講演会であったりという形式で行っているものです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に３３７ページ、西品川一丁目地区再開発事業補助金と、３３９ページ、目黒駅前地区再開発事業補助金についてお伺いいたします。それぞれ、西品川は１１７億２９０万円、目黒駅前は９４億２,２１０万円となっておりますけれども、これは一見すると、額が非常に多いので、非常に気になるところなのですけれども、この補助金の仕組みと財源はどうなっていますでしょうか。簡潔にお知らせください。","respondent":"溝口都市開発課長","answer":"全体の、本年度かかります、それぞれの再開発事業の事業費に対しまして、補助対象の事業費を算定いたします。その補助対象の事業費に対して、３分の１が再開発組合で、３分の１が国費で、３分の１が区費という形の関係になっております。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、品川区の一般財源からは使われていないということでよろしいのでしょうか。","respondent":"溝口都市開発課長","answer":"すみません。今回、区費、品川区で予算を組んでいる歳出予算につきましては、一般財源は使わずに、財調または都市計画交付金または国費といったものを充てて予算を組んでいるというものです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。本当にこの額が一見すると非常に大きいので、そうした仕組みを一般の区民の方はよくわからないと思いますので、ぜひとも今の仕組みを簡単に示したもの、区民の方への説明のための資料、広報をぜひともお願いしたいと考えておりますけれども、その点はいかがでしょうか。","respondent":"溝口都市開発課長","answer":"今回の予算、また補助金の仕組みといったものについてはホームページでも掲載しているところではありますが、まだまだ市街地再開発事業、またほかのいろいろなまちづくりの仕組み、制度といったものについて、わかりづらい部分等ありますので、機会を捉えながら。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"財政はそれでよろしいのでしょうか。財政課長、よろしくご答弁ください。","respondent":"秋山財政課長","answer":"今、都市開発課長がご説明したとおりです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"確認","question":"しっかりと、またこの点は、これからまた確認したいと思います。次に３３１ページ、京浜急行線連続立体交差化事業、３３９ページ、品川駅南地域整備検討委託について、それぞれ簡潔に内容をお知らせください。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"こういった検討を、東京都がまず調査を行うとしております。区としましても、それに連携して、基礎的な立体化に伴う周辺地域の環境影響ですとか、そういった基礎的な調査を行うといった内容です。それを引き継ぎまして、平成２８年度も、そういったところの、まちづくりをどのように進めていくのかというところの具体化の検討をしていきたいと考えています。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"この両事業、平成２６年につくられた品川駅南地域まちづくりビジョンにも則ったものと理解してよろしいのでしょうか。","respondent":"溝口都市開発課長","answer":"そういった中で、一つまちづくりの大きな流れとして、連続立体化事業というのが今後見込まれておりますので、それも含めましてどのようなまちづくりを進めていくのか。そういったところの検討をしていきたいと考えているものです。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"これは先日も私、「品川区はすごいね」と言われまして、「何がすごいのですか」と私が尋ね返しましたら、いや、「新幹線がとまるじゃないですか」と、その人はお答えが返ってきまして、いや、「品川駅は港区です」というようなお答えをいたしました。本当に区民、そして区の施策、日本全国の人のために、ぜひとも品川駅を品川区にしてほしいのですけれども、これは実は不可能ではない。法的に可能なのです。","respondent":"柏原企画調整課長","answer":"今、委員がお尋ねの部分は恐らく、特別区の部分の境界、それから変更等々の部分であろうかと思います。地方自治法上は、第２８１条の４ですか、こちらのほうで、境界の変更等々が、一定の手続を踏めばというところでの条文があります。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"地方自治法第２８１条の４で可能ですので、せめて品川駅の敷地内だけでも、ぜひとも港区と交渉していただいて、濱野区長の代で、このわかりにくい問題を解決していただきたいと願っております。ぜひともご検討のほど、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"横山委員","kind":"確認","question":"私からは、３２７ページの治水対策費と、３３７ページの子ども達のアイデアを活かした公園整備についてお伺いいたします。子ども達のアイデアを活かした公園整備についてお伺いします。初めに、荏原南公園改修工事実施設計委託の更正減額がありました。その理由を確認させてください。","respondent":"多並公園課長","answer":"それだけではなくて、地域行事でも非常にお使いいただいているということもありますので、そこを確保しながら、ほかの遊具等、全体的な老朽化している施設の更新を図ろうとすると、やはりいろいろな施設の更新で利用に大きな影響があるということがわかりまして。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問","question":"今、基本設計でとまっているというような状況ということなのでしょうか。来年度、平成２８年度に、地域の方のお話をお聞きして、基本設計、そして詳細設計という形で進められるのでしょうか。今後の設計ですとか工事のスケジュールのほうをお聞かせください。","respondent":"多並公園課長","answer":"それで、工事については詳細設計で、具体的な工事の内容を固めて、平成２９年度以降、地元のご意見をお伺いしながら、基本的にはイベント等も支障がないように工事を進めていきたいという計画で今後進めていきたいという内容です。","id":"exchange-046"},{"speaker":"横山委員","kind":"意見","question":"詳細なご説明ありがとうあります。例えばキャッチボール場ですとか広場ですとか、そういった大きなゾーンで、現在の使用状況ですとか、地域の方のお声、そのあたりを区はどのように捉えていらっしゃるのか、現在の大きなゾーンの枠組みというところでのお考えを聞かせていただければと思います。","respondent":"多並公園課長","answer":"大きなゾーンという考えで申しますと、やはり今の広場のゾーンが一番、大きく据えないといけないところと。","id":"exchange-047"},{"speaker":"横山委員","kind":"確認","question":"利用状況の確認をしていただきながら今後とも進めていただければと思います。最後に１点だけ、子ども達のアイデアというところなのですけれども、今後、まだアイデアを聞くという段階にはなっていないのかなと思うのですが、そのあたりのスケジュール感も最後にお願いいたします。","respondent":"多並公園課長","answer":"子ども達のアイデアを活かした遊具の選定に関しましては、先ほども申しました詳細設計という中で決めてまいりますので、東品川公園のときも地元の小学生の方々との意見交換をしながら選定してきた経緯もありますので、今回の荏原南公園につきましても、近隣の小学校。","id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"では次に移らせていただきます。治水対策費についてお伺いいたします。品川区の河川、目黒川と立会川と下水道の設備状況について、品川区総合治水対策推進計画に基づき、現在の状況と治水安全度達成率、浸水対策整備率の推移、平成２６年度、平成２７年度あたりの部分を教えてください。","respondent":"和田河川下水道課長","answer":"雨水流出抑制に関しましては、平成２９年度に、時間５ミリの雨水を地中に浸透させるべく、雨水浸透施設を整備するというような目標ですけれども、現在、平成２５年度に１０万トンという水が地中に浸透するような整備が完了していますけれども。","id":"exchange-049"},{"speaker":"横山委員","kind":"意見","question":"今、雨水浸透ますの設置の促進ですとか、雨水利用タンクの助成ですとか、また防水板の設置助成事業といったところを、促進、またＰＲしていくというところに区のほうで取り組んでいらっしゃると思うのですけれども、こちらの詳細を、近年どういったＰＲに取り組んでいらっしゃっていて、どのような効果があらわれているのかお聞かせいただけたらと思います。","respondent":"和田河川下水道課長","answer":"３つの施策のＰＲ活動の詳細ですけれども、まず増改築の施工業者の連絡会に参加いたしまして、業者にまず認知していただくというようなＰＲをしています。水防訓練やＥＣＯフェスティバルなどのイベントにブースを出しまして、そこで広く区民の方々に周知を図っているところです。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問","question":"引き続きＰＲの強化をお願いしたいと思います。そのあたり、現在の品川区の総合治水対策推進計画改定版で順調に進めていただいているかと思うのですけれども、１００ミリを超えるような集中豪雨の際、どのような効果を発揮してくると区のほうではお考えでしょうか。","respondent":"和田河川下水道課長","answer":"品川区の計画ですけれども、これは東京都豪雨対策基本方針という都の方針に従って策定されたものでございまして、都の考え方ですけれども、この方針はおおむね３０年後を見越して、時間７５ミリまではハード対策として雨水を強制的に排除するということですけれども。","id":"exchange-051"},{"speaker":"横山委員","kind":"意見","question":"実際の被害が出ているのは、１００ミリを超えるような豪雨になっているかと思います。そういった現在の品川区の状況、そして今後、区民の皆様の自助の部分というものの力も発揮していただくということで、ＰＲ促進、今後とも強化をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"提案","question":"１点目ですけれども、先ほどの質疑の中で、区営住宅費の質問の中で、住宅困窮者の住宅施策に関して、「総合的な検討をする組織体をつくる」というようなご答弁があったのですけれども、これは居住支援協議会を創設するということでよろしいのでしょうか。４点伺います。４点目、区内唯一の国が定義する交通公園ということで、どういうふうに交通安全に活用されていくのか、この４点について伺います。","respondent":"矢木住宅担当課長、多並公園課長、稲田道路課長、立川経理課長、中村都市計画課長、田口交通安全担当課長、小林施設整備課長","answer":"第１点目、居住支援協議会の設立の予定ですが、まず国が掲げた目標といたしまして、平成３２年度までに１００％。時計につきましては、やはり地元の方からも説明会でもお話があったのですけれども、見やすくという話がありまして。ということで、歩道橋撤去、それから信号機をまず設置する、横断歩道を設置するには、警視庁の基本的な考え方は。区ではこれまで、いわゆる契約約款の中に、設計変更については定めておりましたので、今後ともこれまでどおり柔軟に。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"バリアフリーなのですけれども、稟議の結果なのですが、やはりあそこはテナントなので、ヤマダ電機の一存ではなかなかできないというところもあるのですけれども、やはりバリアフリー計画の一覧を見ると、ヤマダ電機のところだけがないという、非常に目立つ状況になっているということで、今後も働きかけを進めていただきたいと思いますし、最後になりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"３４８ページの住宅費、これ全般にかかわることです。定住化促進は重要なテーマです。区民にとっても切実な願いです。そこで伺いますが、この２つの調査が導き出した、子育て世帯の定住化に向けた支援に取り組む必要があるという方向性について、区は、アンケートの願いも含めてしっかり受けとめ、定住化促進のための子育て世帯を対象にした家賃助成をするべきだと思うけれども、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"子育て世代の定住化促進についてですが、こちら、定住化促進は、当然のことながら、住宅施策のみならず福祉施策等々、トータルバランスの中で考えていくものです。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"この２つの調査をかけて、それ相当の費用もかけて行った調査で、先ほど紹介したような、定住化に向けた支援に取り組む必要があると導き出している。ここについて品川区はどういうふうに考えているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"さまざまな施策が考えられるところではありますけれども、どういったところができるかというのは、こういったご意見をもとに庁内のほうでも検討を深めたいと思ってあります。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"必要な部分は行っていく、検討していくということでした。それから、２つ目の質問として、３０９ページの大森駅水神口の駐輪場整備の計画ですけれども、７６５台にした根拠というのは何なのか、当面の需要は満たされていると考えてこういう数を設置したのか、その辺について、あの地域のマンション建設が非常に盛んに広がっている中で、どういうふうにこの数字を見たらいいのかというところを伺います。","respondent":"柏原企画調整課長、田口交通安全担当課長","answer":"人口ビジョン等々、こちらのほうでつくってアンケート等も行った中ですが、そこの中で一定の方向性等々、将来展望も出していますけれども、委員が今ご紹介いただいた家賃助成をせよというふうには。７６５台の根拠ですが、これは今回、３基、整備いたしますが、１基が２５５台ということで、３基で合計７６５台と。これは標準仕様となっております。ということで、７６５台という数となっております。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"その辺の認識はどうなのかを伺います。子育てファミリー世帯向けの家賃助成です。そういう対策の一つに家賃助成を入れていくべきだと思いますので、その点についての見解を伺います。全ての子どもが使えるようなということもありかもしれないけれども、やはり一定の年齢層というところ、対象をはっきりして公園づくりということも私は大事なことだと思いますので、その辺を伺います。","respondent":"柏原企画調整課長、多並公園課長","answer":"そういった中で、どういったことが効果があるのか。いろいろな区のほうの財政的な負担面でも、そういったところを総合的に勘案しながら必要な施策を検討して打っていくという姿勢です。しおじ公園の件ですが、やはり先ほどもご説明しましたが、わかば幼稚園の近くにあるということで、幅広い子どもたちが遊べるような遊具ということで、最近いろんなところで入れしていますけれども、複合遊具といいまして、その中でも。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"私は、せっかくというか、やはりきちんと定住化促進のために、家賃助成も中心に据えて検討するべきだということを強く求めたいと思います。内陸部のほうに比べれば十分豊かにあると思います。子どもがやはり増えている状況もありますので、やはり小さな子どもも安心して外で遊ばせられるような公園づくりもしっかり見据えていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"吉田委員","kind":"確認","question":"私からは、３３７ページ、４項都市計画費、３目公園新設改良費、子ども達のアイデアを活かした公園整備、３３１ページ、４項都市計画費、１目都市計画総務費、区民の自主的なまちづくりへの支援、３４９ページ、６項住宅費、１目住宅総務費、空き家等対策事業について伺います。最初に、３３７ページの、子ども達のアイデアを活かした公園整備について伺います。１個、言葉の確認だけさせてください。","respondent":"多並公園課長","answer":"委員の今のお話のとおり、詳細設計と、ここに書いてあります実施設計というのは、同意義で先ほどお使いさせていただいたということで、紛らわしい言葉ですみませんでした。同じです。","id":"exchange-060"},{"speaker":"吉田委員","kind":"確認","question":"確認です。それで今回、進捗状況を質問するということで、そもそもの計画全体、どういうふうに進められるように構想されているのか押さえるために、２０１４年から２０１８年の品川区長期基本計画と、それに基づいて策定された第３次品川区総合実施計画を確認しました。それで、変更の場合はその理由や手順を含めて点検できるようなものが欲しいと考えるのですが、それはいかがでしょうか。","respondent":"多並公園課長","answer":"それで、総合実施計画との関係ですけれども、もちろん適宜、このような形で、今度の新しい計画の中にも、もちろんこういう進捗に沿った形で計画していって、より皆様にわかりやすい計画の。","id":"exchange-061"},{"speaker":"吉田委員","kind":"提案","question":"それで、過去の生活者ネットワークの一般質問に対して、区長は、「総合実施計画は具体的に区民に施策を知らせるため」という趣旨のご答弁をされています。総合実施計画というのは、その趣旨に沿ったものであるべきなのではないでしょうか。それと、先ほどちょっと、第４次計画についてはどうなっているかという質問をしたのですけれど、その辺もあわせてお答えいただきたいと思います。","respondent":"柏原企画調整課長","answer":"それで、年次年次の予算というものをまた持っておりますので、素早い対応というところであれば、その年次年次の予算で、皆さんこういったところでご議論いただきながら事業を進めていくというような姿勢ですので、長いもの、短いものというのはありますけれども。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご答弁の内容はとても理解できます。ただ、第３次の実施計画ですか。特に点検というのを、ある意味、積極的に区民に求めていくということも必要なのではないかと思いますので、これについては引き続き要望ということでとどめたいと思います。２０１５年度の実績について、補助団体の数と、具体的にどのような団体やまちづくり活動へ支援されたかを伺います。","respondent":"中村都市計画課長","answer":"区民の自主的なまちづくりに対する支援ですけれども、こちらはまず２０１５年度、平成２７年度実績です。まちづくりの団体に対する支援が７団体です。そして、まちづくりの専門家の派遣を、７回行いました。まちづくりの団体として登録されておりますのが、現在９団体あります。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"後でそれを確認するのと、生活者ネットワークとしては、この事業を、市民がまちづくりへ参加するきっかけとして高く評価しております。２０１５年度の予算立ての根拠として、補助団体を１３団体と見込んで、１７２万円の計上、今年度は今のところ７団体ということですから、見込みには届いていないということですが、次年度予算を実績より多く計上していることも評価させていただきたいと思います。","respondent":"中村都市計画課長","answer":"この区民の参加につきましては、まず大きな視野での用途地域等の区で定めたものはありますけれども、その中で、それぞれの地域の方々が自分たちのまちについて、環境の保全ですとか、あるいは防災性の向上といったものに対して意識を持って取り組んでいくといったところについて。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり、実際、自分たちがまちづくりに関しての悩みとか課題にぶち当たったときが気付くときと言うのはすごくよくわかって、そういう団体が利用しやすいのはすごくわかります。これは要望です。最後に、空き家等対策事業について、先ほど別の委員からもご質問がありましたけれども、２０１５年度予算が８２２万５,０００円に対して、２０１６年度予算は倍増以上ですか、しています。","respondent":"矢木住宅担当課長","answer":"こちらが新しくできたものでございまして、措置・支援に関しましては空き家等適正管理審議会にかけて特定空き家等の速やかな措置等を行ってきたほか、有効活用につきましてはモデル事業ということで、産学官連携のもと、活用の検討をしてまいったわけですが。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり、この空き家活用、建設委員会でもいろいろ議論があって、その議事録も読ませていただきました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"沢田委員","kind":"質問・要望","question":"有効活用可能な空き家をこれからどういうふうに活用していくかということは、これからの空き家の有効活用の中で大変大切なことですけれども、今回の予算の中で、今お話もありましたけれど、活用モデル検討経費補助ということと、それからまた改修助成ということで、２軒ということで書かれておりますけれども、具体的に区としてどのような有効活用を考えられているのか、教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"区といたしましては、まず町会等、地域のニーズを聞いて、会館等の公共施設の設置を検討していくでありますとか、ないしは区の事業で空き家を活用するでありますとか、さまざまな用途を想定して活用を検討していきたいと考えています。","id":"exchange-067"},{"speaker":"沢田委員","kind":"質問・要望","question":"その後、ＮＰＯとか、そういったことも考えられているわけだと思うのですけれども、もう少し具体的に、町会では町会、ＮＰＯ、そのほかの団体等、区としてもある程度、優先順位というか、活用できる方法を、町会でも使い勝手が悪いところもあるとか、そういったことをこれから調べていかれて、どういうふうに活用していくかを考えていかれると思うのですけれども。","respondent":"矢木住宅担当課長","answer":"空き家の活用は基本的には所有者の考えることですので、区として何か有効活用ということであれば、やはり公共目的といったところで限定して考えていくべきであろうと考えていますので、その辺の体制でありますとかロジック等々につきましては、現在、鋭意検討中でございまして。","id":"exchange-068"},{"speaker":"沢田委員","kind":"質問・要望","question":"行財政改革特別委員会の中でも話が出ていますけれども、隣の大田区が民泊特区ということでいろいろと話を進められておりますけれども、委員会の中でも、区はその状況を見ながらという話がありましたけれども、今回、民泊特区で、現状ではまだ申請が３件しかないという大変厳しい状況だということで新聞等でも報道されていますけれども、区として率直に、先に大田区が進められたということで、品川区も当然。","respondent":"柏原企画調整課長","answer":"国家戦略特区を使ってという形で動き出したものでございまして、品川区といたしましても、そういったすきも見ながら検討ということはしておったのですが、大田区の場合ですと、宿泊の施設が今後不足してくるという状況を見ながらということでありますので。","id":"exchange-069"},{"speaker":"沢田委員","kind":"意見","question":"今お話がありました、厚生労働省の旅館業法の規制緩和のほうも国は考えられているということで、品川区でも、民泊というか、いろいろと事業をされていますけれども、そういった規制緩和がある一方で、近隣とのトラブルとか、そういった話もあるということで、大田区は特区の中でやられたということですけれども、これから品川区として、そういった状況を見定めながら考えていくということですけれども。","respondent":"柏原企画調整課長","answer":"ただし、先ほど申しましたように、例えば延べ床の数であるとか、宿泊の日数が６日であるとかいったところがありますので、そういったところ、実際の事業者が動けるかどうかということ、それから近隣等々のトラブルがやはり一番懸念されるところでありますので。","id":"exchange-070"},{"speaker":"沢田委員","kind":"質問・要望","question":"わかりました。それから防犯カメラのことで、公園管理費の中でちょっと聞いていきたいと思います。この間、ちょっと話を聞いたのですけれども、まず品川区内の区立公園の中で、防犯カメラが設置してある公園というのはどの程度あって、どのような場所に設置されているでしょうか。","respondent":"多並公園課長","answer":"防犯カメラの件ですが、区内の大きな公園の中で管理上必要な死角等を管理する点で、防犯カメラというのを設置してございまして、全部で１１公園に３０台のカメラが現在設置しています。","id":"exchange-071"},{"speaker":"沢田委員","kind":"質問","question":"１１公園に３０台、大きな公園ということで３０カ所ということでありましたけれども、この間ちょっと聞いたときに、今、品川区は町会が防犯カメラを設置していますけれども、現在、都の補助金を受けて町会が設置している防犯カメラを公園のほうに向けた場合、基本的には都としては助成対象にはしないというお話を、この間、質問の中でも聞かせていただいたのですけれども。","respondent":"多並公園課長","answer":"ただ、先ほどの町会がつけております、東京都のほうの補助を受けて行っているものは、都の補助要綱の中で、道路のほうを向けて設置することというのが要件になっているということで、そういう対応で町会がやられているのではないかということで確認しています。","id":"exchange-072"},{"speaker":"沢田委員","kind":"質問・要望","question":"やはり今、公園も大分、安全対策をいろいろ進めていますけれども、やはり犯罪等が起きたり、ごみの不法投棄等の問題もありますし、この間、ニュースでも、荒川区で全ての区立公園に防犯カメラを設置するという話もありました。安心安全なまちづくりの観点からも、品川区のそういったところ、必要とされているところに、ぜひとも設置していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"３１２ページの道路維持費の中から、先ほどちょっと、水銀灯８,０００基を５年で建て替えるというところで、その次のページにあるＬＥＤ設置については１,４４４基、平成２７年度は１,４５９基というところで、５年間で８,０００基となると１,６００基ぐらいなのかなと思うと、まだ時期的に間に合わないのではないかというところで教えていただきたいのと、あと予算が、昨年に比べると。","respondent":"稲田道路課長、田口交通安全担当課長","answer":"今年度、詳細の検討を今しております。ネットワーク化を図ろうと今思っていて、最後のまとめを今しようです。青色で塗る路肩からか、そういうのと、あとナビマークで表示するもの。あわせて昨年、道交法が改正になりまして、警察のほうの取り締まりが強化されております。件数につきましても摘発件数が増えていると伺っております。一定の成果が出ているのかなと感じております。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。道路維持のほうの水銀灯などはわかりました。最後に、３２６ページ、河川総務費の中から、目黒川の水質改善について伺いたいと思います。高濃度酸素水とか、都のほうで、浚渫されて、今、効果について調査するなどされているということだと思うのですが、今の事業の流れについて教えていただきたいと思いますし、どの程度の基準になっているか教えてください。","respondent":"和田河川下水道課長","answer":"ここに来て水質の苦情が多いということですけれども、我々も認識してございまして、抜本的な解決策は、やはり川の合流改善ということで、東京都下水道局に負うところが多いと思いますので、その点につきましては下水道局に申し入れしていきたいと考えています。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"初めに、戸越拡充幹線の整備というところなのですが、都の下水道局が、平成２５年の豪雨対策下水道緊急プランというもので、今、戸越の地域を５０ミリ拡充に位置付けたということから、それによって、ここに発生する浸水リスクというものの軽減を図るということで、この事業が行われる背景にあるということですけれども、この浸水リスクというものについて。","respondent":"和田河川下水道課長","answer":"このリスクといいますのは、基本的には東京都の区部の下水道は、時間５０ミリの降雨に対応できるように整備するということで整備を進めているものですが、戸越銀座のあたりとか西品川の通りにつきましては、戸越幹線は入っているのですけれども。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"ちょっと細かくこの事業のスケジュールなのですけれども、平成３２年度に、上流部というふうなことで、中原街道から西品川公園までの工事が、完成というのかな、されて、暫定利用というふうになっております。それをお伺いしたいと考えています。それから、もう一つ最後に、目黒川までのいわゆる本格対応というか、下流部が完成する時期が未定となっておりますけれども、この未定の理由についてお伺いします。","respondent":"和田河川下水道課長","answer":"当然ながら、今、三ツ木公園の下の貯留管とか上流部の貯留管しかないものですから、それに加えて貯留管ができる、それも大規模な貯留管ができるということですので、相当リスクは下がるわけなのですけれども、先ほど私が申し上げましたとおり。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問","question":"次に３３９ページ、密集市街地の整備促進にかかわるところだと思うのですけれども、ＵＲとの連携による木密整備ということで、協定に基づいて、ＵＲと締結した協定、豊町四丁目、五丁目、六丁目、二葉三丁目、四丁目、西大井六丁目の地区におけるＵＲとの連携によって、ＵＲがこの地域の用地情報の収集とか、またあるいは取得を行うことで、不燃化整備を図るということなのですけれども。","respondent":"寺嶋木密整備推進課長","answer":"ＵＲと昨年の１２月に事業協定を結びまして、今後、ＵＲが密集地域の用地取得を進めていくということで、そういった事業方針を持ったということを打ち合わせの中でお聞きしまして、区と連携して密集地域の解消に努めていきたいということで協定を結んだというものです。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"その辺についてお伺いしたいと思います。","respondent":"寺嶋木密整備推進課長","answer":"それで１点、ちょっと先ほど説明が漏れましたけれども、ＵＲと協定を結んだエリアが、まさに今ご案内いただいた、豊町、二葉、西大井。この地区においての事業ということで、まず来年度は実施するということで、複合的にこの地域の密集解消に資するものと考えております。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３３１ページの可動式ホーム柵の整備助成と、地域交通検討会の経費、コミュニティバスについて伺いたいと思います。それから２つ目は池上線なのですが、これは固定式のホーム柵がついていて、ホームドアの対象になっていません。池上線も可動式ホームドアにかえてほしいという働きかけを、区からもぜひしていただきたいと思いますが、いかがでしょうかということが２点目です。","respondent":"中村都市計画課長","answer":"中延駅の事故につきましてもですが、まず優先的に中延駅の整備を２０１６年、平成２８年度に行うですが、その後も引き続き品川区内を特に優先していただくように、またその中でも旗の台駅を優先していただくように。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域交通検討会についてですが、今年度は開かなかったのでしょうか。そして、区としてバスの事業者に協力を求めるということで、バスの増便や路線の増設を求めたが、多額の費用がかかるので、今の経営状況では難しいと言われているという答弁もされていますけれども、ということは、区としても、バス事業者がやってくれるなら、増便や路線の増設は必要だと考えているのかについてもお聞かせください。","respondent":"中村都市計画課長","answer":"今年度の地域交通検討会の開催状況ですけれども、今年度は０回ということで、これは、現在までにおきまして喫緊の課題というものが特になかったことが理由です。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者や高齢者などの交通弱者の移動する権利の保障というのは区の責務だと考えているか、そういう立場に立っているかということについては、改めてご答弁いただきたいと思います。私は、品川区の財政力からすれば十分可能だと思いますが、なぜ数千万円が出せないのかについても伺いたいと思います。","respondent":"中村都市計画課長","answer":"こういったバスの路線網を考えたときに、これは例えば既存の路線網におきまして１つの駅を増やしたときにこの金額ですので、それだけでは当然、要望には応えられないです。","id":"exchange-082"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は、３３０ページ、都市計画費の中からと、それから３３９ページ、都市計画費の４目、都市開発費関係、それから３４９ページ、住宅費の中から質問します。品川区として、まちづくりという意味で、こういう計画は立てていく考えがあるのでしょうかというのが１点。それから住宅費関係です。その中で、この部屋に関してなのですが、以前の部屋と比べてどういう形になっているのか。その２点を教えてください。","respondent":"溝口都市開発課長、矢木住宅担当課長","answer":"港区の取組み等もありますが、そういったものも参考にしながら、今後も低炭素まちづくりにしっかりと取り組んでいきたいと考えているものです。家賃関係ですが、現在、鋭意計算中でございまして、それを含めまして、５月竣工、６月入居に向けまして入居説明会のほうを居住者向けに開いていきたいと考えています。","id":"exchange-083"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、品川区でも、今、大崎、西品川の辺も大きな開発をやっている中で、この辺はどう考えているのか。今現在は、その辺も配慮はしているということでいいのでしょうか。今までの区営住宅というのは、浴槽はご自分で設置する。古い建物と新しい建物という差はあると思うのですけれど、この辺はどういうふうに整合性をとったらいいのか、その辺の考え方をお聞きしたいと思います。","respondent":"溝口都市開発課長、矢木住宅担当課長","answer":"これにつきましては、引き続き再開発事業の計画段階からそういった低炭素社会に向けての取組みというのは進めていきたいと考えているものです。ただ、年代も過ぎまして、昭和５８年に建てられました西五反田五丁目１３号棟・１４号棟以降は浴槽設置ということで、現代のような状況になってあります。","id":"exchange-084"},{"speaker":"鈴木（真）委員","kind":"質問","question":"低炭素のほうは理解はしました。ただ、そのことでちょっと気になっていたのが、歳入の中に、低炭素建築物新築等計画認定申請手数料、１１件、８万２,０００円という項目があったのです。これは個人の方が申請するという意味。その辺がちょっと意味がわからなかったので、それを教えてください。その２点をもう一回お願いします。","respondent":"鈴木建築課長、矢木住宅担当課長","answer":"お尋ねの低炭素建築物等の計画認定です。こちらにつきましては、平成２４年に、いわゆる低炭素法というものが施行されておりまして、基本的には、環境に配慮した高効率な建物を計画した場合は区として認定すると。このような負担がございまして、それよりは、また新たに入った方にご自身で、その時代に合った浴槽を入れていただくということが、総合的に言ってよろしいのではないかということで、このような形にしています。","id":"exchange-085"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"住宅のほう、お風呂場はやはり結構大きな金額になると思うので、そこら辺、これから何かいい方法を考えていただけないかなということで、これは要望します。現在まだその表示も出ていない中で、どうなっているのかを教えてください。","respondent":"溝口都市開発課長","answer":"ＪＲのほうでは、巨大な建物になりますので、そのガラを含めて搬出をどのようにしていくのか、また地下にはりんかい線が通っておりますので、その上の解体をどのようにやっていくのかといったところの検討に、ちょっと時間を要していると聞いております。","id":"exchange-086"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。やはり、交通の面を非常に気をつけていただきたいなと思いますし、これは全体についてはまた別の場で質問するつもりもありますので、広町のほうはそれで終わります。もう一つ、天王洲地区まちづくりという科目がありました。これは、どの辺の範囲まで天王洲として検討していくのか、その点で教えてください。","respondent":"溝口都市開発課長","answer":"今回、予算で計上しています天王洲周辺のまちづくりの検討の範囲ですが、東品川二丁目、まさに京浜運河に囲まれた、野球場を含めて、今、開発が既に進んでいる全ての区域を対象に、まちづくりの今後の活性化に向けて検討していくということで、予算計上させていただいています。","id":"exchange-087"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それで品川区に戻ってくるのかな。ですから、今後、あそこの中継所、何か品川区として考えていく場合、その交通アクセスの問題は非常に大きな問題になると思われます。橋を渡って、運河の高速側のほうに行かなくてはいけなくなってしまうと思うので、その辺も十分、今回なのか、また先のときなのかわからないのですけれど、この計画の中に含んで、頭に入れておいていただきたいのですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"東品川船舶中継所の跡地につきましては、今後の跡地利用を考える際にあわせて、どのような車のルートというのは、かなり開発していく上でも重要なところになりますので、しっかりそういったものを踏まえてまちづくりの計画を立てていきたいと考えております。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"３０９ページの交通安全啓発費ですが、何度かお願いしております、どうなったのかなという確認なのですが、３人乗りの自転車です。これは、ぜひ早く啓発をしていただきたいということを言っているのですが、どうなっているでしょうかということです。それから３３１ページと３５３ページに、東日本大震災支援費の中で、住宅原状回復費があります。品川区としてはどうしていこうとしているのかをお尋ねします。","respondent":"田口交通安全担当課長、矢木住宅担当課長、米田人事課長","answer":"実績ですが、昨年は１０回実施、保護者を含めまして約１,０００名の方が参加しています。東日本大震災支援費の被災者受入住宅費等のご質問です。この辺の取組みについては今後も継続的に続けていき、それで、現地に行った職員がさまざまな住民の方々との交流等を通して得たものを。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車の啓発ですけれども、１,０００名の方にということなのですが、本当にこれは罰金を取ってもいいぐらいだと私は思っているのです。本当に危なくて、やはり１,０００人でも少ない状況だと思うのです。その内容についてお聞きしたいと思います。いろいろなノウハウを持っておられるな、経験を持っておられるなと思いますので、この辺を防災上どういうふうに反映していくのかをお聞きしたいと思います。","respondent":"矢木住宅担当課長、米田人事課長","answer":"確認しつつ、十分、国および都の動向等を見きわめながらやってはまいりますが、難しい状況ではなかろうかと考えております。それで、あちらに行って、また環境もいろいろ違いますので、被災しているという現況の中で、また知識を得て、戻ってきたところが防災とも限りませんので、またそれを深めて活躍してもらおうというようなことで考えているものです。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"よろしくお願いします。被災者に対しましては、なかなか国の制度などもありますので、難しいところが多々あるかと思います。しかしながら、お一人お一人の現状もありますので、よくお聞きになっていただいて、品川区でできることをしていただきたいなと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"石田（し）委員","kind":"提案","question":"これは平時も災害時でもそういったことがあるかなと思いますが、そういった、現場に確認に行く際に、ＩＣＴを活用すると非常に効率が上がるということで、今、多くの自治体でそういったＩＣＴを活用して、実際に現場に行って写真を撮って、その場で送信して、役所とその場でコンタクトがとれる、情報交換ができるという意味では、非常に効率的になると伺っておりますが、その点。","respondent":"多並公園課長、和田河川下水道課長、矢木住宅担当課長、稲田道路課長","answer":"ただ、今後につきましても、公園の中にある立地ということを考えながら、より整備は進めていきたいと思っているところです。水陸両用車のご提案ですけれども、水陸両用車は、ご承知のとおり、スロープが必要だということと、それから今、江東区に１カ所、水陸両用車の。私からは、二葉三丁目と豊町五丁目の公園整備に空き家を活用してはどうかというご質問に回答します。土木全般、現場に出たとき、ＩＣＴ等々を使ったらどうかですが、現在は写真でメールを送るとか、そういう対応を実施しているところです。","id":"exchange-092"},{"speaker":"本多委員","kind":"質問","question":"３４９ページの分譲マンション実態調査業務委託について、２つ目は、３３１ページの都市計画総務費、やさしいまちづくり整備費について伺います。最初に分譲マンションの実態調査なのですけれども、マンションの課題につきましては、歳入の款別審査のときに沢田委員からも質問がありました。耐震性不足のマンションや既存不適格など、建替えが困難なマンションが多数存在する。","respondent":"矢木住宅担当課長","answer":"その中で課題について検証いたしまして、有効なものから実施していきたいと考えています。","id":"exchange-093"},{"speaker":"本多委員","kind":"質問・要望","question":"対策はわかりました。ぜひ目標に向かって、達成できるように進めていっていただきたいと思いますが、その中で、この１０年間の取組みの中での６つの目標がありますので、一つずつ取り上げて、その政策指標が出ておりますけれども、それに対して品川区のイメージですか、その辺をちょっと教えていただければと思うのです。","respondent":"矢木住宅担当課長","answer":"修繕積立金につきましての品川区のイメージですが、こちらは、まずマンションの実態調査ということで、実態を把握してからそれぞれを検討していくということで判断させていただければと思います。","id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"すみません。これから、そうですよね、実態調査をして取組みということですけれど、目標が６つあるので、１つずつ聞いていいですか。","respondent":"矢木住宅担当課長","answer":"都からの話によりますと、こういった管理状況報告制度を創設するという形で対応していきたいということがありますから、区といたしましても実態調査を含めた上で、この数値というのを定めていきたいと思います。","id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"６つの政策指標がありますけれども、それぞれ実態調査を把握していただいて、前向きに取り組んでいただきたいと思います。次の質問に移ります。次に、３３１ページの都市計画総務費のやさしいまちづくり整備費につきまして、「高齢者、障害者等を含む誰もが住み慣れた地域で安心して暮らすために、快適に行動できる環境と、やさしく触れ合いに満ちたまちづくりが求められています。","respondent":"中村都市計画課長","answer":"委員ご質問のとおり、品川区全域にかかる大きな目標です。","id":"exchange-096"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、全区的に対象だということで、品川区全域に対象という意識を持って、一つだけ地域を限定して聞いていきたいと思います。そういった、地域でも根強い声がありますし、そういったことを、やさしいまちづくり整備費の中で、そういった事業に考慮していけるかどうか、いかがでしょうか。","respondent":"中村都市計画課長","answer":"ただ、そこで区のほうでもお願いしておりましたのは、やはり今後、駅建替えですとか、そういったものを進めたり、あるいはバリアフリーの取組みを進める中でも、やはり許す限りの中で検討をまずしていただきたいということで、これは２年前、一昨年の話ですけれども。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３３１ページの特定整備路線について、補助２９号線の法的瑕疵問題について質問します。区役所前抗議行動が続けられておりますが、住民の会が今指摘しているのが、この法的瑕疵問題です。東京都は、戦後直後の昭和２１年４月２５日に出された告知１５号によって都市計画決定されたと説明しています。初めに、この決定をした戦災復興院総裁は誰ですか。伺います。","respondent":"中村都市計画課長","answer":"この補助２９号線の告示が昭和２１年４月２５日ですので、そういたしますと、そのときの戦災復興院総裁といたしましては、２代目の阿部美樹志氏ということになります。昭和２１年から昭和２２年にかけての就任です。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問","question":"当時の官報によりますと、今ご紹介がありました、昭和２１年４月２５日に、戦災復興院総裁、阿部美樹志と記されています。当時の旧都市計画法で告示ができる人物、すなわち決定できる立場にある役職とは何ですか。私が調べましたけれども、都市計画審議会を経て主務大臣の決定、そして内閣の認可を受けるという旧法第３条の規定に間違いないでしょうか。","respondent":"中村都市計画課長","answer":"旧都市計画法に基づきますと、委員ご指摘のとおり、「都市計画審議会の議を経て主務大臣、これを決定し、また主務大臣、これを告示し、行政庁をして関係図書を縦覧に供せしむべし」ということで間違いございません。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"先ほどの戦災復興院総裁は主務大臣なのか伺います。主務大臣の決定後、内閣の認可を受けた経緯はあるのか。伺います。","respondent":"中村都市計画課長","answer":"あと主務大臣の決定後の、内閣の認可を受けた経緯があるのかですが、これはまず私のほうでは、法律に関する客観的な事実につきましてはご答弁することはできますけれども、都市計画の事務手続の、国の内部の手続につきましては、今現在確認のしようもございませんので。","id":"exchange-100"},{"speaker":"のだて委員","kind":"確認","question":"確認ができないでは困ってしまいます。この決定が根本の問題になっています。この阿部美樹志氏、今ありましたとおり、大臣ではなく、有名な建築士、土木技術技師でした。大臣ではない、この総裁の告示に、都市計画決定の効力がどこにあるのでしょうか。伺います。この決定、内閣の認可があるのかないのか、改めて伺います。","respondent":"中村都市計画課長","answer":"それ以上はコメントすることはできません。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"戦災復興院は内閣の管理下にあるということでしたけれども、内閣ではないということだと思います。主務大臣ではないと。この大臣ではない総裁の告示に都市計画決定の効力があるのでしょうか。この点が法的瑕疵の一つです。内閣の認可を受けたという経緯、書類、そして図面もない。内閣の認可がないと、この都市計画決定は無効ではないでしょうか。伺います。","respondent":"中村都市計画課長","answer":"これに引き継がれているという考え方がありますけれども、これは最高裁の判決でも、有効・無効についてはいろいろありますけれども、こういった法律もあるです。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"今おっしゃいました許可認可等臨時措置法は、「大東亜戦争に際し」となっております。時限立法であると。近鉄特急料金訴訟の最高裁判決で、効力がないと判決があります。これは弁護士に聞くと、法曹界では常識と聞きましたが、効力がないとは本当でしょうか。伺います。","respondent":"中村都市計画課長","answer":"補助２９号線につきましては、昭和２１年に告示がなされて、また計画決定がなされたものが今日活きているということで、それについて、特にこの法律に関してどういった解釈であっても、その事実については、結論は揺るぎないものであると認識しております。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"平成４年まで存在していたと。そこで廃止されたということですけれども、存在していたからといって、効力があるわけではありません。この指摘について、区も詳細を把握すべきではないでしょうか。伺います。しかも、この７０年後に復活させるという。区議会の反対決議が３度も上がっているのに、住民の反対運動が続けられている中、進めるというのはおかしいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"したがいまして、この告示と事業認可、事業計画決定は有効という認識で、東京都も事業を施行しているものと思われます。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"現実的ではない、有効だということですけれども、これは手続がまず根本のところでしっかりとなされていないということです。その根本が、今回取り上げた法的瑕疵問題という重大な問題を抱えています。ここが不鮮明なまま計画を進めるということ、また濱野区長が都に補助２９号線の実施を求めたことはおかしいと思います。やはりこの点からも、とても進める状況ではないと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区といたしましても、防災性を配慮した上で東京都と連携して進めてまいります。","id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"それが１点。もう一つは、今、いわゆる大崎ニューシティ側と接続していないということで、当面の対応として、下の区道と階段で接続する予定と伺っております。今年度、設置した４つの橋梁名を教えてください。水辺の魅力づくりの視点から、この鉄道事業者へのアプローチというのはどういうお考えがあるでしょうかというのをお聞きします。これを確認させていただきたいと思います。","respondent":"溝口都市開発課長、稲田道路課長、和田河川下水道課長","answer":"そういったものも視野に含みまして、よりマンションが集まったところ、まちづくりとして対応できるところは対応していきたいと考えているものです。渇水期に工事ということで、まだ現場のほうには着工していませんが、年度中にはつけるという予定で今進めております。この辺がどのように効果的であるかというのは検証する予定でありますけれども、その結果を見て連携して。","id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"こういう、道路や公開空地を有効に活用できるような規制緩和の仕組みが、今、メニューがありまして、せっかくのデッキ、桜の季節のお花見とか、夏のビアガーデンとか、冬は近くでイルミネーションもありますので、ぜひこういう規制緩和の手法を使って、デッキを有効に、多くの方に活用していただきたいなということで、質問をお尋ねしたいと思います。それと、分譲マンションのほうは、わかりました。","respondent":"溝口都市開発課長","answer":"つながった暁には、当然、６ｍの有効空地があるようなデッキができますので、さまざまなイベントのときに連携した形で、一つのバリアを超える橋としてつくっておりますので、イベントもバリアを超えて複数連携して、地域一体となったイベントが打てるような。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３０９ページ駅周辺の放置自転車の対策、それから、あと３３７ページ、市街地整備事業、広町地区整備検討委託、それから３４９ページ、空き家等対策事業についてです。広町２丁目の、先ほどほかの委員からも質問がありましたが、広町地区整備検討委託のところなのですが、解体、ここの取り壊しが８月というお話がありました。その中で劇団四季は今後どのようになるのかを含めてお願いいたします。","respondent":"溝口都市開発課長","answer":"来年度、平成２８年度につきましては、それをより具体化に進めていくために検討費など定めておりまして、できれば都市計画の素案といったものも、まとめられるのであればまとめていきたいとは考えておりますが、何せＪＲの、相手もある話ですので。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、粗々お話しいただいたのですが、取り壊した後に検討という形で並行して進んでいくのだと思うのですが、全体像がなかなかうまくまとまらない状況ということであれば、ＪＲの取り壊した土地を何らかの形で、区のほうで暫定的に一部分でも、何らかのアイデアを出してお借りしながら、長いスパンではないにしても考えるということについてはいかがでしょうか。","respondent":"溝口都市開発課長","answer":"今回、社宅の工事につきましてはＪＲが行う工事になりますので、当然、既存の保育園または周辺の方々、また四季にご来場されるお客様は、そういったものの配慮も含めてしっかりと検討してくださいという要望をしておりますので、またそういったものを含めて、今現在。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひとも安全確保をお願いします。それから、暫定的なという、もしというお話がありましたが、担当といいますか、区全体の中からアイデアを募って、ぜひ今後の需要に合った形でさまざまな方策を施していただきたいと思います。そして、その自転車をどこにとめて通勤されるかなどを考えますと、この周辺、一番近いところの大井町駅西口の保育園、当日利用は９１％、もうほぼ満員という形になります。","respondent":"今井待機児童対策担当課長","answer":"今後、また年齢が進みますと３００人規模まで拡大してまいりますので、状況を見ながら検討してまいりたいと考えています。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問","question":"とするとなかなかそういう質問がなかったということですが、今お話があったように、年代が、５年の間にはベビーカーから自転車という形になる方も増えてくると思います。そこで、駐車場、駐輪場の大井町駅、現状ではおそらく厳しい状態になるかと思うのですが、今後の大井町駅近辺の駐輪場の整備についてどのようにお考えでしょうか。","respondent":"田口交通安全担当課長","answer":"大井町駅周辺は、非常に利用率も高いです。本来早急に整備が必要ですが、いかんせん土地がないという状況ですが、引き続き誠心誠意、少数でも停められるという場所でも探して、順次、整備のほうを検討していきたいと考えています。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、今年の８月に取り壊しが終われば、ＪＲの社宅跡も少しは土地があるのではないか。その内容をお聞きしたかったのですが、時間がなくなったので、それも含めて、今後、先ほどお話があったように交通安全の徹底と広町の保育園ができたときの、そういった駐輪場のことなどをぜひ検討して、問題ないように進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"私は、３３３ページ、しながわ水族館に関連して、それから３２１ページ、立会川雨水放流管工事に関連して、それから３２７ページ、立会川河口部整備検討経費について質問します。初めに水族館ですけれど、これはオークランドのケリータールトンズ水族館をモデルに建設されたと聞いています。当初、展示施設とある以上は、常設的な内容のままでは、利用者に飽きられてしまう。お願いします。","respondent":"多並公園課長","answer":"運営の収入につきましても運営事業者のほうに入っていくということで、企業努力が見込めると。３つ目としましても、広報活動等につきましても事業者が行えるということで、民間事業者がメリットを享受できるような形の運営形態というところだと認識しています。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私たちはこのときに、水族館の抜本的な見直しを求めました。そういう品川区、それからサンシャインとしての活動の記録というのは、全国自治体のモデルとなると思うし、それから企業と行政の新しいコラボレーションの形を示してつくってきたわけでありますから、ぜひ２５年の記念の事業の一環として、そういう計画をまとめて、それから全国に発信していくなり、新しいことを企画したらどうでしょうか。","respondent":"多並公園課長","answer":"２５周年の事業の中で、今の委員のご提案のとおり、やはりほかの自治体も含めて、こういう形で今まで進めてきたということはＰＲしながら、今後のオリピック・パラリンピックに向けた一つのきっかけというところの弾みにしていきたいなと思っているところです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"だから、この水族館を起点として、いろんな絵が描けていく施設だし、ましてや品川区を代表する施設であると私たちは思うので、ぜひ区長にお答えをお願いしたいのですけれども、しながわ水族館の将来像なり、それからこれからの将来構想等について、ぜひご答弁をお願いいたします。","respondent":"濱野区長","answer":"それで、今、こういう事態になっているわけでありますけれども、これが果たしてどこまで続くのかということは、しっかりと考えていかなければならないですし、施設の老朽化というものも、あわせて進んでまいりますので。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"意見","question":"これは、地域の住民の方々は浸水対策として早期完成を当然望んでいるわけでありますが、当初の計画では平成３０年夏頃に完成予定でありました。都民であり区民である方々に対して、やはりもっと品川区は東京都に物を言うべきであるだろうし、それから東京都が品川区に対してどう思っているのだろうかという疑問がありましたので、河川下水道課長でしょうが、ご答弁をお願いいたします。","respondent":"和田河川下水道課長","answer":"これについては、当然、遅延の長さもそうですけれども、報告が遅いということで抗議を申し上げましたし、また遺憾の意を伝えたところです。これからも区としましては、東京都と良好な関係は維持しつつ、言うべきことは言っていきたいと考えています。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"質問・要望","question":"特に私としては、この地域に近いものですから、過去に水害がたくさん起きたし、だからこそ放流管工事を望む声がたくさんあった。だけど、もう少し早く品川区に伝えてほしかったなという気持ちがありますので、そのことを指摘すると同時に、改めてもう一つは、立会川の津波対策のための水門設置についても、これもさまざまに私ども地元から要望していますけれども、今の現状はどうでしょうか。","respondent":"和田河川下水道課長","answer":"これにつきましては当然、下水道局に、抗議の内容の中に含めて遺憾の意を伝えたところです。一日でも早く、２年といわず少しでも早く下水道管工事を完成させるように、今後も申し伝えていきたいと考えています。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問","question":"だから、それが２年遅れるということは、いろんな事業に影響があるということなので、これはここで言っても何も始まらないかもしれないけれども、やはりそれは品川区としてはきちんと東京都の担当の部局に意見を伝えていただいて、２年と言うけれども、それはなるべく早く対処していただいて、雨水放流管工事もそうだし、その後の立会川の水門整備にさらに加速していっていただきますようお願いしますが。","respondent":"和田河川下水道課長","answer":"区民の皆様のご心配をおかけしていることとご迷惑をおかけしていること、本当に下水道局になりかわりまして申し訳なく思っております。委員ご指摘のとおり、今後も一日でも早く、２年といわず少しでも短縮できるよう、下水道局に伝えていきたいと考えています。","id":"exchange-118"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは、前に聞いた説明では、立会川河口部の立地状況や、そのほかのさまざまな現状を調査していくふうにお伺いしました。だから、そんなことを考えていくと、この立会川河口部整備検討というのが、何というか、いろんなところから視野を持っていって、立会川の河口部の整備を検討していかないと、いろんな要望に応えられないと思うので、今の現状の整備検討のお考えをお聞かせください。","respondent":"和田河川下水道課長","answer":"しかしながら、委員ご指摘の視点は重要なことと認識しますので、その点も含めて検討してまいりたいと考えています。","id":"exchange-119"},{"speaker":"伊藤委員","kind":"意見","question":"特に後半の部分が非常に重要だと私は思います。まとめていきますけれど、水辺の利活用や、それから浜川砲台も含めた観光の面、それから、あと地域の方々の意見も一部あります。そういうさまざまな物事をしっかり捉えた上で、将来に向けて立会川をしっかり検討していっていただきますようお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"いながわ委員","kind":"質問・要望","question":"要は並行に建っているというのですかね。ずれてはいるのだけど、車１台分もないずれ方をしているというケースがあって、非常に交通の利便性も悪くなるし、事故も多く、ぶつけるというケースもあるのですが、そういった部分、東電とかＮＴＴ、電柱の管理者にはどういったお話をして移設を求めているのか、今でも大分、品川区にあろうかと思いますので、その辺をお聞かせください。たしかそんな答弁。","respondent":"鈴木建築課長、稲田道路課長、多並公園課長、寺嶋木密整備推進課長","answer":"私からは、区道の細街路セットバックに伴う電柱移設についてお答えします。それから今後におきましては、非常に高額、それから時間がかかるというところでございまして。水族館についてのご質問ですけれども、まずバーベキュー場との連携というところですけれども、今度。それで、経緯としましては、地区計画導入につきましては、行政と地域との話し合いということで進めていくという基本的な考え方がございまして。","id":"exchange-121"},{"speaker":"いながわ委員","kind":"質問・要望","question":"電柱に関しては、鋭意しっかり調整して、なるべく真ん中に来ないように、すれ違いできるような形をとっていただきたいと思います。もっと言うのだったら、これは要望ですけれど、水族館のバスにも「わ！最低敷地に関してなのですけれど、確認なのですけれど、例えを出して話すのであれば、例えば５０m2未満の土地を持っている人がいます。しかし、買った人はそこに家を建てることができるのかどうなのか。","respondent":"寺嶋木密整備推進課長","answer":"あくまでも分割に対するルールなので、面積を変えない限りは、売却した後の建設も可能です。","id":"exchange-122"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それを聞いて、ある意味、安心しました。この地区計画に対して、私は賛成のほうなのですけれど、僕も今までの質問の中で密集の再来だと言って、例えば１００m2あったところに３棟も建ったら、区が一生懸命、密集市街地の整備をしようという反面、また密集が増えているではないかということもずっと質問してきましたので、あえて確認のために、今、質問させていただきました。","respondent":"多並公園課長","answer":"遊具につきましては、地元の利用者のご意見をお伺いしながら、利用実態に合った形で選定しております。事故につきましては、よくあるのが、ちょっと壊れているということでお問い合わせいただいて現場に行きまして、それを早急に直するということは今年も何件かございました。","id":"exchange-123"},{"speaker":"いながわ委員","kind":"質問・要望","question":"子どもたちが集う場所、遊ぶ場所でありますので、そういった点検もしっかり行っていただきたいのが１点と、あと公園を使うに際してのルールが、何げにキャッチボールをしてはいけませんとか、そういうのがあるのですけれど、遊具を利用する際の注意事項というのですか、例えば滑り台を逆さから上がっていってはいけない、下から上に行ってはいけないとか、あと上でたむろって。","respondent":"多並公園課長","answer":"点検につきましては、年に１回、必ず行いながら、あとは巡回でも行っています。ルールについては、いろいろなことがあれば、それについては看板を設置するなど対処しています。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、３４７ページ、品川シェルター、それから住宅耐震化について、それから３４９ページ、住宅まつりについて伺いたいと思います。しかし、平成２７年の実績は１件と伺ったのですけれども、この木造住宅に住む高齢者、障害者、低所得者などを対象に全額助成されるという、とても使いやすい事業だと思うのですけれども、なぜ進まないのか、理由をどう考えているかお聞かせください。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、平成２７年度、今年度になりますが、今のところ実績１件です。非常に持ち出し、全額ほぼ区の負担でというところと、工期も短いというところと、引っ越しもないというところで、非常にいいものとしてＰＲはさせていただいているところです。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も、圧迫感を覚える、そうした形が嫌だといった声も受けるわけですけれども、しかし設置した方からは、命を守るためと思うとそれらは気にならない、とても安心ですという実感が寄せられています。そして、やはり工夫が必要だなと私も思いました。周知について、またこういったチラシについて、新年度の工夫はあるのかどうか伺いたいと思います。","respondent":"鈴木建築課長","answer":"防災体験館が今度新しくなりますけれども、こちらのほうには模型とともに、新しくつくり直したチラシも含めてＰＲしていきたいと。来年度の話ですが、ケーブルテレビ品川のほうでもコマーシャルをつくって積極的にＰＲをしていきたいと考えています。","id":"exchange-126"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひＰＲを進めていただきたいなと思います。そして、今回の予算書に、耐震シェルターという項目がなくなっています。耐震シェルター設置支援の中に品川シェルターが入っていると思うのですけれども、品川シェルターだけになっているのですが、これはなぜか伺いたいと思います。","respondent":"鈴木建築課長","answer":"品川シェルターとともに耐震シェルター、今年度まで実施しておりましたけれども、耐震シェルターというのは基本的には、民間が開発したものについて一定助成を行ってきておりました。","id":"exchange-127"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国の補助がなくなるから廃止したということでしょうか。ぜひ残すべきだと思うのです。住宅を耐震改修させるだけの力がない世帯。命を守る事業として必要だと思います。ですので、やはり命を守る事業として必要だと思うので、ぜひここは残すべきと求めたいと思います。品川区としても、こういったことを取り入れるべきだと思うのですけれどもいかがでしょうか。","respondent":"鈴木建築課長","answer":"やはり区としては非常にいいものとして今後もＰＲを積極的に行っていきたいというものです。それから、今いただいた耐震指標１.０に満たないものについての助成ですが、基本的には木造の耐震補強における耐震指標１.０の考え方は、もう確立されたものがあります。","id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、こういった耐震化をいち早く進めていく。そこに大きな障壁となるこの評点１.０、また改修費用がかかる。そして、ちょっと時間がないですけれども、住宅まつりについて伺います。建設組合、４組合から、毎年、住宅まつりへの助成額増額が求められていますけれども、区として住宅まつりについて、そして助成額の増額について、どのように考えているか伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"こちらは毎年、西大井広場公園を会場として、品川区住環境改善協議会が開催しているものです。私も毎年行かせていただいておりますが、建て前をはじめとして、くぎ打ち体験ですとか、包丁研ぎですとか、いろいろ工夫をされていることは認識しております。","id":"exchange-129"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、３１５ページの道路空洞調査修繕、それから３４１ページの不燃化１０年プロジェクト、３４５ページの建築物耐震化支援費に関連してということで伺います。初めに道路空洞調査修繕ですが、代表質問でも取り上げさせていただいて、３年間ですぐ修繕が必要な箇所で、２８カ所発見されて補修済みと。区内に６０ｍ以上の建物が何棟ぐらいあるのか、あわせてお知らせください。","respondent":"稲田道路課長、寺嶋木密整備推進課長、鈴木建築課長","answer":"この業者の選定方法ですが、この技術が２０年来の技術を持っているというところと、そういうところでございまして、実績のある業者。その他についても、今後、都費の対象になるように、東京都と協議を進めていきたいと考えておりますが、現在は単費ということで予定しております。基本的に周期といいますと、一般的に揺れが１往復するのにかかる時間というところでございまして、東日本大震災以降、国のほうで南海トラフを想定して。","id":"exchange-130"},{"speaker":"たけうち委員","kind":"確認","question":"いわゆる非破壊で調べないといけないということで、実際には調査が行われたときに、それが、では例えば何カ所ありましたよといっても、それをなかなか区のほうで確認できない。極論ですけれど。それで、都内のほかのところでも、全くの価格だけの競争ではなくて、そうした技術の評価を入れてやっていくということを選定法をやっているところがあるのですが、これについての感想を教えてください。","respondent":"稲田道路課長、寺嶋木密整備推進課長、鈴木建築課長","answer":"今後なのですけれども、事業を実施する中で、技術力の状況など確認しながら、動向を注視しながらやっていきたいと考えております。区民の方からお問い合わせがあった際の対応、それからＰＲということで、実施時期等も想定されたご質問と受けとめておりますけれども。しかしながら、今回示された大規模な地震波についても、この案ではしっかり検証して診断をして。","id":"exchange-131"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから１０年プロジェクトについては、本当に知らないで家を建ててしまったと。それで、国のほうでも補助制度も新設するようなことも、るる情報も出ていますけれども、そうしたのを注視していただきながら、今、既存のある耐震診断とか、改修のいろんなスキームがありますけれど、新しい国の制度も使いながら、しっかりした対応をぜひお願いしたいと要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"４点お聞きしたいと思います。１点目です。４.５ｍ、どうしても欲しいのですよということで、それには線路を動かすわけにいかないので、新しい材質によってガードを細くするか、下を削らないといけないというようなお話を伺っていたのですが、この４.５ｍをとるためにどのような工事をするのかということ。５００万円というお金ですけれども、どんなことを検討されていくのかをお聞きしたいと思います。","respondent":"稲田道路課長","answer":"桁の高さの関係、４.７ｍ確保できるというところで現在なっております。道路の高さ、それから桁の下端の高さを詳細に検討したところ、４.７ｍでいけるというふうに結果が出ております。それから、今後の検討費です。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"あれを広げるというのは大変なことですので、できるだけ早く、補助１６３号線も全線開通するようによろしくお願いしたいと思います。今度改めて工事ができるということで、これは大変に喜んでいるのですけれども、この工事が内径３.５ｍ、延長２.５ｋｍ、大変に大きな工事なのですけれども、これが貯留管ではなくて、戸越下水道幹線となっているのですけれど、これはどういうことなのでしょうか。","respondent":"和田河川下水道課長","answer":"これは、塚本委員のご質問に答弁したとおり、貯留管ではなくて、目黒川へ雨水を排水できる排水管です。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"今の立会川と同じように、あふれたら、いわゆる、し尿がそのまま目黒川に流れるということではないですか。今現在つくっているのよりも大きな貯留管ができるわけですから、相当数、５０ミリ、６０ミリぐらいの対応もできると思うのですけれど、下水をそのまま目黒川に垂れ流す、しかもそれが、どこですか、あの橋のところなど相当、雨が降ると水かさが上がります。目黒川も戸越幹線も同じ雨が降るのです。","respondent":"和田河川下水道課長","answer":"それを超えた分だけが雨水排水管に入り目黒川へ放流されるということですので、そのまま汚い汚水が目黒川へ排水されるということはなくて、この戸越拡充幹線には、基本的には雨水のみが入っていくというような計画になってあります。","id":"exchange-135"},{"speaker":"松澤委員","kind":"確認","question":"雨水だけが流れていくのだったら、下水が基本的には流れていないという確認でよろしいでしょうか。","respondent":"和田河川下水道課長","answer":"ここで、ないと言ってしまうと、うそですので、薄まった汚水が流れてしまう可能性はあるかもしれませんが、どかんと雨が降ったときは流れる可能性はあるかもしれませんけれども、通常の雨、通常の強い雨の場合は基本的にはないと答弁しておきます。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"西品川公園から目黒川までは未定ということになっているのですけれど、こういう話ですと、私は未定のままがいいと思う。そうすれば、暫定貯留管で使えるのですから。そのほうが私はいいような気がいたします。３点目です。これは、なぜこの地が選ばれたのでしょうか。ここがにぎやかだからなのでしょうか。あるいは公園があって待合所ができるからなのでしょうか。その点についてお聞きしたいと思います。","respondent":"和田河川下水道課長","answer":"これは、今年１月に発表されました、河川部が発表しました防災桟橋の計画によって、防災桟橋として位置付けられたものです。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"別にここにつくられたのを云々というわけではないのですけれども、この上流の荏原青果市場の跡地に市場橋というのがあるのですけれど、そのたもとに石づくりのはしけの発着場があるのです。現在あるのです。しかも目の前が桜の名所ですからね。何でここを検討されないのか。この思いが一つと、今後ここの利用計画、何とかこれを使おうという思いはないのでしょうか。それも聞きたいと思います。","respondent":"和田河川下水道課長","answer":"今回、五反田リバーステーションの計画地は、背面に、大崎橋広場・児童遊園がありますので、そこをスロープとして活用することによって、身障者の方も乗り降りできる桟橋ができるということで設定させていただきました。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"４点目に入ります。公園が運営について管理するということなのですけれど、あそこはやはり防災ということで１００トンの防火水槽があったり、いろいろあるのですけれど、何といってもあそこには消火栓を入れてあるのです。これはもう、開放のときに期間を何カ月前ということで切ればいいわけですから、そのような形で防災行事優先にしていただきたいと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"このような形で、開放後は防災課とよく連携しまして、スタンドパイプの訓練だとか、有効的な活用ができる公園だと考えていますので、しっかり進めていきたいと思っているところです。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"防災の拠点として本当にすばらしい訓練ができる場所ができたなと思っていますので、よろしくお願いします。それと、下段のほうに、子どもたちの優遇施設がありますけれども、上のほうで防災訓練で全面使っている場合でも、あそこは子どもたちは脇から通って行けるようになっているのですよね。その点を１つお伺いしたいと思います。","respondent":"多並公園課長","answer":"遊具の件は、少し斜面を使った遊具もありますので、そこをご利用いただくところはありますけれども、区切った形で、そこは連携を図れるかなとは思っております。今後については、細かい利用については調整させていただきながら進めたいと思っているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"私は、３３３ページ、しながわ水族館運営についてと、３３９ページ、都市防災まちづくり事業についてお聞きしたいと思います。しながわ水族館運営ですが、この中にイルカショーがあります。したがって、水族館での自前での繁殖しか、これからイルカは入手できないということなのですが、この点に対して今後どうするのでしょうか。見解をお聞かせください。","respondent":"多並公園課長","answer":"今後につきましても、このような形で魅力あるショーを継続するために、今のイルカを大事にしながらショーを継続してまいりたいというところは、サンシャイン、運営している企業のほうにも確認しています。","id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"今お話を聞きましたが、イルカは生まれた子が親になるまで１０年かかるというのです。日本全国の水族館がそういう形で共鳴しているということは、もう品川区も今後、水族館をこれから改修工事をするならば、３０億円かかるのかどうかわかりませんが、それに匹敵する金額になると思います。ですが、もう品川区の役割は終えたのではないかなという気もするのですが、ちょっと見解をお聞かせください。","respondent":"多並公園課長","answer":"特にイルカは飼育は難しいということで、今の、先ほど、しながわ水族館生まれのイルカがいるとお話しさせていただきましたけれども、今ちょうど１９歳ということです。まだ元気にもちろんショーをやられているということで、大体イルカの寿命は４０歳ぐらいと言われています。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"今お話がありましたが、専門家がやはりそれぞれの見解を出しています。科学的な、そういう実証もされているということなので、私は考えていただきたいと思います。次に、都市防災についてお聞きしたいと思います。これは、品川区ではさまざまな資料を区民に渡していますが、こういうことは記載されているのですか。ちょっとすみません。私もよく読んでいないのでお聞かせください。","respondent":"鈴木防災課長","answer":"ご質問いただきました、『東京防災』に載っている地震保険等についての情報ですが、品川区のほうで作成して配布している『我が家の防災ハンドブック』とか防災の啓発資料に関しては、地震保険についての説明等は現在載せていないところです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"そういう話があります。ですから、少なくとも被害額をカバーすることができる手法である地震保険等の説明だけでも、私は記載することが必要だと思いますが、どうですか。ちゃんと東京都は、全都民に対して、『東京防災』というハンドブックを出して、皆さんもこれに気を付けてくださいよという警鐘を鳴らしているわけですが、何で品川区はできないのですか。お聞かせください。","respondent":"鈴木防災課長","answer":"今までの啓発で、ご指摘のとおり地震保険についてはお伝えしておりませんが、委員ご指摘のとおり、自助の備えという一つの中に地震保険も含まれると思いますので、今後改訂する『我が家の防災ハンドブック』や、それからさまざまな啓発の中で。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問・要望","question":"わかりました。区民のやはり再建ということを私は考えていただきたいと思います。次に、都市防災の根本的な問題である、発災時の警報システムである屋外スピーカーについてですが、これは警報音ですか、聞こえない、緊急放送も聞き取れない地域が多くあります。このことはどういうふうにお考えになっていますか。そして、これに対して何か対策は考えていらっしゃいますか。","respondent":"鈴木防災課長","answer":"それから国のＪ－ＡＬＥＲＴというように、さまざまな情報を、文字だけでなく音声、また区の広報車も含めた直接の呼びかけも含めて、そういう対策を講じる中で、区民の方への必要な情報提供、また安全確保を図りたいと考えております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから大変ではないですかということで、都市防災のほうからお聞きしているのですが、実際、今、自衛隊の駐屯基地でもそうですが、現在、警報音、もちろんありますよね。そういう警報音は、今の品川区みたいに小さいのですか。そして、全隊員が即座に緊急情報を共有する仕組みは自衛隊もつくっていないのですか。だって、初動体制で全くわからない。こんな仕組みでいいのですか。そんな状態でいいのですか。","respondent":"鈴木防災課長","answer":"それからテレビ、ラジオ、そのどれかで区民の方が情報を察知していただくというのが基本になると考えております。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"意見だけ言わせていただきます。実際、小さなお子さん、お年寄り、働いている人、買い物に行く人、みんなさまざまですよ。テレビを見ていますか。それで、その人たちがメールを見れますか。ケーブルテレビを見れますか。ずっとこうやって毎日見ているのですか。こんな仕組みだったらやる必要がないじゃないですか。こんなことではしようがないのではないですか。と、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"あべ委員","kind":"質問","question":"私は３０９ページの自転車駐車場、それから３１９ページの歩道整備、３３７ページの子ども達のアイデアを活かした公園、そして大崎駅周辺を中心とした再開発事業についてもお伺いしたいと思います。駐輪場なのですけれども、バイクがとめられる駐輪場もあるのですが、ここの出入りなのですよね。今後もずっとその形になって、いわゆる簡略化した形になっていくのか、その辺の考え方を教えてください。","respondent":"田口交通安全担当課長、稲田道路課長、多並公園課長","answer":"駐輪場からバイクに乗ったまま歩道を通行するということで、区のほうはそういったことは認識はしてございません。狭い歩道でも、これはもう、どうしても歩道の幅というのは、道路の幅が決まっていますのでなかなか改修はできないのですけれども、その段差とか。それで、いろいろご意見をいただいて、またいただいたご意見を踏まえて実施設計を進めて、具体的な内容をまたご説明すると。","id":"exchange-148"},{"speaker":"あべ委員","kind":"質問・要望","question":"バイクのほうですが、ぜひ現場をしっかり見てください。私も何人か周りの方に聞きましたけれども、実際、危ない思いをしたという方だけでも複数いらっしゃいましたので、ぜひ確認して対策をよろしくお願いいたします。それから再開発事業のほうに質問を移します。そのことが私はどうしても理解できない。そして、ぜひ実現に向けてさらに一歩、進めていただきたいと思いますが、区のお考えを教えてください。","respondent":"溝口都市開発課長","answer":"お一つ、一方でのお話になりますが、やはり五反田駅周辺のまちづくりについては、非常に大切なまちづくりを行っていただくところの会社ですので、そういったところについては、引き続きまちづくりをしっかり進めていただけるように進めていくというのが。","id":"exchange-149"},{"speaker":"あべ委員","kind":"質問・要望","question":"時間がないのですが、両方、まちづくりがうまくいくのであれば、それは応援しますけれども、本当に一緒にまちづくりをやっていける相手なのか見きわめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"飯沼委員","kind":"質問","question":"３３７ページの市街地整備事業費、再開発についてです。続いて、３３５ページ、しながわ中央公園拡張整備についてお伺いいたします。２０１１年６１億円余、目黒駅と西品川が始まっています。２０１２年３０億円余、武蔵小山が始まっています。２０１３年９３億円余、品川駅南の地域が始まっています。これが１点目です。再開発への税金投入の考え方を伺います。１３億円も増えた理由を伺います。","respondent":"溝口都市開発課長","answer":"それに合わせた形での補助金の増額になっておりますので、一定補助率というか、大体、区内でいきますと１４％ぐらいになりますが、その補助率を上げてまで補助を増やしているという形ではありません。","id":"exchange-151"},{"speaker":"飯沼委員","kind":"確認","question":"過去最高の２３６億円であることを確認させていただきました。なぜなのでしょうか。区民の皆さんに、これだけ税金投入をしていることを周知し、意見を聞き、まちづくりに活かすべきと思いますが、いかがでしょうか。これが１点です。予算の使い方。これはどういうことなのか、評価を伺います。そして、住宅の耐震、そして不燃化、公園づくりなど、予算の増額をすべきと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"それぞれの予算につきましては、それぞれ必要な予算を計上して動いてきていると考えておりますので、再開発だけが予算が多くて、ほかの予算が少ないから何もやらないというわけではなくて、総合的な判断の中で、再開発事業もありますし、木密。","id":"exchange-152"},{"speaker":"飯沼委員","kind":"質問","question":"意見のところなのですが、まちづくりのマスタープランもそうでしたけれども、区は区民の声を聞く。聞くところで終わっているのですよね。私は、区の姿勢にずっと貫かれていると思うのですが、区民の反応についてどう考えていらっしゃるのでしょうか。高さ制限を設けてほしい。環境悪化、超高層ビルはもうこれ以上要らないといった声が大変多いのですが、この辺に対しての見解をお伺いします。","respondent":"溝口都市開発課長","answer":"ただ、総体的にまちづくりを進めていく中で、品川区がより発展していく。そういったところの中での区民の方々のご理解というのは十分いただきながら、まちづくりを進めてきていると考えているものです。","id":"exchange-153"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多額の税金を投入する事業なので、一方的に進めないでほしい。私はこれは区民の声であると思っています。国の税金の使い方も私は間違っていると思います。東日本大震災から丸５年がたちました。今も１０万人の方が避難生活に苦しんでいますし、不便な仮設住宅を出る見通しも立っていません。被災地の復興を進むように、国の財政支援を強く求めるべきと考えますがいかがでしょうか。","respondent":"溝口都市開発課長","answer":"国のほう、国土交通省のほうでは、全体的なバランスを見ながら配分をかけていくというふうに考えておりますので、一概に再開発事業だけが手厚くなっていると実感しているものではございません。","id":"exchange-154"},{"speaker":"飯沼委員","kind":"質問","question":"再開発に、とても手厚い国の補助が出ていると思います。国の税金、国民の税金ですから、願いにかなった使い方を、ぜひ国も自治体もしていかなければいけないと思います。ヘリポートに移ります。防災にも触れます。よろしくお願いします。公園の整備、具体的に向かっていますけれども、拡張整備後の使い方についてお伺いします。公園として日常的な使い方、あと災害時の使い方もお伺いします。","respondent":"多並公園課長","answer":"ＪＴ跡地の拡張整備後の利用ですが、さっきちょっとご説明させていただきましたけれども、公園の利用ということで、遊具等ありますので、平時は皆様、お子様が遊んだり、あとは広場の中で遊んでいただいたり、憩っていただいたりという日常の使い方です。","id":"exchange-155"},{"speaker":"飯沼委員","kind":"質問・要望","question":"計画をぜひ取り込むべきであると思っていますが、その辺１点と、あと、ぜひご答弁をいただきたいことが１点あります。確認ですけれども、自衛隊への要請は東京都知事の要請に基づくものであると確認していますが、この点はいかがでしょうか。","respondent":"鈴木防災課長","answer":"ただいま都のほうで、災害時の拠点となる場所のヘリを含めた使い方についても新たな検討も始まっておりますので、その結果も踏まえながら、区のほうにも適切な表現、記載をしていきたいと考えております。それから２点目、自衛隊との連携とのお話です。","id":"exchange-156"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ誤解のないようにしていただきたいなと思います。連絡をスムーズにしていく意味での役割は十分あると思いますが、この点に関してはしっかりとルールを守るといった立場、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"浅野委員","kind":"質問","question":"それと３４１、３５１ページ、時間があればですけれども、電波障害対策費について質問します。最初に、親子自転車交通安全教室ですけれども、１回当たり大体何人ぐらい参加されるのかということと、今年度どのぐらいの人数の方が参加されたか教えてください。この安全教室の中で、自転車の保険についての話とか、またそういうＴＳマークの話とかもされているのかどうか教えてください。","respondent":"田口交通安全担当課長","answer":"１回の参加人員ですが、これはまちまちです。今年度の実績で言いますと、５０名から、多いときは２００名という実績があります。今年度、トータルで９６７名の参加があります。それで、この安全教室の中で、例えば保険の話だとかしているかですが、その辺は周知しています。","id":"exchange-158"},{"speaker":"浅野委員","kind":"質問・要望","question":"周知されているということですが、ＴＳマークのほうはどのぐらい区内では、浸透しているというのでしょうか、マークをつけている人というのはいるのかということについて教えてください。このような対応もぜひとも教えていっていただければと思います。このようなことはこれまでもやってきたのか、それともこれからなのかということについて教えていただきたいと思います。","respondent":"田口交通安全担当課長","answer":"それと、ＴＳマーク以外にも現在、自転車保険にはいろんな保険があります。これにつきましても安全教育等の中で周知を図っているところです。あわせてホームページ等でも紹介しています。","id":"exchange-159"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも保険については力を入れていただきたいと思います。次にいきます。これは、今から七、八年ぐらい前でしょうか、木製の遊具が古くなって、ちょっと危ない状況もあったということで、新しい遊具がその当時、入れられたと思います。たしか区のほうで、３種類ぐらいでしたか。Ａ、Ｂ、Ｃだったと思います。こちらのほうについても、しっかりと継続していただけると思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"今のはしっかり確保しなければいけないと考えていますので、そういう点も踏まえながら、今後、地元と調整しながら進めてまいりたいと思っているところです。","id":"exchange-160"},{"speaker":"浅野委員","kind":"質問","question":"当然、保育園ではなくて幼稚園の園児だと思いますけれども、危険とスリルと、あとは危険に対する能力を養うという意味では、さまざまな場面に遭遇するのが一番いいかと思いますけれども、けがをしたとなると、ちょっとこれは非常に私も気になっているところではありますが、ではこれは撤去するのかといいましたら、やはり人気のあるというところで、何らかの形で残していきたいとは思うわけですが。","respondent":"多並公園課長","answer":"それで、今後のこの公園につきましても、そういう部分はしっかりもう一度再検証させていただいて、お子さんが安全に安心して遊べる公園ということを目指すように進めてまいりたいと思います。","id":"exchange-161"},{"speaker":"浅野委員","kind":"質問・要望","question":"民間の危険な擁壁・崖に対策するため、助成制度が、こちらのほうにつきましては、私どもも公明党としまして助成制度を設けるように要望しているわけですが、この件につきまして、今後、助成制度を設けて、民間の土地でありますけれども、崖・擁壁を減らすような努力はされる予定でいるのかどうか。ぜひともこの助成制度を設けていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"区としましても、来年度、残りの半数を調査しながら、例えば専門家派遣ですとか、あるいは啓発のパンフレットですとか、そういった効果的な支援策についてしっかり検討していきたいと考えています。","id":"exchange-162"},{"speaker":"浅野委員","kind":"意見","question":"最後になりますが、これは民間で、その人たちが整備するとなると大変な費用がかかって、なかなかできないのではないかなと思います。これからも助成制度はしっかりと検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-163"},{"speaker":"渡辺委員","kind":"質問","question":"私は３１３ページ、道路擁壁等美化事業を伺います。この美化事業の政策的な目的、そしてこれまでの効果検証というのですか、それを教えてください。それと、区が把握しているというか、区が管理すべき対象はどれぐらいあるのか、数ですね。それと、そういうところで、結構なところで見受けられるので、どれぐらいこういうものが実施されているのか、これも数を伺えればと思います。","respondent":"稲田道路課長","answer":"現在、実施の箇所数なのですが、４１ヶ所のうち３７ヶ所、実施してきております。そして、今後の見込みなのですけれども、平成３０年度末までには残り４ヶ所を完成させていこうというところで現在進めております。","id":"exchange-164"},{"speaker":"渡辺委員","kind":"提案","question":"例を言えば、山手通りで、目黒川の付近というのですか、三共製薬のところ。今後という中で、まずオリンピックという目標も含めて、舟運事業にも活かされるべきという思いでは、これは多分、東京都と連携になりますが、これはぜひ品川区からの要望あるいは提案も含めて進めていただきたいと思いますが、京浜運河沿い、このあたりなども結構いろんなことが展開できるのか。","respondent":"和田河川下水道課長","answer":"ただ、積極的に検討はしたいと思っているのですけれども、課題も少なくなくて、例えば魅力的に映るデザインとはどんなものかとか、それから対象区間をどうするかとか、それから水の中から当然施工するので、その施工性の問題とか、いろいろあります。","id":"exchange-165"},{"speaker":"渡辺委員","kind":"提案","question":"その中でも、例えば今、京浜運河のところは護岸を思い浮かべたのですが、モノレールの足というのですか、柱。品川区で開催される３種目のイラストなり絵が表現されている。そういう意味で、とにかく最初、道路で伺ったのですが、いろんな要素を表現する施策になり得るのではないかなと思うので、企画になるのでしょうか、最後、そういう意味でご提案申し上げますが、コメントをいただければと思います。","respondent":"柏原企画調整課長","answer":"一つ一つについては、それぞれ検証しなくてはいけない部分はあろうと思いますけれども、考え方としては、オリンピック・パラリンピックが一つの契機でありますので、品川区をどういった形で、うまくといいますか、発信できるかという観点では。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1046#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":127523,"voices":392}},{"id":"h28-20160314-3","meetingId":"h28-c-budget","date":"2016年3月14日","dateIso":"2016-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後５時３５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を155件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年度品川区一般会計予算","agenda":"平成２８年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、３７３ページ、学校環境整備事業の維持補修費、３７５ページ、校庭人工芝生化、そして、擁壁改修について、お伺いいたします。施設一体型一貫校では、教室の床、壁などには木材を使用していることで落ち着きのある空間ですけれども、分離型小中一貫校においても、教室改修が必要な場合、木材を使用していくのでしょうか。昔から日本ではしっくいが使われてきました。お考えをお聞かせください。","respondent":"品川庶務課長","answer":"２点目のしっくいについてですが、先ほど、委員からご説明がありましたように、メリットとして消臭機能とか、かび防止、鳥インフルエンザ等に効果があるということです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３７５ページ、校庭人工芝生化についてお伺いいたします。伊藤小学校、台場小学校２校の校庭人工芝生化の予算が１億２,５００万円余り計上されております。本年２月に、ようやく全米消費者製品安全委員会、そして環境保護局や疾病対策センターとの共同で、安全性について調査を始めたとのことですけれども、今回の人工芝生化に使われている原材料の安全性はいかがでしょうか。","respondent":"品川庶務課長","answer":"先だって、ある雑誌等に、人工芝の発がん性について記事が出ていたというのは、私のほうも確認しておりますが、その発がん性について、本当にあるのかどうかというところも、まだ現在は検証されているような段階ですので、逐次、この状況を見ていきながら。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２０２０年オリンピック・パラリンピック競技会に向けて、運動能力の向上、グラウンド、そして体育館の整備をぜひよろしくお願いいたしたいと思います。次に、擁壁の改修について、お伺いいたします。近年、ゲリラ豪雨や地震等の影響で、危険な擁壁やがけの崩壊等が心配されております。本年度会計予算の中に、擁壁改修が１校計上されていますけれども、その対象校はどこになるのでしょうか。","respondent":"品川庶務課長","answer":"擁壁工事の点ですが、今年度対象となっている学校は清水台小学校になります。ここは、校舎の東側には昭和大学の９号館、もう一つ民家のアパートがあるのですけれども、それから、中原街道側の南側、この部分の擁壁改修を行っていく予定です。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"意見","question":"南側は中原街道に面しているということで、当然、通行人などがいらっしゃいます。子どもたちのいる学校での擁壁の崩壊等はあってはならないことだと思いますので、ぜひ、速やかな対応をよろしくお願いいたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"新妻委員","kind":"確認","question":"私からは、３６５ページ、マイスクール運営費、３６７ページ、品川図書館運営費、３６１ページ、プラン２１推進事業の中の市民科・各教科充実経費について、お伺いします。発表されました資料から確認をしますが、まず、会派として、マイスクール八潮に見学に行かせていただきました。それから、７年生から９年生が対象ということですが、どのくらいの受入れ人数を予定しているのか、まずお伺いします。","respondent":"村尾教育総合支援センター長","answer":"ただ、マイスクール五反田につきましては、集団生活ではなくて、どちらかというと個別対応がメインになりますので、そのように考えております。今、１日大体１０人程度を予定して、計画しています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、マイスクール五反田では、メンタルフレンドということで大学生を起用していくということですけれども、このメリット、またデメリットを教えていただければと思います。そして、今、個別対応が主だというお話でした。例えば、マイスクール八潮からも行くことがあるのか、そこら辺を教えてください。マイスクール八潮とマイスクール五反田との役割分担を、少し教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特にその中でマイスクール八潮につきましては、先ほど言いましたけれども、集団対応、マイスクール五反田については個別対応、また、マイスクール五反田につきましては、午前９時から１２時を現在考えておりまして、その中で、子どもたちが通える日はこちらと。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、市民科の質問をします。今回、平成２８年度、がん教育の部分で少し予算が付けられているのか、また、決算特別委員会以降、例えば、市民科の中で少しがん教育を取り上げられた学校がありましたら、教えていただきたいと思います。あわせて、品川図書館のほうの質問もします。現在、品川区の図書館には大活字本はあるのか、またはどれくらいあるのか、あわせて確認させていただきたいと思います。","respondent":"村尾教育総合支援センター長、木村品川図書館長","answer":"特に市民科で予算を付けてということではないのですけれども、さまざまな全国的な取組み等を参考にしながら、今回は、保健体育領域の中で進めてきましたけれども、子どもたちに、よりよいがんに対する認識を持たせるということ、また。大活字本についてのお問い合わせです。区内に図書館１０館ございまして、そちら全てに所蔵しております。どれくらいかということですけれども、昨年３月末現在ですけれども、全部で４,０４３冊所蔵しております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"がん教育に関しましては、１校、保健体育の授業でやっていただいたということで、ありがとうあります。大活字本ですが、１０館全てにあるということで、思っていたより多くの本が用意されているということがわかりました。４,０００冊ある中での、この利用者数とか、いろいろな種類があると思いますが、購入にあたってのジャンルなど、どういうふうに購入されているのかお伺いします。","respondent":"木村品川図書館長","answer":"利用されている方の数です。実数はつかんでおりませんけれども、貸し出しをした数ということでございまして、平成２６年度は、先ほどの所蔵数と全く同じなのですが、４,０４３冊が貸し出されておるところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは利用率が高いということでしょうか、ある本が全て貸し出されているということなのでしょうか。ぜひ、また周知もしていただきながら、多く利用できるようにしていただきたいと思います。大活字本とはこういうもので、ここにありますということもしっかりと周知していただきたいと思いますが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"ただ、委員ご指摘のとおり、まだまだ周知がいま一つの部分もあります。時期を見まして、情報提供に努めてまいりたいと思います。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"せっかくいい本でありますので、周知をしていただき、多くの方にご利用いただきたいと思います。本年度、東京都の中でも、初めて千代田区と江戸川区が、大活字図書を対象に加えたということを聞いているのですが、品川区としては、今のところ入っていないようですけれども、今後どうなっていくのかお伺いさせていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"これからまた見直しの材料の検討の中身の素材としては入ってまいりますので、幅広い障害のある方の日常生活用具、どういったものを取り入れると皆様の生活が豊かになるか、そうした視点で検討していきたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"意見","question":"図書館においても、リクエストに応えて購入されているということですが、手元に持っておきたい方もいらっしゃるかと思いますので、ぜひ前向きにご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"３６３ページから３６５ページ、品川英語力向上推進プランと推進経費について、それから、３５５ページ、学事制度検討経費について伺います。平成２６年度、平成２７年度、平成２８年度と英語教育の予算が大幅に伸びています。特に小学校１年生から６年生のところでいいですが、予算の主な使い道、何に使われているのかお伺いします。それから、英語教育の目的についても、お聞かせください。","respondent":"渋谷指導課長","answer":"１点目が言語や文化に興味、関心を持たせるとともに、体系的に理解を深めるということ、２点目は、積極的にコミュニケーションを図ろうとする態度の育成を図るということ、３点目は、聞くこと、話すこと、読むこと。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小学校のところですけれども、外国人の英語講師派遣委託費、それから、今お話があった小学校の専科指導員の配置経費、ここのところの比重が大変高いのですが、ＡＬＴの委託先、資格はどのようになっているのか、人数について、これが１点。どこに所属し、配属されているのか、具体的に教えていただきたい。小学校全員の何％くらいが研修を受けているのか教えてください。","respondent":"渋谷指導課長","answer":"人数については、後ほど、お知らせいたしたいと思います。それから、ＪＴＥですが、日本人英語講師ですが、これは３年間かけて全校実施をしていくもので、現在、２年目です。身分については、区の非常勤職という位置付けで、月１６日勤務と月１３日勤務でお願いをしています。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"ＡＬＴの資格がどうなっているのか、漏れているので、後で教えてください。それから、子どもたちが英語に興味を持って楽しく学べることがとても大事ですが、今回の予算書を見て気になったことが、平成２８年度に国際理解教育の文字が消えています。私たちは、英語教育に特化されすぎているのではないかと思っています。この点が１点です。免許を持った職員として採用すべきと思いますが、いかがでしょうか。","respondent":"渋谷指導課長","answer":"ここ２年ほど実施しましたＪＴＥの応募状況を見ても、１００人を超える方が実際に応募をされていて、他区で実践されている方も、こういうふうにきちんと認めて、しっかりと仕事ができる環境にあこがれて品川区に応募してくださる方が多いという状況ですので。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"私は、中学校の英語は確立されていると思うのですが、小学校の１年生から６年生は新しい分野ですよね。私は、じっくりと体制整備をしていきながら、教職員の意見もしっかり聞いてやってほしい。ぜひその辺を聞かせてほしいのは、英語教育はさまざまな考え方があるので、必ずしも賛成している方ばかりではない、という意味では、検討とか、評価をどのようにされているのか。","respondent":"渋谷指導課長","answer":"ただ、これは確立したものではございませんで、この後、学習指導要領で、英語が教科としてしっかりと位置付けられた後には、学習指導要領等々との整合性も合わせて検討して、品川教育としてしっかりとしたものを確立していきたいと考えているところです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"提案","question":"教育フォーラムで提案されている英語教育プラン、現場の教職員の方にどのくらい浸透して、どのくらい理解ができているのか、質問したので、ここのところを答えていただきたい。この間、中学校の先生に伺ったら、英語は７、８、９年生は４コマ、４コマ、４コマだけれども、国語が４コマ、４コマ、３コマになっているというのです。その点が一つ。","respondent":"渋谷指導課長","answer":"現場への浸透ですが、ここがやはりなかなか難しいところではあります。一律に研修をしても、なかなかご理解いただけないというのが実際です。ただ、今年度、モデル校を１４校実施して、実際にＪＴＥの方とティームティーチングをした先生方については、非常に評判がいいです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保護者は、英語が話せたらいいなという期待はしています。でも、その期待にしっかり応えるものなのか、また、子どもたちの１時間、１時間は今しかないのです。その子どもたちの成長を大事にする意味では、現場の職員の声も聞いてじっくりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"私からは、３５９ページのいじめ等根絶普及啓発費について、３６３ページのオリンピック・パラリンピック教育推進事業の独自教材作成について、３５５ページの教職員健康管理費について、時間がありましたら、３６３ページの学力向上プラン推進事業について伺います。３５９ページのいじめ等根絶普及啓発費の５９１万５,０００円について伺います。","respondent":"村尾教育総合支援センター長","answer":"今年度、区のいじめ防止推進条例のほうで、現在進めている中で、今回、この条例の制定を踏まえ、改めて区内の子どもたち、そして教職員、ＰＴＡ、また地域関係の皆様、まさに子どもの教育に携わる一人ひとりがいじめ防止に対する意識の高揚を図っていただくとともに。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"そうした目的で、一人ひとりにいじめ防止に対して意識をさせる取組みとして、私は、とてもいいアイデアだと考えています。そこで、啓発バッジについて伺います。この作成にあたり、児童たちがデザインを決めるということでありますが、現在、どのような段階まで進んでいるのか伺います。今後のスケジュールについても伺いたいと思います。よろしくお願いします。","respondent":"村尾教育総合支援センター長","answer":"この後、各学校で決めたバッジを業者のほうに出すということで、来年度になりますけれども、それぞれつくったバッジについては各学校に配布し、さまざまな形で、いじめ防止について、うまくツールとして活用できればいいと考えているところです。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした対策で、児童・生徒一人ひとりがいじめ防止に対する意識を高めていただいて、また、教職員、ＰＴＡ、地域の方々と連携し、生徒をいじめから守っていただきたいと思います。３万個ですが、生徒や教職員、ＰＴＡ等に配られる予定とありますが、地域の方々や保護者に関しては、その中に含まれているのか伺います。配布方法についても、あわせて伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"予算ですが、当初まだ、どのような形で啓発事業を行うか検討している段階でしたので、グッズという大きな括りで予算は出させていただいて、最終的に決まったのがバッジ作成と考えているところです。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、そうした形で取り組んでいただけたらと思います。啓発ポスターも含まれておりますが、１７万３,０００円余と、プレス発表のほうではそのように書いてありましたが、このデザインは教育委員会が考えるのでしょうか。何枚くらいなのか、数について伺いたいと思います。どういったところに掲示される予定なのかも、あわせて伺います。","respondent":"村尾教育総合支援センター長","answer":"現在、ポスターにつきましては、委員おっしゃるとおり、教育委員会のほうで作成し、これについては、バッジの配布とあわせて、学校のほうに掲示しようと考えているところです。枚数等は、学校プラスさまざまな関係の場所等を考えて決定をしていきたいと考えています。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"いじめ防止推進デー、いじめ防止推進ウイークについて伺います。これらは、各学校で設けるとあります。この時期に関しては、５月から６月と、１０月、１１月にかけてだというデータがあります。それを見ますと、やはりそうした時期、特に５月から６月ですけれども、そうしたところをこうしたウイークにしていただくよう検討していただきたいのですが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"委員ご提案の、５月から６月につきましては、本当に参考にさせていただいて、各学校を含めて、一番子どもたちの啓発、また地域絡みで、オール品川でいじめを防止する取組みに広げていければよいと考えているところです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、そうした理由も踏まえて、ご検討いただきたいと思います。次に、３６３ページのオリンピック・パラリンピック教育推進事業の独自教材作成について伺います。これについてですが、各学校でオリンピック・パラリンピックに関する教材を作成されるものであるのか、伺います。この目的と、作成方法等について、どのような教材になるのか伺います。","respondent":"村尾教育総合支援センター長","answer":"ページ数はそんなに多くなく、３種目の内容、それから写真等を使ったもの、これにつきましては、こちらのほうで作成し、印刷をして子どもたちに配布し、また、それを子どもたちが家に帰って、保護者にも、品川区の種目等を広げていこう。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"わかりました。年間３時間ですね。この教材は、今、各学校に配布されていると思いますけれども、そこでこの授業に関してですが、科目は何に当たるのでしょうか。これは体育に当たるのか、わからないので教えてください。内容について、簡単に教えていただければと思います。どのような形でこうした授業を行っているのか、お伺いします。","respondent":"村尾教育総合支援センター長","answer":"体験教室ということで、本区においては、ブラインドサッカー、ホッケー、ビーチバレーの３つを、３年間かけて全校で一応実施していこうと考えているところです。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"授業内容はわかりました。対象が区立全学校ということを伺いまして、今後、東京オリンピック・パラリンピックの後、閉会後はどのように考えていらっしゃるのか伺いたいと思います。私の知り合いでも、ホッケーを勉強されていて、一生懸命やられている方がいらっしゃるのですが、今後もぜひ、こうしたことを続けていただけたらと思うのですが、閉会後について伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"オリンピック・パラリンピックが終わった後ですけれども、一つは、子どもたちにレガシーではないですけれども、やはり今回、オリンピック・パラリンピック教育を通して、まさに先ほどお話がありましたけれども、子どもたちが世界に目を向けたりするような学習を。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、そうしたこともご検討いただければと思います。最後に、時間がありますので聞きます。３５５ページの教職員の健康管理費について伺います。この中で、ストレスチェックと、メンタルヘルス対策についてですが、現在、教職員全員が行っているものでしょうか。昨年、ストレスチェックでどのような結果が得られたのか、また、対策について、最後に伺いたいと思います。","respondent":"品川庶務課長","answer":"時期としましては、６月から７月頃に行いまして、状況としまして、Ａ、Ｂ、Ｃ、Ｄ、Ｅランクまであるのですけれども、平成２４年度から平成２７年度まで、０.４％から１％程度の方がＥランクという形で出ている状況です。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"委員長、ちょっとページ数がわからないのですが、教育委員会とか、学校がほかの部署とどうかかわっているのかということを、まず伺ってよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"委員長からオーケーが出たので、質問します。具体的にわっくわくランドしながわとか、民生費で出ている事業がありますけれども、いわゆるほかの部署にこういった小学校や中学校を対象とする事業がある場合、教育委員会といいますか、学校では、特にＰＲの仕方ですけれども、どういうふうにかかわりを持つのでしょうか。","respondent":"伊崎子ども育成課長、村尾教育総合支援センター長","answer":"教育的なかかわりという視点からまいりますと、ボランティアとして、小学生からＯＢ、ＯＧの方たちまで活躍していただいていますので、青少年の健全育成という視点では、教育と同じ土壌で考えていると考えています。地域関係であれば、ＰＴＡ会長にも伝えていくという形で、学校、校長を中心にさまざまな区の取組みのバックアップ、支援、また協力・連携を図っているような状況です。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"３６３ページ、オリンピック・パラリンピック教育推進事業で、内容等についてはよくわかりましたけれども、ビーチバレー、ホッケーに力を入れていくということで、それはここで競技するからだと思うのですが、しかし、野球、サッカー、普通のバレーボールもさらに、ここではありませんけれども、充実していっていただきたいという思う気持ちがあるのですけれども、その辺についてはいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"子どもたちは、テレビで見たり、さまざまな情報を知りながら、スポーツにかけるいろいろな生き方とか、そういうものも広くできるのかと考えております。学校の中で行われるさまざまな活動の中でも、その辺は十分に広げていけるものだと考えているところです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"意見","question":"２０２０年に終わってしまうわけですよね。わからないですよ、オリンピックは４年に一遍あるのですけれども、またその次の次にもしかしたら日本に来るかもしれない、東京に来る可能性はあるわけですけれども、目標がある２０２０年、目標が終わった２０２０年以降という形で、どういうふうに考えられているか、教育委員会と準備担当の二つの部署からご答弁いただけますか。","respondent":"小川オリンピック・パラリンピック準備課長、村尾教育総合支援センター長","answer":"そういったことが確実にレガシーとして残りますので、区内で３競技やったということが、子どもたちの胸にとどめられ、それが何かの形でいろいろ発展していけるように、教育委員会とはさまざま連携して残していきたいと考えています。教育の分野です、一つはオリンピック・パラリンピック競技の大成功ということで進めてまいりますけれども、実際にこれが終わった後でも、今回、区としては五つの視点、おもてなし、障害者理解、スポーツ学習、和の心。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"最後に、３７９ページの給食食材放射性物質検査費についてお伺いしますが、これまで５年実施してきた結果はどうだったのか。区民に安心感を得てもらうためということでしたけれども、もう既に流通段階で全てクリアしていて、なおここでお金を使うことがあるのかという意味で伺いたいと思いますが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"それにもかかわらずなぜやるのかということですけれども、やはり今のところ、まだ汚染水等、いろいろ決着がついているわけではございませんし、品川区としては、子どもたちが食べる食材ですので、独自検査を、少なくとも来年度についてはやっていこうと考えているところです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"もう流通の段階でやっていますよね。今の学務課長の前に環境課長だったから、その辺に力を入れたいという気持ちはわかるのですけれども、もうこの５年間大丈夫だったのですから、節目の５年ですから、その辺については、私はもういいと思っているので、改めてよろしく答弁のほうをお願いします。","respondent":"野呂瀬学務課長","answer":"平成２８年度については給食検査ということでご提案しています。平成２９年度以降につきましては、適時適正に判断してまいりたいと考えています。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私からは、３５５ページ、区教員経費、３６１ページ、市民科推進会議等、３６３ページ、品川英語力向上推進プラン、３７３ページ、実用英語技能検定料助成５～９年生について、お伺いいたします。区教員経費についてお伺いいたします。現在の区の固有教員の採用基準と評価。平成２８年度の採用状況と、区の固有教員が管理職になるための現在の条件と、今後の整備条件について、お聞かせください。","respondent":"渋谷指導課長","answer":"義務教育学校への配置については、今、ご説明したとおり、一貫校への配置というのは、そのまま義務教育学校への配置ということに、今のところはスライドしていくと考えているところです。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"小中両方の免許をお持ち、また特別支援学級と英語科のいずれかをお持ちの方ということで、今回、採用辞退があったということでゼロということで、ちょっと残念な結果だと思うのですけれども、そのあたり、区のほうとしてはどのように見ていらっしゃいますでしょうか。","respondent":"渋谷指導課長","answer":"残念ながら、その２名の方がご辞退になったです。ただ、ずっと品川の先生でいらっしゃる方でありますので、採用基準を下げることなく、今後も、一定水準以上の方を採用していきたいと考えているところです。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"市民科についてお伺いいたします。２月の品川区教育フォーラム、市民科の分科会におきまして、新しい次の１０年を先取りしていくというお話がございました。市民科の課題として、市民科における教師指導力の向上と、これからの社会において求められる力の育成について、簡単にお聞かせいただけたらと思います。研修の向上について、区のお考えをお聞かせいただけたらと思います。","respondent":"村尾教育総合支援センター長","answer":"ただ、今後１０年先を見たときに、やはり新しいもの、フォーラムでも発表いたしましたけれども、主権者教育であったり、また、少子高齢化、福祉教育的なものも、もう少しクローズアップされて、子どもたちに小学校・中学校段階から。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"現代の課題に対応できる力ということで、法教育、主権者教育、福祉教育等ということで、フォーラムでもご紹介がありました。地域包括ケア、今後、担っていくのは現在の児童・生徒たちになってくるかと思います。子どもたちが大人になったときに、変化にどのように対応していくのか、そうしたあたりのスキル、変化への対応力について、品川区の子どもたちにどのような力が求められると、お考えでしょうか。","respondent":"村尾教育総合支援センター長","answer":"２点目、子どもたちは変化への対応力がある、まさに、国際化、情報化、グローバル、さまざまな変化が大きくあるところです。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問・要望","question":"現実の地域や社会をしっかりと見せていき、そしてまた、子どもたちに考えさせて、また行動も一緒に教えていくということで、そういった形で今後とも進めていただきたいと考えています。議論やディベート、また課題を発見する力、それを解決する力、そうしたところもに力を入れていっていただきたいということで要望します。次に、英語検定の質問をします。品川英語力向上推進プランについてお伺いいたします。","respondent":"渋谷指導課長","answer":"今後も、品川区の義務教育を終了した子どもたちが自信を持って世界に羽ばたいていけるように、しっかりと教育していきたいと考えているところです。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"今、さまざま、先ほどの委員へのご答弁でもありましたけれども、ＪＴＥと担任教師のＪＴＥのティームティーチングの取組みですとか、さまざま体験されているかと思います。このあたりですけれども、今後もフォニックスやリテラシー学習の導入をぜひ進めていただきたいと思いますが、中学校の英語教育、また就学前の英語教育、そうしたところにつきまして、品川区のお考えをお願いいたします。","respondent":"渋谷指導課長","answer":"今まさに、品川区で大きな課題として認識しているところが、中学校英語との接続の部分を、この後の学習指導要領の改訂に合わせてどういうふうに図っていくのかということで、品川区はこれでオリジナルの取組みを進めておりますので、国と同じというわけにはいきませんので。","id":"exchange-038"},{"speaker":"横山委員","kind":"意見","question":"最後に、実用英語技能検定料助成５～９年生について、検定料の全額助成、大変英語学習の意欲につながっていると聞いておりまして、児童・生徒皆さん意欲的に受験されているということですけれども、このあたりの実施の状況や、また成果の部分について、最後にお願いいたします。","respondent":"野呂瀬学務課長","answer":"英語検定ですけれども、昨年の６月に補正予算でご承認いただきまして実施したところ、中学校につきましては約４,８００人中２,１３３人、４４％、中学校５、６年生につきましては、約４,２００人中４２１人、大体１０％ということで、受験していただきました。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、５テーマ質問します。２問まとめて質問します。予算特別委員会、決算特別委員会で、これはずっと要望させていただいておりましたので、大変感謝をしております。３点伺います。２点目は学校保健会、これは学校長、校医、歯科医、薬剤師、養護教諭からなる連絡協議機関であると思うのですけれども、こちらへの周知徹底も不可欠だと思いますが、いかがでしょうか。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"３点目、人工芝のところで、人工芝を使うにあたっての弱点として、炊き出し等ができないことがございまして。２点目のＭＴＢＩについてですけれども、ご指摘のとおり、学校保健会というのは校長、養護教諭、それから３師会、３師会というのは学校医、学校歯科医。学校に来られた方につきましても、少しでも興味のある方に配布できるような形で準備をしていきたいと考えています。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"確認","question":"ＭＴＢＩについては、ぜひ周知をしてください。周知という考え方はいろいろあるものですから、確認させていただきました。次に、図書館経費で、図書館での障害者施設製品の販売について伺います。そこで質問したいのですけれども、今までありそうでなかった図書館と福祉の出会い、どのような経緯で、いつから実現したのか教えてください。それから、売得金額はどこに帰属するのか教えてください。","respondent":"木村品川図書館長","answer":"荏原図書館は、今まで耐震工事を行っていたのですけれども、昨年８月、再開館にありまして、指定管理者のほうから、ぜひこういうことをやってみたいと、実際は他区で既に実施されていたということですけれども、そういう打診を受けまして、障害者福祉課を通じまして。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど、新しい商品の開発ということもあったのですけれども、これは荏原図書館だけではもったいないような気もするので、販路として、品川図書館をはじめ、可能なところでは各地区図書館など、また、大井町、武蔵小山でサービスコーナーをやっていると思うのですけれども、ああいうところでの拡大を、ここで要望したいと思うのですけれども、いかがでしょうか。","respondent":"木村品川図書館長","answer":"販路の拡大についてです。委員ご指摘ございましたように、来年度は地区館も一つ展開していこうと検討しています。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３６１ページ、プラン２１推進事業から、先日、ＰＴＡの方からご意見を賜る機会があったので、さまざま伺ったのですが、２点に絞って伺います。報道によれば、全国で導入されるのが８校、もしくは９校と聞いているのですが、品川区の６校のほかには、たった２校か３校しかないということで、なぜこんなに移行を急いだのですか、拙速すぎるのではないかというご意見がありました。３点伺います。","respondent":"渋谷指導課長","answer":"ただ、やはり保護者の方々は、義務教育学校というふうに名称変更になることによって、そこの部分についてご不安を持っていらっしゃるお声も、私どもも耳にしていますので、そこは個別の部分で丁寧に対応して、ご説明をしていきたいと思っているところです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その説明の部分で、もう１点だけ伺います。帰ってうちの娘が通っている小学校の先生に確認しましたら、品川区をモデルにしていると。この点について、ちょっと質問の仕方が難しいのですが、教育委員会は、これをどういうふうに考えられているのか。子どもの実力さえ上ればいいのか、それとも保護者に対して、これをどういうふうに説明していくのか。そこのところを教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"実際に、保護者の方に実感していただくという意味も込めて、今回、フォーラムでは、全校、実際に授業公開をして、実際の子どもたちの活動している場面、状況をご覧いただいて、実際の子どもの変化、成長を感じていただくということを地道にやっていくことが。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、時間があまりないのですけれども、子どもの貧困について伺います。就学援助というところで、教育委員会の範疇で伺えば、例えば先生が自分の生徒が、この子は１日に給食しか食べてないなとか、いつも同じ服を着ているなとか、これは貧困を起因として学力が遅れていると感じた場合に、今はどういう手段を講じていらっしゃるのか。これについて、教えてください。","respondent":"村尾教育総合支援センター長","answer":"そういうときには、当然、学校長のほうに連絡をして、家庭訪問をするとか、また現状がどういうふうになっているのか確認したうえで、関係機関と連携を図りながらサポートしていく、その部分かと考えています。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５９ページ、巡回相談員経費に係わって、学校における性の多様性への理解について、後半は、３６７ページ、図書館経費、大崎図書館の現地での存続を求めて質問します。ＬＧＢＴ、性的マイノリティの点ですが、昨年の決算特別委員会でも取り上げました。お伺いしたいのですが、教員の皆さんに持ってもらうべき、きちんとした知識というのは何なのか、区としてはどのように考えるのか伺います。","respondent":"村尾教育総合支援センター長","answer":"先ほど、委員のご案内のとおり、国のほうからも、性同一性障害に係る児童・生徒に対するきめ細やかな対応の実施について、ということで、教員研修、そしてチームでの支援体制、また、医療機関との連携ということが述べられています。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"連携等とありますけれども、後でもお伺いしますけれども、そもそもＬＧＢＴ、性的マイノリティとはどういうことなのか、そもそものきちんとした知識が大事だと思いますので、後で伺いたいと思います。そこで幾つか伺いますけれども、例えばこの中で、「同性愛は精神的な病気の一つだと思いますか」との質問に対しては、５.７％の教員がそう思うと答え、２５.１％がわからないと答えています。","respondent":"村尾教育総合支援センター長","answer":"国の調査結果の部分につきましては、まさにそれは、現状としては、教員の意識、また教員が認識している部分については、そのような形だと考えています。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"これは教員の調査の結果そういうことだったのですけれども、では、同性愛とは精神的な病気の一つなのでしょうか。きちんとした知識を持ってもらうことが大事ということでしたので、品川区教育委員会自身の認識を伺いたいと思います。同性愛は精神的な病気の一つなのか、伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"医学的見地に基づく診断というような形で考えているところです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"同性愛は精神的な病気の一つではありません。もう一つ、調査の中で、「性同一性障害と同性愛は同じようなものだと思うか」との質問に対して、教育の中で５.０％がそう思うと答え、２９.４％の方がわからないと答えました。性同一性障害と同性愛は同じようなものだという誤解も少なからずあるという実態ですけれども、これが同じものなのでしょうか、この問題についての区の認識も伺います。","respondent":"村尾教育総合支援センター長","answer":"そのため、これとこれが同じかどうかということではなく、この部分につきましては、どのような形で対応できるかということを重点に考えていくところです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"提案","question":"ちょっと提案したいのですが、全教員を対象にした研修の実施、そして、児童・生徒向けの正しい知識を広げるため、また、同じく誰に相談すればいいのかわかるポスターの図書館や保健室への掲示、これが２番目です、３番目として、図書館の図書や視聴覚資料の充実、以上３点を求めますけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"加えて、特別支援コーディネーター連絡会、そして、巡回相談連絡会等につきましても、本年度既に、この件について各学校での取組み、子ども自身への支援、多様な性への理解を深めるもの、また保護者への正しい情報提供、今後どのような形にしていくかにつきましては、今。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のお話ですと、不十分ですね。やはり全教員を対象とした研修の実施を強く求めていきたいと思います。ぜひ、こちらはすぐにでも実施していただきたいということを要望したいと思います。大崎図書館、先日の文教委員会で、９５７筆集まった存続を求めての請願審査もございました。地域の熱い思い、地域と一緒に、この方が図書館にと提供してくれた土地を、図書館でなくしていいのか、ここを伺います。","respondent":"木村品川図書館長","answer":"今までもご説明してまいりましたけれども、例えば、移転先、それから代替施設として計画をしております芳水小学校の地下、大崎駅前の再開発の地域、そちらの大崎地区全体の図書機能という形で、その思いを受け継いでいくような形で。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"代替施設もつくるということで、同等と説明されておりますが、代替施設の中身ですが、検討中と繰り返して、どんな机が幾つできるのか、蔵書数の規模がどうなのか、人員配置がどうなのか、全く不明です。代替施設５００m2は、現在の大崎図書館の１階部分にも及ばない面積、これのどこか同等なのでしょうか、はっきり説明してください。","respondent":"木村品川図書館長","answer":"今まで、同等の機能ということで、確かにご説明してまいりました。同等の規模の面積という意味では、なかなか代替施設の確保が、近隣では難しいという部分がございました。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"機能という意味では、ますます同等ではないと言いたいと思います。地元の大崎住民からすると、当初、改修に関しての経費を要求してきたのです。それが、この計画の中で、区の都合で移転の必要のない図書館を持っていかれたことになるのではないでしょうか、違うのでしょうか。私はとんでもないと思うのですけれども、現地の存続を求めますが、区の見解を伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"ただいまの大崎図書館について、関連質問をします。ただ、大崎図書館が移転するという計画がありまして、その計画に対して、確かに地域ではさまざまな声がありました。ただ、御殿山に移るのではなくて、芳水小学校のＰＴＡ会長が請願代表者で請願を出されて、西口に大崎図書館の１階の機能を残しくださいという趣旨で、芳水小学校の１階に床面積が確保されたと思うのです。その２点について、お願いします。","respondent":"木村品川図書館長","answer":"委員ご指摘のとおり、一昨年の請願をもちまして、実際に移転をするけれども、その考えには変わりはないけれども、代替施設として、大崎図書館の図書機能を芳水小学校で行う、もう一つは大崎駅前の西口の再開発地区で行う。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"私からは、１項教育総務費、３目教育指導費から、３５９ページ、いじめ防止対策費と、３６１ページ、市民科・各教科充実経費、それから、３６５ページのマイスクール五反田運営費について伺いたいと思います。最初に、３５９ページ、いじめ防止対策費についてです。教育委員会が委嘱する５人以内をもって組織するとありますが、どういう活動を想定しての予算立てなのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"品川区いじめ対策委員会におきましては、第１４条に定められている部分でございまして、いじめ防止等のための対策の推進について審議をし、また教育委員会に意見を述べるものとする部分です。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"条例の第２１条に「いじめ問題調査委員会設置がされるのは、区長が当該報告に係る重大事態への対処、または当該重大事態と同種の事態の発生の防止のため必要があると認めるとき」とあるのですけれども、これはどういう状況のことを言うのか伺いたいと思います。","respondent":"江部総務課長、村尾教育総合支援センター長","answer":"区長の附属機関として置かれますいじめ問題調査委員会ですが、予算立てといたしますと、１６３ページ、総務管理費、一般管理費の中の事務用経費の中の１,５００万円余の中に委員会の報酬として含まれてございまして。第２０条、また第２１条に書かれている重大事態という部分ですけれども、(1)、(2)に書いてあるとおり、生命、心身または財産に重大な被害を生じた場合ということで、具体的に文部科学省のほうの見解といたしましては。","id":"exchange-056"},{"speaker":"吉田委員","kind":"提案","question":"なぜこのようにメンバーについて質問するかというと、それぞれの委員会やチームに子どもたちの目線に立てる人、子どもたちの気持ちに寄り添える人を入れてほしいという思いがあるからです。それから、どういう活動を想定してバッジとなったのか、最後に、検証がどういうふうにされるのか伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特に、今回条例制定された部分につきましては、４月１日からの予定になっておりますので、そこから改めて、品川区、いじめ防止についてしっかり取り組んでいこうという考えです。具体的な活動については、学校がそれぞれ工夫をしながら、バッジを有効的に活用する。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"時間がないので、次にいきます。次に、３６１ページの市民科・各教科充実経費ですが、先ほど、午前中にご質問がありましたけれども、ＬＧＢＴへの意識啓発について伺いたいと思っています。人権啓発教育の一環と理解したので、この項目で伺いたいと思います。品川区での教育現場における対応を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"現在でも、実際に東京都が発行しています人権教育プログラムの中にも、性同一性障害という部分で記載されており、都全体でＬＧＢＴの子どもたちへ、どのような形で対応していくかということを十分に議論され、それによって、どのような形で指導していくか、また内容についても。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"具体的には、どのようなことなのでしょうか。例えば文部科学省の通知には、自認する性の制服や体操着の着用を認める、多目的トイレの使用を認めるなど、具体的な配慮がされているのですけれども、品川区においては、トイレへの配慮とか、制服や体操着、更衣室、身体検査のときなどは、どのように対応されているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"例えば服装や更衣室、トイレ、授業、水泳、また修学旅行等、さまざまな個別の配慮が必要になってくる部分がありますので、当然、ケースに応じて適切に対応できるように、学校も十分対応できるようにしていきたいと考えております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"都の関係部局の方のお答えでも少し気になったのですけれども、子どもたちから相談があればということなのです。今も、もしかするとそうかと思うのですけれども、そうすると、子どもたちへの啓発が必要なのかと思います。相談していいということと、それから周りの子どもたちがそれを受け入れるという、そういう子どもたち自身への啓発が必要になるかと思うのですが、その点はいかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"もしそういう対応が必要な児童がございましたら、学校内外を含めて、チーム支援ができる体制を整備したり、また必要に応じて医療機関との連携等、具体的にそういう場合には、担任、または保護者からの相談等も十分に受けられるような相談機能も。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"教員へのというのは、本当にそのとおりだと思いますけれども、ぜひ、子どもたちに自身への啓発も急いでいただきたいと思います。自殺を考えるのは、偏見よりももっと前段の、自分の存在がみんなの気持ちの中に想定されたものではないという深い孤独感、絶望感によるものだということを、当事者の方から伺いました。子どもたちへも、早い段階での啓発が必要と考えますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"今後、どのような方向になるのか見極めながら、区としてもしっかりした対応ができればと考えております。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"ぜひ、早い対応をお願いしたいと思います。マイスクール五反田のことは、先ほど別の委員からご質問があって、大体様子がわかったのですけれども、１点だけ、マイスクールの最終目的は学校への復帰ということなのでしょうか、その点について伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"マイスクール五反田については、先ほどもお答えしたとおり、不登校に陥る可能性のある児童・生徒への、まさに思春期生徒支援事業ですので、大きなねらいの部分では、学校への復帰、休みがちな子がうまく場所を使って少しリラックスをしたり。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３７９ページの３目学校給食費に関連して、学校の食物アレルギー対応についてと、３８１ページの４目学校保健費に関連して、新規計上された脊柱側わん検診についてお尋ねいたします。義務教育学校についてお尋ねします。品川区のこの１０年間の小中一貫教育の先進的な取組みを高く評価し、新たに誕生する義務教育学校を大切に育てていかなければならないという思いから、幾つか質問します。","respondent":"渋谷指導課長","answer":"そういったことで、今まで運用でやってきたものが、法制化されることによって、継続性も担保されますし、安定性もしっかり担保されて、効果的な小中一貫の取組みができるということが大きな取組みになってくると思います。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この１０年間の豊かな実践の取組みが、しっかりとした形として、今、結実したと理解しました。４・３・２と６・３の二つの区分が義務教育学校の中には混在することになると思われますが、学校運営上、特に４年から７年生のあたりで特に気を付けるとか、対応をお考えの点はあるのでしょうか。","respondent":"渋谷指導課長","answer":"義務教育学校が設置されても、単独の小学校、中学校も存在するわけで、義務教育学校の６年間が終わった子どもは、小学校と同等程度の扱いになるのは当然のことでございまして、そういった部分で、６・３に分かれているというのが学事制度的な問題です。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に問題になるのは、後期課程から入ってくる転入生の扱いだと思います。学区内の小学校で前期課程の期間にあたる６年間を過ごして、後期課程から義務教育学校に転入してくる生徒に対して、具体的にどのような温かい、あるいはいろいろ配慮に富んだ取扱いなどをされる予定なのでしょうか、その辺のご説明をお願いいたします。","respondent":"渋谷指導課長","answer":"具体的には、例えば宿泊行事ですとか、スチューデントシティ等々のそういった校外学習を、関連する小学校、義務教育学校の前期課程の子どもと一緒にやる等々、入学前からある程度一緒になじめるような環境をつくるとか。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"設問３７の「義務教育を４・３・２年のまとまりで考えることは、子どもの学びや発達段階に合っている」という質問に対しては、賛成が９.１％、やや賛成が４８％、やや反対が２８％、反対が１０％と、教育委員会の方々の高い志に比べて、いま一つ理解や共感が深まっていないような気もするのですが、教育委員会のこのアンケートの、特に設問３７の結果については、どのようにご評価されているのでしょうか。","respondent":"渋谷指導課長","answer":"小中一貫教育を推進していく中で、一番の課題は、最初に委員からご指摘がありましたが、４・３・２の考え方がなかなか理解しにくいところ、特に単独小学校で４年生、それから５年生以上の部分の、４年生と５。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"父兄の方からいろいろなご意見をお聞きして、大変勉強になったのですが、今後とも、教育委員会も、区のほうも、保護者の方と十分な意見交換を行いながら、実りある義務教育学校も含めた小中一貫教育を進めることを要望いたしまして、次の質問に移らせていただきます。次に、食物アレルギー対応について、昨年の決算特別委員会に引き続きお尋ねいたします。","respondent":"野呂瀬学務課長","answer":"もう一つは、いわゆる除去食対応ではなかった児童ですけれども、帰宅後、アレルギー症状を発症したケース。この２例がございました。","id":"exchange-067"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今の二つの事例に関して、症状が出てから、最終的にどうなったのかという点と、学校側の今後の対応、食物除去や症状が出ないための対策等について、ご説明をお願いいたします。","respondent":"野呂瀬学務課長","answer":"食物アレルギー対応は、安全が最優先ということで、学校生活管理指導表の提出をしていただいているのですけれども、今回の２例目は、除去食対応をしていなかった子どもでも、アレルギーの症状を発症するケースもあるということで、管理指導表の提出をしていただいて。","id":"exchange-068"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"具体的に詳細なご説明をありがとうございました。今回の事例も、しっかりと情報共有と防止策の協議を行うように要望します。食物アレルギーというのは、最悪の場合、死を招く病態で十分な対策が必要です。平成２６年１月に、品川区教育委員会も食物アレルギー対応のてびきを作成しておりますが、これは現在、十分に活用されているのでしょうか。","respondent":"野呂瀬学務課長","answer":"平成２６年１月に作成して、もう２年たちますけれども、食物アレルギーの対応のてびきは定着して、順調に対応が行われていると考えているところです。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、食物アレルギー対応で、今年度に何か新しい取組みなどは、教育委員会はされているのでしょうか。その１点、ご説明をお願いします。","respondent":"野呂瀬学務課長","answer":"今年度、食物アレルギー対応のてびきを一部改訂いたしまして、給食以外の教育活動、例えば移動教室や調理実習だとか、そういう給食以外の教育活動における食物アレルギー対応についても記載するなど、児童・生徒の安全を最優先に食物アレルギー対応の強化に努めているところです。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今後も、食物アレルギー対応をしっかり行うことを要望いたしまして、次に移ります。脊柱側わん検診について、次年度、モアレ撮影が新規計上されました。モアレ撮影についてお伺いいたします。これは、つる副委員長などもたびたび質問されているようですが、まずモアレ撮影について、簡単にご説明をお願いします。","respondent":"野呂瀬学務課長","answer":"モアレ撮影とは、特殊な撮影装置を使用して、背中に等高線のような縞模様の影を移して客観的に背骨の状態を見る検査を言います。背中に写した縞模様が、背骨を中心として左右対称であれば正常、左右で模様がゆがんで、左右差があるような場合は脊柱側わん症の疑いとなるものです。","id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"確認","question":"モアレ撮影は、すだれ状の格子を通した光を背中に当てて、背中に縞模様を浮き出させて、これが左と右で同じかどうか確認して、側わんのチェックをする簡単な検査です。品川区は、従来は、生徒を前に倒して前屈させて、肩の高さや肩の状態を見て、脊柱側わんを診断する視触診法で行われてきたわけですが、次年度よりモアレ撮影を導入することに決めた理由をご説明ください。","respondent":"野呂瀬学務課長","answer":"２００８年に小・中学校の学校医が学校保健法で定められた脊柱検診を怠ったために、脊柱側わん症が悪化したとして大阪地裁に訴訟を起こされたようなケースもございました。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"大阪の事例は、担当した学校医が、女子生徒が裸になるのを嫌がるからという理由で、実際に裸にしなかったので見逃したということで訴えられたようです。このたび導入される予定のモアレ撮影は、男女ともに上半身裸になって撮影されなければならないのですが、学校はどのような点に注意するように、教育委員会としてはお考えでしょうか。","respondent":"野呂瀬学務課長","answer":"女子の検査につきましては、女性技師が見るほか、室内を暗くして、カーテン等で仕切るなどプライバシーに十分に配慮してまいります。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問","question":"モアレ撮影のターゲットとなる脊柱側わん症は、どのくらいの頻度で発見されると考えられているでしょうか。","respondent":"野呂瀬学務課長","answer":"東京都で脊柱側わん検診の唯一の検査機関であります東京都予防医学協会の２０１３年度の実施結果に出ていますけれども、モアレ撮影での異常者数は、小学校で約５.１％、中学校で約１１.５％が検出されました。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは、しっかりと診断しなければいけないので、診断した後も整形外科につなぐこと、正しい診断をして、必要な場合は装具とか、手術をすること、このような手順を踏んでいかなければいけないので、その辺の手順、取組みについてもしっかりとお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"大倉委員","kind":"質問","question":"３６１ページ、市民科・各教科充実経費から情報モラル教育について、３６７ページ、子ども地域活動支援経費、それから、３７２ページの学校管理費から天然芝管理について伺います。昨年の予算特別委員会や先の決算特別委員会等でもさまざまご指摘があった中で、どのように具体的に変更になったのか教えてください。","respondent":"村尾教育総合支援センター長、品川庶務課長","answer":"今後、インターネット関係の業者とうまく連携を図りながら、新しい取組みの必要性、また今の取組みの改善点等も参考にさせていただきながら進めていこうと考えているところです。これに対しましては、来年度より、４年生以上については希望者にスタンプカードを配布していくという対応をとっていきたいと考えております。","id":"exchange-076"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりとした取組みを進めていっていただきたいと思います。そこで、例えば、子どもたちが中心となって主体となって考えていくような、文教委員会でも視察しました下関の少年サミット等、主体的な取組みについて、ぜひ進めていっていただきたいと思いますが、その辺のお考えを教えていただきたいと思います。ぜひ押せるようにしていただきたいと思います。","respondent":"村尾教育総合支援センター長、品川庶務課長","answer":"昨年、それから本年度、特にネットに関するいじめをどうしていこうかということで、本当に子どもたち同士、小学生も入っていますけれども、中学生の意見を聞きながら、それぞれ聞いた感想を述べ、また学校に帰って。１２月に行われます総合防災訓練のところで、このスタンプカード事業を行ったらどうかということだと思いますが、案としては非常にいいことで、総合防災訓練は、確かに子ども等の参加が少ないということが。","id":"exchange-077"},{"speaker":"大倉委員","kind":"質問","question":"防災教育という部分においても、防災活動に積極的に参加してもらえるようになるために、まず一歩として参加してみるというところで、その意識付けというところで、ぜひ使っていただければと思いますので、いろいろ検討をよろしくお願いいたします。時間がないので、芝生のほうにいきます。学校管理から天然芝の管理について伺います。","respondent":"品川庶務課長","answer":"ですので、保護者の方等も卒業を期にここから離れるということもありますが、このくらいの大きな組織で芝を維持しているですので、今後も、学校と地域で協働して、芝の管理はしていきたいと考えております。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"グローバル人材に必要な能力は何でしょうか。それから、このグローバル人材育成の目的と、ゴールとしてどういうものをイメージされているのかを、まずお聞きします。そして、次に、市民科です。その中で、どういうふうなすみ分けをしながら進めていこうとしているのかお聞きします。最後に、教職員健康管理のところで、午前中の質問にありましたが、ストレスチェックを９９％やっていますと。","respondent":"渋谷指導課長、村尾教育総合支援センター長、品川庶務課長","answer":"私のほうからグローバル人材育成に関するご質問にお答えしたいと思います。それ以外にも、教職員の研修ということで、それぞれ先生方からさまざま意見を取り上げながら、特に初任者研修、二年次については。東京都の教職員総合センターのほうでは、そういうプログラムがございまして、こころとからだの健康運動プログラムというのがありまして。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"グローバルの捉え方です。国際化とは全く違うと私は認識しておりまして、インターナショナルというのは国家と国家の２カ国でやっていく、まさにグローバル給食などもそれでやっていると思うのですが、これから求められるものは、多国間の中で地球全体をどう捉えていくか、マトリックス的に考えていく人材ということになるので、とても大きな内容になってくるのです。","respondent":"渋谷指導課長、村尾教育総合支援センター長、品川庶務課長","answer":"ただ、私どもが義務教育段階でグローバル人材というときには、先ほどの繰り返しになりますけれども。来年度もいろいろな事業が多くなっていく中で、人員の確保については課題ではありますけれども、現在、組織が集約することによって。ストレスチェックのほうですが、やはり個人個人、症状によっていろいろ違うものが出てきますので。","id":"exchange-080"},{"speaker":"沢田委員","kind":"質問","question":"３６１ページの小中一貫教育推進経費、３６３ページの体力向上推進事業、それから３６７ページの教科書採択事務についてお伺いします。教科書採択事務のことでお伺いしたいと思います。平成２１年以降、教科書会社２２社中のうち１２社が、教科書を採択前に教員に見せていたということで、さらにそのうちの１０社が謝礼を払っていたということです。品川区の状況について、お聞かせください。","respondent":"渋谷指導課長","answer":"品川区におきましても、大変申し訳ない状況ではありますが、現在、在職している教員の中で７名が報告の調査対象になっているものです。","id":"exchange-081"},{"speaker":"沢田委員","kind":"質問","question":"７名ということで、教科書を見たのが７名なのか、それとも謝礼を受け取ったのが７名なのか、非常に残念なことでありますけれども、この中で教科書採択に直接、または間接的にかかわっていた方もいらしたのでしょうか。","respondent":"渋谷指導課長","answer":"教科書採択に関与ですが、品川区の教科調査研究会、一番ベースになる各教科の調査資料を作成する委員としてかかわったものが２名、それから、東京都の教科書の調査委員をしているものが１名、７名のうち３名が何らかの形で関与したことになります。","id":"exchange-082"},{"speaker":"沢田委員","kind":"意見","question":"教科書採択については、何度か私も取り上げてきましたけれども、そのたびに公正、公平な環境のもとでの採択がされているかと聞かせていただいていましたし、区としても、していますという答弁をいただいておりました。改めて、今後の対応、教員の倫理観についてどう考えていくのか、区としてのご対応について聞かせてください。","respondent":"渋谷指導課長","answer":"委員ご指摘のとおり、教科書については公正、公平、また透明性をきちんと担保した中でしっかり行わなければならないものだということを、しっかり認識しています。","id":"exchange-083"},{"speaker":"沢田委員","kind":"質問・要望","question":"二度とこのようなことが起こらないようにしていただきたいと思います。特に４・３・２の３の部分が分離しているということですから、そのあたりの連携について、具体的にどういうふうにやられているのかお聞かせください。それから、小中の教員免許を両方持っている方はどういう配置になっているのか、お聞かせいただきたいと思います。","respondent":"渋谷指導課長","answer":"具体的にどういった連携をとっているのかですが、例えば４・３・２のくくりの中で、４年生までは指導を徹底して基礎基本を身につけさせるということで、４年生の終わりに区の学力定着度調査を実施して。","id":"exchange-084"},{"speaker":"沢田委員","kind":"意見","question":"今お話があった、特に４・３・２の３のところの分離型の中での連携というか、どういう形で６年生から７年生につないでいくのかというのは、いろいろとまた課題があるところだと思いますけれども、今、そういった形で連携しているということで、特に分離型から一体型のほうに進学した場合の対応については、慎重に、丁寧にということで、先ほどもご説明がありましたけれども、区内を見てみると。","respondent":"渋谷指導課長","answer":"７年生の学力の結果というのは、当然、５年生、６年生で学んだことの成果も出てくるわけですので、中学校中心に、一貫校もそうですし、単独中学校もそうですが、夏休みに、連携する小学校の先生たちが集まって、そこに入学してきた７年生の子どもの学力の状況を検討して、また。","id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"しっかりと対応をとっていただきたいと思います。最後に、先ほどもありましたけれども、学事制度としての前期、後期という課程の表現が今年からいろいろ出てきたと思うのですけれども、教育方針上の４・３・２と、前期課程、後期課程という表記の仕方ですけれども、それは誤解が生まれている部分はあると思うのです。それについて、区としてはどう考えているのかお聞かせください。","respondent":"渋谷指導課長","answer":"４・３・２がわかりやすいのかというと、ご指摘のとおり、ここは保護者アンケートでもさまざまご指摘をいただいているところですので、学事制度的な６・３と、教育内容としての４・３・２のわかりやすい説明、また、整合性をつけるような形で、今後。","id":"exchange-086"},{"speaker":"沢田委員","kind":"質問","question":"子どもの体力向上推進についてお聞きしたいと思います。本格的に子どもの体力向上について取り組んでいる中で、昨年１年間の取組みの成果、テクニカルアドバイザーを導入したり、品川スポーツトライアルということを行ってきたと思うのですけれども、この状況と成果についてお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"５月の当初に比べて随分向上した結果が出ております。テクニカルアドバイザーですので、技能指導をよくやっていただいており、その中で、子どもたちからは、できないことができるようになった、このような形で答えた子が多く出ております。","id":"exchange-087"},{"speaker":"沢田委員","kind":"質問・要望","question":"２０２０年のオリンピック・パラリンピックに向けて、品川区からもオリンピック選手、パラリンピック選手が出るように、これからも体力向上にしっかり取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６５ページのマイスクール八潮、マイスクール五反田に係わって、都立定時制高校廃止計画撤回を求めて質問します。昨年第４回定例会以降、何をしてきたのか伺います。そして、改めて、小山台、雪谷、江北、立川４校の都立定時制高校廃止計画の撤回を東京都に求めるべきだと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"都への要請等ですけれども、これはあくまでも東京都の教育委員会のほうの施策ですので、本区において、存続について申し出るというような活動をしているものではございません。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"東京都の議論を注視してきたということですけれども、具体的にはどういったことをやってきたのか伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"言葉どおり、都がどのような形で議論され、どのような結果になったかということを、こちらは受けたという、それだけです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"ただ見てきただけというような感じを受け取ってしまうのですけれども、今、都によって決められたということで、都に対して何も言わないということですけれども、その理由について、内容を詳しく教えてください。","respondent":"村尾教育総合支援センター長","answer":"何もしなかった理由というご質問ですけれども、東京都の定時制高校につきましては、都立ですので、本区から何かしなかった理由というよりも、そもそもするべき内容ではないので、こちらとしては特に東京都のほうに何かをしたということはございません。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"小山台定時制高校の前にある武蔵小山駅前でも、１時間で２００名分集まりました。参加した方にお話を伺うと、ひっきりなしだったと、中には、どうしてそんなひどいことをするのか、勉強したいという人の場をどうしてなくすのかと怒りの声が寄せられました。これだけ４校の定時制高校が必要とされているのです。区は、どうして定時制高校がこんなに必要とされている、大事にされていると思いますか、伺います。","respondent":"村尾教育総合支援センター長","answer":"それに伴って、それぞれ定時制に通っている、または定時制に通った人たちの意見は意見としてあるのですが、東京都のほうではさまざまな事情を踏まえて、今回廃止をし、また新たにそれに関する、代替ではないですけれども、チャレンジスクール等で、そういう子どもたち、また。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"私は、学びたいという人にとって、かけがえのない定時制高校だからこそだと思います。定時制高校では、家庭の環境も、境遇も、年齢も違う仲間が、４年間机を並べて過ごす中で、さまざまな事情を抱えた人たちの学びたい、成長したいと思うことができる大切な場だと思います。定時制高校の役割とは何か、どういう生徒の受け皿になっているのか、伺います。","respondent":"村尾教育総合支援センター長","answer":"現在においては、その生徒の数が減ってきたとともに、多様な生徒が存在するようになった、そこにおいて、東京都のほうでは、さまざま検討した結果、今回の決定に至ったと、私は認識しております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"当初、勤労学生が多かった、今減っているからということですけれども、勤労学生というのは正社員しか入っておりません。今、非正規が増えている中で、働きながら通っている方も多くいらっしゃいます。だからこそ、反対すべきだと思いますが、いかがでしょうか。だからこそ、大崎定時制高校をはじめ小山台、雪谷は大切な進路先ではないでしょうか、伺います。こうした生徒の痛みを、区はわかりますか。","respondent":"村尾教育総合支援センター長","answer":"ただ、今回の東京都の計画に対して、私どもが賛成とか、反対とかという立場ではございませんし、今後、東京都としての考え方を十分に踏まえながら、区としては、進学先の対策、または子どもへの紹介等は十分にしていかなければならない、そういう立場ですので、悲しい部分とか。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"悲しいとか、そういうことではないということですけれども、そこを聞いたわけではないですね。いじめなどを受けて、生徒がそういったことを受けた友達に会いたくないといったときに、選択肢が狭まってしまう。その生徒の痛みがわかっているのかということです。小山台、雪谷、江北、立川４校の都立定時制高校廃止計画の撤回を東京都に求めるべきだと思いますが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"痛みがどうのという話ですけれども、繰り返しますけれども、全ての定時制高校がなくなるという話ではございませんので、やはり子どもたちにとって、そのような形、またそれ以外に不登校関係も含めて、対応していければと考えております。","id":"exchange-095"},{"speaker":"若林委員","kind":"質問","question":"３６７ページの特別支援教育費と、３６１ページのプラン２１推進事業についてお伺いします。特別支援教育費ですが、平成２８年度の特別支援教育の充実について、ご説明をお願いいたします。それから、本定例会の一般質問のご答弁で、庁内療育支援ネットワークについて、「今後は政策的な課題にも対応できるように、課長級の会議体として再構築を検討していきます」という福祉部門からの答弁がございました。","respondent":"村尾教育総合支援センター長","answer":"各部署での取組みや現状、特別支援に関するものをしっかり把握できるベースというか、ホームグラウンドだと認識をしております。","id":"exchange-096"},{"speaker":"若林委員","kind":"質問・要望","question":"プラン２１に移ります。平成１１年度からこの事業が始まりまして、学校選択制が始まりました。これは本来、校務を司る校長先生が行うものではないかと、私は思ったのですが、ご認識を伺いたいと思います。これについて確認をします。それから、この位置付けはどういうことになるのか教えてください。最後に、ルネサンスを教育委員に諮った際、どのような意見があったのか、お聞かせいただきたいと思います。","respondent":"渋谷指導課長","answer":"例えば、国語の指導の工夫とか、いわゆる教育方法の工夫改善だったり、また、そういったことに一生懸命取り組んでも、校長先生が変わると、今までぐっときていたのが、またがらっとゼロからやり直しになったり、そういったことの繰り返しで。","id":"exchange-097"},{"speaker":"若林委員","kind":"質問・要望","question":"最後の教育委員の話は、定例会、臨時会がありますけれども、具体的に平成何年何月何日に諮って、議案として出したのか、報告として出したのか、そういう公的なところで、もう一度ご答弁をいただきたいと思います。こういう図式の中で、いわゆる学校の組織運営とか、教育活動についての根本的な、またよりどころとなるものは何なのか、お聞きしたいと思います。","respondent":"渋谷指導課長","answer":"教育委員会では、正式な議題としてルネサンスを上げたという記録は確認できておりません。","id":"exchange-098"},{"speaker":"若林委員","kind":"質問・要望","question":"そこはわかりました。そういう認識でいけば、改めて各学校の経営方針の書きぶりというのでしょうか、私も全部見たわけではないのですけれども、そういうものが大分違うと思います。この書きぶりの格差というと違うのでしょうけれども、これは何なのだろうと、今回改めて見させていただいた率直な感想ですので、これについてお話をお聞きしたいと思います。","respondent":"渋谷指導課長","answer":"今後は、グランドデザイン、ビジョン展開シートを必須のものとして位置付けておりますので、それに基づいて経営方針をしっかりと記していくように、またそれはきちんと地域の方にお示しするように、指導のほうは徹底していきたいと考えているところです。","id":"exchange-099"},{"speaker":"若林委員","kind":"質問","question":"これまで、選択制も含めてさまざま、例えば、本日ずっと出ておりますが、４・３・２制と６・３制の話、ただいまの学校選択制の話等々、いわゆる小中一貫教育が始まってもう１０年がたって、いまだに地域、また保護者の理解と協力が進んでないと、私の言い方ですれば、そういうふうな現状です。これまで、公式にそういう方々のお声を聞く場はあったのでしょうか。","respondent":"渋谷指導課長","answer":"今回のフォーラムも、そういう意味では、地域の方たちにきちんと教育委員会のこれからのルネサンスという方向性についてご説明をして、また、広くご意見を求めて、皆さんの声に耳を傾けながら施策を進めていきたいと考えているところです。","id":"exchange-100"},{"speaker":"若林委員","kind":"提案","question":"家庭でも、町会でもばらばらの意見が出る。議事録を見ましたけれども、市長も皆さんの意見、提案をお聞きして、また、ＰＴＡ側も、出席側もいろいろな提案をして、一緒にやっていきたいという、品川区で言うと、区で拡大会議を開くという場面の議事録を見させていただいて、非常に建設的な総合教育会議が京都市では開かれているのかなと、傍聴はしたことありませんけれども、そういう率直な感想があります。","respondent":"渋谷指導課長","answer":"先ほどちらっと申し上げましたけれども、校区教育協働委員会で、夏休みには熟議という形で、各校区ごとに地域の方、保護の方に入っていただいて、教育問題について議論する場を、今後はきちんと位置付けていこうと考えています。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"さまざまな工夫をされて、お声を聞いていると。そういう中でも、本日の款別審査の中でも、さまざま区民の声を代弁されている委員がいらっしゃいます。ぜひ、建設的な関係ができるように頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"石田（し）委員","kind":"提案","question":"私からは、３６３ページから３６５ページの英語教育について、３５９ページ、いじめ対策について、３６１ページ、市民科について、３７３ページの学校ＩＣＴの活用についてお伺いしていきます。英語教育についてですが、もう先ほど来、各委員からいろいろなことが質問、また提案もされているので、率直にお聞きします。それから、市民科についてですが、一つは選挙権年齢が１８歳に引き下げられる。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"英語教育がどのように変化してきたかですが、私どもが受けてきた英語教育は、どうしてもやはり入学試験を前提としたものですので、文法を中心に読むこと。３点目、選挙権が１８歳からになるということで、区としては、市民科の中で、すぐに来年からということではないのですが、本年度から研究を進めている中で。そのほかの通常学級におけるＩＣＴの導入状況ですが、短焦点のプロジェクターについては、これはもう導入校についてはなくてはならないもので。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"英語教育ですが、１点、国際友好協会と連携して、青少年の語学研修の派遣をされておりますが、今、学校長の推薦枠もある中で、参加された子どもたちが帰国後に何らかの発表というか、その学校の子どもたちに、こういった取組みをしてきた、活動をしてきたということを発表する場があるのかどうかだけ、ちょっと確認したい。これは要望で終わります。英語教育の部分をよろしくお願いします。","respondent":"渋谷指導課長","answer":"総務課でやっている広島・長崎への平和使節派遣も同様でございまして、各中学校の代表者が参加したものについては、きちんと発表する場を設けて還元をして、またそういった子どもたちがより一生懸命やりたいという動機付けに役立っていると報告を受けております。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問・要望","question":"一番知りたいのは、品川区に一切関係したことのないような教員の方々や教育関係者、そして、例えばですけれども、公務員ではない、教育者ではない教育関係者というのか、例えば教科書会社や塾の関係であったり、いわゆる民間というのでしょうか、そのような方々がどのくらいお見えになっていたのか。今も申し上げましたように、３６１ページ、プラン２１推進事業ということで伺いました。","respondent":"渋谷指導課長","answer":"３年後には、新しい品川教育要領を策定します。それに向けての準備も平成２８年度から始めていくということで、今まで品川区がさまざま取り組んできた教育の成果にさらに上乗せして、新たな品川教育を創生していくと、そういうふうな旗印として考えているところです。","id":"exchange-105"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。ということは、これがＰＴＡの方々とか、いわゆる地域の方々にどこまで知られているかというと、実は知られないまま４月に始まるのかと思いました。そういうことを、やはりしっかり周知徹底していただきたいですし、逆に、これがそういう機会ですから、さまざまな意見をいろいろな方から聞くような体制づくりが必要と思いますけれども、その辺はいかがお考えでしょうか。","respondent":"渋谷指導課長","answer":"今回の教育フォーラムが、品川教育ルネサンスをきちんと大々的にアピールしていく第一歩だと考えておりますので、この後、さまざまな機会、また場面を通じて、教育委員会が何を考え、どういう方向に進むのかということの周知については。","id":"exchange-106"},{"speaker":"渡部委員","kind":"質問・要望","question":"６年後の要望までさせていただきましたので、よろしくお願いいたします。学事制度審議会をやってくださいという質問をしていても、なかなか、やりますという答弁もいただけない感じだったのが、風向きが変わって、いよいよ平成２８年度に学事制度審議会が行われます。改めて伺います、学事制度審議会を平成２８年度にやる目的と背景、教育委員会のお考えをお聞かせください。","respondent":"野呂瀬学務課長","answer":"中学校区を基本とした、地域とともにある学校づくりとして品川コミュニティ・スクールのことや、今後の品川区の教育のあり方を検討すること、その中で、今委員もおっしゃったような、学校規模や学校配置、または学校選択制についても、その審議会の中で、必要があれば検証。","id":"exchange-107"},{"speaker":"渡部委員","kind":"質問・要望","question":"子どもが増えてきて、学校の教室が足りなくなるということが数年先に見えている中で、待ったなしですから、これはしっかり進めていただいて、しかるべき方策を立てていかなければいけないと思います。実は平成１２年から学校選択制は始まりました。もう１回確認ですけれども、そもそも兄弟枠はどのような経緯でできてきたのか教えていただけますか。","respondent":"野呂瀬学務課長","answer":"いろいろ優先順位があるのですけれども、一度入った子どもについては、空きがある場合は、その兄弟、姉妹については優先的に枠の中で受け入れていこうという制度です。","id":"exchange-108"},{"speaker":"渡部委員","kind":"質問・要望","question":"制度はわかるのです。それに対して、当然、この地域においては法律の中ではルールがあって、この人数なのだから、それはしようがないのではないかと、私は言います。これからの子どもの安全・安心、防災上の観点から考えるのであれば、何とかこの辺もう一度、仕組みを含めて考えていただきたいのですが、兄弟枠に対しての考えをお願いします。","respondent":"野呂瀬学務課長","answer":"ただ、他方で、今委員がおっしゃったように、防災上の観点ということはありますので、一応今のところのルールとしては、あくまでも通学区域が優先だと、その中で兄弟枠というのは、今おっしゃったようなことも含めて、今後また必要があればその中で検証。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問","question":"これはやはり、法令上きちんとした形になったので、義務教育学校前期課程、あるいは後期課程というような形で、予算上にもはっきりと分けて表記をするべきだと思いますが、どうして平成２８年度の予算に義務教育学校という形で分類ができていないのかお尋ねします。それから、三つ目は、幼児教育の成果についてです。これは何か特別な教育指導を成された結果だったのでしょうか。以上、そこまでお願いします。","respondent":"品川庶務課長、今井待機児童対策担当課長、竹田保育課長","answer":"私のほうからは、予算上の分類についてお答えしたいと思います。今後、私立保育園の開設に向けまして、具体化に向け、またお話を進めていきたいと考えております。ぷりすくーるでは先進的な教育を数々取り組んでいるところですが、私立小学校進学に向けた特別な教育をしているというのは承知しておりません。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"教育・保育要領が独自に定められていて、特に１歳から５年間教育を受けた子どもがその中には含まれているという話をお聞きしました。それプラス、今お話になったような保護者の方の希望に沿った、進学に関するものなどを進めていくと思うのですが、今後のこういった品川版の公設民営の方法を進めていくという民営化の話もありますけれども、このことに関する行政のほうの見解をいかがでしょうか。","respondent":"竹田保育課長","answer":"ぷりすくーるについてのご質問です。先ほども申し上げましたとおり、先進的な事業に数々取り組んでいるところです。０歳から２歳については、児童福祉法に基づいて、３歳から５歳については幼稚園教育要領に準じた教育を、今後も進めていくところです。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういった形で、その成功例を他にも広げていっていただきたいと思います。そうすると、それが加熱していくと、不正行為につながる。不正行為に関しては、起きない体制を学校側がどうつくるかというところがポイントで、そういった点において、試験の監督体制はどのような形でしょうか。そうした事件が起きないような体制づくりに関しては、どう取り組んでいらっしゃるのでしょうか。","respondent":"野呂瀬学務課長","answer":"今回は初めてということもあって、今後また志願者数は増えていくと考えられますので、今回やったことを踏まえて、体制づくり、試験監督も含めて、不正行為につながらないような形でいろいろ検討していきたいと考えております。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"オンライン英会話は、浜川中学校では、大変に効果が上がっていると。あれはタブレットを使っているのですが、タブレットを使わない形で今後拡大していく予定はどうか。それから、英検の助成は、小学校の英語の先生が受験をするときに助成をするという考えは、いかがでしょうか。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"オンライン英会話については、コンピュータ室でも十分にできますので、対象校を拡大という方向で頑張っていきたいと思います。小学校の先生に、というお話ですけれども、今のところは小学校５、６年生の一部助成ということで、現状の助成の範囲で考えていきたいと考えております。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回、品川区がいじめ防止対策推進条例を提案していますけれども、改めて、私たちは改善をするべきだとさまざま求めてきました。私は、こういう説明をする場でも、ぜひ皆さんからこの条例に対してさらにどういうふうにしたらいじめをなくしていくことができるというところで意見を聞く姿勢でやっていただきたいと思いますけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"いじめ防止についてのご質問です。品川区いじめ防止対策推進条例ということで、今の予定としては、４月施行に向けて、今さまざまな調整等に取り組んでいるところです。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私たちは、条例をつくることそのもののところで、条例提案をしました、議会ですぐに決めましたという、こういうことではなくて、区民にこれを知らせて意見を求める、そういう話し合いの中で、いじめの問題について考える機会にして、真剣にみんなで取り組んでいくことになっていくというように、ぜひやっていただきたいということで求めてきたわけです。それでもあえてこういうふうに禁止という形で明示する。","respondent":"村尾教育総合支援センター長","answer":"いじめは、どの学校でも、またどの子どもでも起こり得る、また加害者にも被害者にもなり得るという前提でいますので、この条例等を含めて、子どもたちと、しっかりいじめ防止に向けて一緒に取り組む姿勢で臨みたいと考えております。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、そういう人間関係を教育の中でつくり上げていくということこそ必要だと思います。私が伺ったのは、なぜいじめをするのかという、そのいじめを行う子どもが抱えている悩みやストレス、その苦しいところに共感をしながら、人間的に立ち直っていくところへの支援が必要なのではないか。ここのところをお聞きしたいので、お願いします。","respondent":"村尾教育総合支援センター長","answer":"加害者、被害者については、条例の中では第１７条の中にも含まれていますけれども、被害者への支援だけではなく、加害児童への支援や指導、その辺についても学校教育の中で行う部分ですので、当然に、その子どもたちのいろいろな日常的ないじめに至った背景や原因を聞きながら。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"養護教諭を増やしてほしいということは、いつも現場から聞いているところですけれども、一定規模以上の学校への複数配置、そしてもう一つは、スクールソーシャルワーカーですが、４人ということで、１,６６５万円ということで予算書に出ていますけれども、一人当り４００万円ということで、ぜひ正規化をしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"当然、なかなか人数的にはということはありますけれども、学校にとっては、ソーシャルワーカー、またスクールカウンセラー等を活用しながら、いじめ問題に対して対応できていると思っているところです。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回、いじめ防止対策推進条例ということで、私たちは提案もさまざましておりますけれども、そういうところも、ぜひこれから改善に入れていっていただきたい。それから、せっかくこういうことで条例がつくられるのですから、この条例をつくったと同時に、予算もこれだけ付けて、体制もつくったという形で、ぜひやっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"提案","question":"マイスクール五反田につきましては、午前中に新妻委員の質問で、いろいろ概要を伺ったのでわかりましたが、実は古い話で恐縮ですが、私も平成１６年の第４回定例会で、このときは引きこもり、ニート対策ということで、メンタルフレンド訪問事業を提案させていただいて、そのときはあまりいい答弁ではなかったのですね。それから、各種検診等委託について。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"都のほうは逆に、今後、品川区が行っていくマイスクール五反田のような初期対応のやり方を学ばせてもらいたいというような電話があったですので、都とはいろいろな事業で連携しながら。モアレ検査は、今考えているのは、大体１２月か１月くらいになる。ですから、定期検診の中では実施しないで、２学期以降と考えております。対象学年は、今のところ５年生と７年生を考えております。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"メンタルフレンドはわかりました。だから、そんなに重くはないと思うのですが、残念なから小・中学校のときに発見できなかったということで、そういう面では、こういうのが導入されて、一日も早く実施していただいて、一人でも多く、特に女性が多いということで、今は体操をやれば少し改善されるというようなこともあるので、早期発見をぜひよろしくお願いしたいと思います、要望します。","respondent":"村尾教育総合支援センター長、野呂瀬学務課長","answer":"マイスクール五反田のメンタルフレンドの活用です。現在、子どもたちへの対応ということで、実際に現在、調整しておりますのは委託という形で考えています。今、委員おっしゃっているように、近見視力というのは、これからパソコン画面などを判読するために必要な視力となるのかと思います。今のところ、学校現場からそのような声は、私どものほうに入っておりません。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"質問・要望","question":"既に何年も前に、実際に大阪あたりでは得意な先生がいろいろ調査したりしているのですが、その中で、先ほど申し上げたように、全体の５％くらいいるというようなことにも触れられておりました。これは、一応意見をいただきたいと思います。どうやったら改善されたかというと、喫煙者が４割減ったという。そういうことを踏まえて、もう１回、力強く最後に答弁をいただきたいと思います。","respondent":"野呂瀬学務課長、村尾教育総合支援センター長","answer":"学校の視力検査はスクリーニングとして行われているため、個々に適した検査をするのはなかなか難しいところはあります。がん教育のお尋ねです。がん教育の実施においては、先ほどもご答弁したとおり、さまざまな国、また全国的な実践が行われている中で、本区でも本年度実施してまいりました。","id":"exchange-121"},{"speaker":"伊藤委員","kind":"質問","question":"結果として犯罪が起きたということは、たくさん報告されているのであります。学校現場ですることはもちろん正しいことだけれども、帰るところが、もし万が一そういう価値観であるならば、子どもがそうなってしまう可能性が高いので、いじめをなくすという観点からすると、そういうところまでさかのぼっていかなければいけないと思うのですが、いかがでしょうか。品川区のご見解をお聞かせください。","respondent":"村尾教育総合支援センター長","answer":"その中で根本的な解決という部分では、子どもに指導することも当然ではありますけれども、保護者であったり、育っている部分に何らかの影響があるのではないか、また、要因があるのではないかということで、実際に、先ほどお話もありましたけれども、ＨＥＡＲＴＳ等が。","id":"exchange-122"},{"speaker":"伊藤委員","kind":"質問・要望","question":"誰も、暗い学校とか、いじめの不幸な事件を繰り返したいとは思っていないわけです。今、お話があったように、私たちは、家庭訪問を随分言ってきました。やはりいろいろな情報が前よりは集約できるようになったのでしょうから、それを早期に集約していかないと、早いうちにその芽をつむことはできないと思うので、ＨＥＡＲＴＳの早期展開についてのご見解、考え方をお聞かせください。お願いします。","respondent":"村尾教育総合支援センター長","answer":"対人関係が苦手であったり、友人関係がうまくつくれなかったり、また日々の生活の中でさまざまストレスを抱えている子、また、今では進学等を含めて、さまざま子どもが抱えている問題は事前に担任、または学校全体で把握しながら、その状況をつかみ。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"だから、ぜひそういう観点で進めていっていただきますように、お願いをしておきます。そういうことからすると、特別支援教育、確かにそういう方々が対象なのだけれども、それぞれの児童・生徒の能力や個性に応じた内容の展開と同時に、その子の一生を考えた施策を展開していかないと、大きな禍根を残すことになると思うので、品川区のお考えをお聞かせください、お願いします。","respondent":"村尾教育総合支援センター長","answer":"学校のほうは、それを受けながら、保護者と一緒に個別の指導計画を立てながら、個に応じた教育、この子のいいところはしっかり伸ばそう、そして、課題のある部分については、どうやってうまく支援をしていこうか、その辺をしっかり話し合いながら。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"ちょっと款が違ってきますけれども、埼玉県の発達障害支援プロジェクトというものがあります。埼玉県の福祉、障害医療、教育、それから総務等が一丸となって、このプログラムを作成した結果、幼稚園での早期発見が２７.４％から８２.３％になったということ。それから、次は６７.９％に増えたということ、保護者の意識の変化が８４.７％あったということがあります。","respondent":"村尾教育総合支援センター長","answer":"障害のある子どもの実態をしっかり把握し、子ども、そして保護者、また、その周りにいる人たちの希望を聞きながら、教育、そして保健、福祉、医療関係がしっかり連携を図りながら、長期計画を考えて、またその子どもに応じた教育、支援。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要望としては、乳幼児期、それから学齢期、成人期、高齢者期というのでしょうか、それぞれのライフステージがあるわけですね、障害児・者の方々は。それから、防災教育であります。学校現場で大規模災害が発生した際に、何よりも大切な子どもたち、児童・生徒の生命を守るために、絶対に防災教育が必要だと思うのですが、学校現場での具体的な展開はどうなっているのでしょうか、お聞かせください。","respondent":"村尾教育総合支援センター長","answer":"大きな災害等の発災時を含めて、今の防災対策についてのお尋ねだと思います。学校においては、基本的には災害に適切に対応できる能力、そして、主体に行動する体力の基礎を養う、これを基本として防災教育を進めているところです。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろんやっていただていることは正しいことなのですよ、それはもちろんやっていただきたいのだけれども、でもあれだけ首都直下型地震に対する被害想定も出ています。ですから、今おっしゃったようなことをやっていただくことも、もちろん必要だけれども、被害想定が出ている以上は、それに対応する具体的な展開を各小・中学校で防災教育を展開するべきだと思うのですが、いかがでしょうか。","respondent":"村尾教育総合支援センター長","answer":"各学校において防災課と協力しながら、学校のほうでさまざまな訓練を実施しています。特に中学校においては、ポンプ隊や消火活動やバケツリレー等、さまざまな形で子どもたちも参加しながら進めているところです。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問","question":"私は、３６１ページの小中一貫教育推進経費に、それから３６５ページ、マイスクール五反田運営費、そして３６９ページ、図書館経費、それから３７３ページの学校環境整備事業になるかと思います、それぞれお伺いしたいと思います。ただ、区内では図書館で高齢者向けの紙芝居というのは、どの程度蔵書があるかということをお伺いしたいと思います。以上、お願いします。","respondent":"渋谷指導課長、木村品川図書館長、品川庶務課長","answer":"１点目の分離型の特徴というご質問にお答えしたいと思います。子ども向け紙芝居というのは所蔵しておりますけれども、いわゆる高齢者向けという形では蔵書はございません。今後の環境課との連携ですが、こういうシックスクール関係、また新たな情報が入り次第。","id":"exchange-128"},{"speaker":"あべ委員","kind":"質問・要望","question":"ああいうのを見ると、品川区として、分離型をどのように見ているのかということが、分離型に通わせている親御さんにも不安な思いを抱かせたりしますので、そういう意図がないにしても、少しご留意をいただきたいと思います。それから、マイスクールのほうに移ります。マイスクール八潮のほうがいっぱいになっていて、２カ所目の設置ということで、この間、何度か求めさせていただきました。","respondent":"村尾教育総合支援センター長","answer":"そういう中で、今回、マイスクール八潮と同じような規模のものをつくるのではなく、あくまでも初期対応することによって、子どもが若干集団に慣れないとか、またさまざまな心配事がある場合、環境を変えることで少しほっとする部分があり。","id":"exchange-129"},{"speaker":"あべ委員","kind":"質問","question":"大変期待するところですが、一方で、マイスクール八潮では、発達に課題のある子どもへの手が、どうしても回りにくいというお話を以前伺いました。三つ目には、民間のフリースクールと東京都の連携というのも、今後考えていってほしいと思うのですが、そこはいかがでしょうか。やはり学校復帰となると、特にステップが必要だと思いますので、そういったことも考えていらっしゃるかどうか、お願いします。","respondent":"村尾教育総合支援センター長","answer":"今後、マイスクール五反田につきましても、発達に課題のある子どもに対して、どのように適切に対応ができるか、それは学校内において都費のスクールカウンセラー等の協力も得ながらできることかどうか、または、本区で行っている巡回相談。","id":"exchange-130"},{"speaker":"あべ委員","kind":"質問・要望","question":"少し時間がありますので、先ほども少し出ておりましたが、小山台の定時制高校についてですけれども、これは多文化共生の分野に非常に手厚い特徴、積み重ねを持っていらっしゃるということで、この蓄積を絶やさずどこかにつなげていくというようなお話が、もし都教育委員会から聞かれていたら、教えていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"具体的に東京都のほうから、蓄積したさまざまなノウハウをどこかで使うというようなお話は伺っておりません。","id":"exchange-131"},{"speaker":"あべ委員","kind":"質問・要望","question":"全体の配置は、都立高校なので東京都ということになると思うのですけれども、その中で蓄積してきたものが、ぜひ地域の子どもたちが受け取り続けられるような形で、ぜひきめ細かい情報交換をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問","question":"３６３ページ、学校地域連携推進経費のコミュニティ・スクールについて伺いたいと思います。ほかとの違いがあるのか教えてください。それから、学校地域コーディネーターとありますけれども、これはとても大きな役割を果たしていく人になっていくと思うのですけれども、これは誰が選ぶのか、推薦するのか、そして誰が採用するのか、勤務時間、そして賃金はどうなっているのか伺いたいと思います。","respondent":"渋谷指導課長","answer":"したがいまして、当初、浜川は浜川中学校区ということで一つの校区教育協働委員会を立ち上げてやっていくということでしたが、実際にモデル実施をすると、なかなか各校の調整が難しいということ、また学校支援そのものが。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問","question":"コーディネーターのところは、時給１,０００円ということでしたけれども、週何日とか、勤務時間はどうなるのかを伺いたいと思います。それから、元ＰＴＡ会長や現ＰＴＡ役員から、私も率直にお話を伺ってきました。今は、両親共働きが多い中で、忙しいと。何とかそんな中でＰＴＡもやられているとのことでしたけれども、コミュニティ・スクールと親たちの関係はどうなっていくのでしょうか。","respondent":"渋谷指導課長","answer":"勤務時間についてですが、１日６時間勤務、あるいは、１日４時間勤務ということで、学校の実態に応じて選べるような制度設計を考えているところです。それから、親との関係ですが、ＰＴＡ活動と地域で支援する体制は、それぞれの地域、学校の実態に応じてすみ分けをしています。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"小中一貫教育推進委員会の中でも、ＰＴＡの代表者から、親は忙しいと、負担感が大きな課題になってくるのではないかということもおっしゃっていました。それでもとにかく進めてみようという区に対して、品川区は何がしたいのかとの声も上がっていました。今やるべきなのか、立ち止まって考えるべきだと思うのですけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"格差が出るですが、それぞれ学校がいい取組みをして、頑張っていこうというものを格差と捉えるのか、一生懸命頑張っていると捉えるのか、それは認識の違いで、いいことについては一生懸命頑張って進めていくのが、当然の取組みと考えております。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いろいろおっしゃいますけれども、やはり親、またＰＴＡの皆さんの実感もしっかり受け止めていただきたいと思います。選択制で、地域とのつながりが壊れている、壊しておいて、地域の力と言われても、都合がよすぎるのではないかと、こういった声も本当に多く聞かれました。学校選択制こそ、今見直して、さらに廃止していくという考えを検討されていくべきではないかと思うのですが、いかがでしょうか。","respondent":"渋谷指導課長","answer":"学校選択制を今のところ見直すという考えはないところです。さまざま地域の特徴に応じてコミュニティを進めることによって、よりよい地域、また地域の学校を選んでもらえる体制ができるものと考えているところです。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問","question":"そのうえで、品川区は、地域行事に参加した子どもたちに景品を出していこうと、こういった対策も打たれています。これはまさに、選択制によって地域とのつながりが壊されている、こういうことのあらわれなのではないでしょうか。やはり、地域とのコミュニティ、これを壊す学校選択制こそ今再検討すべきだと思います、廃止すべきともう一度訴えたいと思いますけれども、いかがでしょうか。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"これも何度も答弁しておりますが、学校選択制で選択している子どもたちは３割程度、いわゆる就学指定変更で、そういった手続を取っているのは、他の自治体でもその程度の変更はあるということで。今後も引き続きやってくださいという親の声は７０％以上あります。それから、学校選択によって各校の持ち味、個性を活かした教育活動に取り組んでいる、これも事実ですので、よろしくお願いいたします。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、もっともっと地域の声、親たちの声を聞いていただきたいと思います。次に、義務教育学校について、今回の一般質問でも、中止してほしいということで質問をさせていただきました。質問の中で、小中一貫校６校の構想は、統廃合の手段にすぎなかったのではないかと伺いましたけれども、「統廃合を目的としたものではない」という答弁でした。では、手段だったのかということを改めて伺いたいと思います。","respondent":"品川庶務課長","answer":"小中一貫校ですけれども、基本的には小学校、中学校の一貫教育というような形で進めてきて、つくっている学校ですので、統廃合とか、そういったものではないということだけご答弁します。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問","question":"小・中学校１８校がなくなったわけです。先日、行われた教育フォーラムで、学識経験者の方々から、義務教育学校は複線化の導入を進めるものであるといった旨の説明がありました。今までの単線化というのでしょうか、複線化を導入する前の学校のよさは何か、問題点は何だったのか、そして、複線化を導入するのはなぜか、何を目指すのか、これを伺いたいと思います。","respondent":"渋谷指導課長","answer":"単線化の問題というよりも、複線化によって多様な教育活動が展開できるということは、区民、保護者にとって最大のメリットだと考えております。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"複線化によって多様なことが進むということでしたけれども、教育フォーラムの中で、ＰＴＡの方も、小学校でもない、中学校でもない、義務教育学校が特別な学校になっていくのではないかという心配の声が出されていました。統廃合で学校をなくしておいて、教育に格差をつくり出すような、この義務教育学校はやめるべきだと私は思うのですけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"先ほどのご答弁でも申し上げましたが、義務教育学校は、単独の小・中学校教育内容に何ら変わりはございません。したがいまして、やめるつもりは毛頭ありません。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども前の委員のところでありましたけれども、一貫になった施設一体型の学校が何しろ推し出されていると、こういう中で、義務教育学校がエリート校となる、特別な学校となる、これが格差をつくり出すという、こういう不安に対して、区はどのように説明されるのでしょうか。","respondent":"渋谷指導課長","answer":"何度も申し上げておりますとおり、エリート校でも、特別な学校でもございません。品川区として均一の義務教育を保障する学校の一つです。","id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり義務教育学校、私たちは、特別なエリート校をつくっていく複線化、複線化は認められたわけですから、それが特別校の何ものでもないと、私は思います。ぜひ、コミュニティ・スクールも、義務教育学校も、一旦立ち止まって、しっかり考えて、保護者のたちの声を聞いて、子どもたち第一に考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"浅野委員","kind":"質問","question":"この内容について、質問したいと思います。ここの部分につきまして、平成２５年度予算ですけれども、こちらを見てみますと、校務システムの再構築の予算が載っておりまして、このときは７,３２２万円、今回とほとんど同じくらいの予算が計上されておりますが、この３年間という短い時間で校務システムを開発、更新しなければならない理由について教えてください。","respondent":"野呂瀬学務課長","answer":"平成３２年度で現行システムが終了なのですけれども、平成３０年度でサーバーのリースが終了するということで、それに伴って、機器と一緒に新システムに切り替えるということで、平成２８年度から約３年間かけて新システムを開発していくという経過になったものです。","id":"exchange-143"},{"speaker":"浅野委員","kind":"確認","question":"ちょっと確認ですけれども、サポートが終了すると伺いました。それから、校内ＬＡＮですけれども、１０年くらいで老朽したため更新とも聞いておりますが、これについては、今まで有線だったのを無線にするのか、またさらに高尚なことをやられるのかどうか、教えてください。","respondent":"野呂瀬学務課長","answer":"校内ＬＡＮのことですけれども、現行と変わらずに有線、無線両方活用していくと考えております。","id":"exchange-144"},{"speaker":"浅野委員","kind":"質問","question":"平成３０年にリース終了ということですけれども、途中で解約みたいな形、終了ということになると、普通はこれだけ高いシステムになりますと、サポート期限もしっかり決めて、それが業者として維持できないということになれば、違約金は発生してしかるべきだと、私は思っているわけですけれども、そのような契約にはそもそもなっていなかったということでしょうか。","respondent":"野呂瀬学務課長","answer":"もとも契約は平成３２年度までだったのですけれども、サーバーのリース期間が平成３０年に終わるということで、二重投資を割けるといいますか、前倒しで平成３０年から新システムに切り換えるということですので、業者のほうから違約金は取れないということになっております。","id":"exchange-145"},{"speaker":"浅野委員","kind":"質問","question":"話がかみ合わないようですけれども、しっかりとやっていただいているとは思いますので、これはまた別途お伺いしたいと思います。全児童を対象として、タイ国を紹介する特別授業も実施したと聞いております。今年度は、小学校２校を選定して実施するということですけれども、平成２７年度に実施したのと同じような形で実施をするのかどうか教えてください。","respondent":"野呂瀬学務課長","answer":"来年度につきましては、やり方としては同じようなやり方でいくつもりですけれども、どこの学校か、どこの大使館かというのは今のところ白紙で、新年度になってから手挙げ方式といいますか、ピックアップして学校を選んでいきたいと考えております。","id":"exchange-146"},{"speaker":"浅野委員","kind":"質問・要望","question":"食は文化と言われますので、このような交流も、子どもたちにとっても新しくて、経験できないことだと思いますので、ぜひとも成功裏に進めていただきたいと思います。例えば中学校を対象としてやるのは考えていないのか。大使館の関係もあるかと思いますけれども、何とかもう少し増やして、多くの小学生がこのような体験ができるような場を設けていただきたいと思いますが、いかがでしょうか。","respondent":"野呂瀬学務課長","answer":"今年、モデル実施ということでさせていただきました。","id":"exchange-147"},{"speaker":"浅野委員","kind":"質問・要望","question":"子どもたちにとっては、興味津々の部分もあると思います。平成２７年度については、学校のほうで手を挙げていただいたと伺っておりますので、そのような学校が多く出ることを望みますので、ぜひともそのときは対応していただければと思います。そういう意味で、残る９館にも何とか導入できるようなノウハウを積んでいっていただければと思いますが、いかがでしょうか。","respondent":"木村品川図書館長","answer":"そのほかの館への展開につきましても、その成果を踏まえて検討してまいりたいと思います。","id":"exchange-148"},{"speaker":"浅野委員","kind":"確認","question":"ぜひとも検討していっていただければと思います。それから、図書館のホームページの改修費が７７０万円計上されております。現在のアクセス数を確認しますと、２,７００万件ということで、これについては多いのか少ないのか、なかなか評価しづらいところがあると思いますけれども、これだけのアクセスがあったということ、そして、この件についての評価を一応いただければと思います。","respondent":"木村品川図書館長","answer":"ホームページの全面改修の部分ですけれども、現時点で考えておりますのは、まず、今回の改修に至った経緯といたしましては、主にセキュリティ面の強化、それから、ＣＭＳと言っておりますけれども、実際に各現場で更新ができる、そういう形の。","id":"exchange-149"},{"speaker":"浅野委員","kind":"質問","question":"今、お話を伺いまして、平成２６年度、１１０万件ですか、そういうような形で予約が入って、それで取りに行かれるということで、こちらのほうも随分と利用されているというイメージを受けました。もう一つ質問したいのですが、国立国会図書館デジタル配信サービス、利用状況ということでお伺いしたいと思います。","respondent":"木村品川図書館長","answer":"今、ご指摘がございました国立国会図書館のデジタル配信サービス、歴史的音源サービス、件数ですが、大変申し訳ございません、今、手元にございませんので、後ほど回答します。","id":"exchange-150"},{"speaker":"浅野委員","kind":"意見","question":"事前にお願いしておけばよかったのですけれども、なかなか行き届かなくて申し訳ございませんでした。これもせっかく導入をしていただきましたので、デジタル化資料閲覧サービス、または歴史的音源サービスについては、閲覧があるようにしてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-151"},{"speaker":"渡辺委員","kind":"質問","question":"３６１ページ、プラン２１推進事業、特に小中一貫教育推進経費を中心に伺ってまいります。私たちの立場から言えば、やはり地域ニーズ、行政の方の専門性以外に、私たちの長所と言えば、やはり地域の声という意味で、現場の保護者、あるいは児童の感覚を中心に、背景として伺います。その下の欄、小中一貫教育推進経費の評価経費、１６６万円、この仕組みないしあらましを教えてください。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"私からはまず、小中一貫教育推進経費の中から、推進委員会経費の部分について、お答えしたいと考えています。具体的には、このテストは６年生と中学校３年生、いわゆる９年生を対象に行いますけれども、小学校においては国語、算数とも、今のような形でおおむね都よりも高い水準をキープしております。","id":"exchange-152"},{"speaker":"渡辺委員","kind":"質問","question":"期間のところ、１年間スパンということで伺いました。もう一つは、資料で言うと、この間フォーラムで配布された義務教育学校のパンフレットを見ていて、学び直しの機会の設定とか、定期テストの導入ということで、ここを少し聞きたいと思ったのが、仮にこの義務教育学校が５年生から今までの中学校と同じようにテストがもう制度化されて、６校ともやるのかどうか、それを教えてください。","respondent":"渋谷指導課長","answer":"勉強合宿についてですが、平成２７年度は、宿泊と通いという形ではありますが、一貫校６校が実施しています。平成２８年度についても、今のところ、一貫校６校が実施です。","id":"exchange-153"},{"speaker":"渡辺委員","kind":"質問","question":"そのようなところが課題だと思うのですが、いかがでしょうか。一つは、公立学校ですから、そして品川区もやはり地域性が非常にある中で、経済的な理由で十分な学習機会が得られないケースも、就学援助の数字を見ていたら、これは全区的な数値です、当然、地域によって高い、低いがあるような気がします。この２点の見解を教えてください。","respondent":"渋谷指導課長、村尾教育総合支援センター長","answer":"施設一体型一貫校、単独の学校、それぞれについて、きちんとした取組みが推進できるよう、いい取組みについてはスピード感を持って実施できるような見通しをしっかりお示しできるように努めていきたいと思っています。まさに学力の結果が出ますので、その結果に基づいて、個々の対応については、今後とも進めていこうと考えております。","id":"exchange-154"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それは教育のプログラムもそうだと思います。大きな制度見直しがある中で、先ほど言った、教育要領の見直し、国の動向も大分大きな変動が見込まれると聞いておりますが、３年間かけてというよりは、その中でもさらにすぐできること、あるいは、中期的にやること、そして大きな見直しと、ぜひともこういう方向性を持っていただきたいと思いますが、それに対しての見解を伺いたいと思います。","respondent":"渋谷指導課長、品川庶務課長","answer":"地域特性に応じたさまざまな取組みについて、例えば英語については、国の学習指導要領の改訂を待たずにオンラインの導入をしたり、できることは迅速に取り組む。校舎の改築につきましては、周辺の人口動向、それから、学校のバランス等も見ながら検討をしていきたいと考えています。","id":"exchange-155"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":123431,"voices":362}},{"id":"h28-20160316-3","meetingId":"h28-c-budget","date":"2016年3月16日","dateIso":"2016-03-16","committee":"予算特別委員会","time":"午前１０時００分～午後５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を121件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"初めに、品川区の平成２８年度予算は１,６７８億９,８００万円。平成２７年度の１,５１０億３,８００万円に比較し、１６８億６,０００万円の増加と、過去にない規模の予算となりました。新年度予算の審査中ではありますが、区として、今後の財政運営、各種の施策についてどのように進めていくのか、お考えをお聞きいたします。","respondent":"中山企画部長","answer":"したがいまして、今後ですけれども、区としてはこのような税制改正あるいは景気の動向に十分アンテナを張りながら、区民の皆様が真に必要とする施策について、重点的な財源配分を的確に進めてまいる考えです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。的確な区政運営、また財政についても検討していっていただきたいと思いますので、よろしくお願いいたします。特別交付金は、２３区間の水平調整の問題もありますが、都区間の配分比率、２３区５５％対、東京都４５％の比率の問題、また特別区交付金５％を普通交付金に配分割合に変更する問題などの課題が残っています。この点につきましてもお答えをよろしくお願いいたします。","respondent":"濱野区長","answer":"ご案内のように、平成１８年だったと思いますが、あり方検討会が設置されて、東京都の事務で特別区に移管できる事務はどういう事務があるのかということを、検討を重ねてまいりました。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"意見","question":"あり方検討会、都区間の問題につきましては、区長も変わったというお話もございましたが、議会もかなりメンバーが変わってきて、この内容も大分わからなくなってきている状況にあると思います。いろいろ情報をいただきまして、この区議会としてもやはり一緒になって都に対応していく考え方を持っていきたいと思いますので、またよろしくお願いします。","respondent":"濱野区長","answer":"財調の課題であります。今、５５対４５ということについては、別に精密に積み上げたわけではありませんので、課題といえば課題ですけれど、緊急の課題にはなっておりません。ただ、特別交付金の５％については、２３区はなるべくなくしていきたい。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財調の問題は、今お話がありましたが、５％の特別交付金は、区のほうで要望している、３％引き下げるという、その辺もできればありがたいなと思うし、都市計画交付金というお話がありましたけれども、品川はわりあい、議会としては申し出ていないのですが、他区の中では、やはりこのことを相当課題にしているところもあるように私も理解しております。どうぞよろしくお願いいたします。お考えをお聞きします。","respondent":"榎本福祉部長","answer":"それから２点目の、医療と介護の連携の部分ですけれども、今、直接的に進んでいるのは、認知症ケアパスの作成という中で、多職種連携のもと、医療職と福祉職の検討会議を置いて進めているところです。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。認知症サポーターの養成。この点は、これからもまたどんどん増やしていただいて、協力者を増やしていただきたい。次に総合事業についてお聞きいたします。品川区は他の自治体に先駆けて、総合事業を昨年の４月から実施いたしました。通所型サービスＢを進めていくために、新しく開設する大崎・平塚橋の高齢者多世代交流施設の事業を結びつけていくことはできないのでしょうか。","respondent":"榎本福祉部長","answer":"特にその中で、今回の介護保険法の改正の課題とされている、総合事業の中の、住民主体による支援サービスというものですけれども、今現在まだ検討中ですけれども、今、委員の提案にあったように、大崎・平塚橋のゆうゆうプラザの場所を使って。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"モデルということで始めていっていただいて、住民主体による介護。（仮称）ふれあいステーションができるだけ早期に区内全域で設置できることが必要だと思いますが、お考えをお聞きいたします。そのために、地域全体が担い手となることが求められていると思います。町会・自治会、民生委員、民間事業者による見守りなど、総力を挙げた取組みが必要だと思いますが、いかがでしょうか。","respondent":"榎本福祉部長","answer":"地域の見守りですけれども、（仮称）ふれあいステーションの展開を進めているところです。今現在４カ所で、平成２８年度、さらに４カ所ということで、開設をしていく予定です。","id":"exchange-006","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"効果的な地域の支え合いの仕組みづくり、ぜひよろしくお願いしたいと思います。次に、ＪＲ広町社宅跡地を含め、大井町近隣の状況につきまして等の質問と提言をさせていただきたいと思います。今年の夏ごろから解体に着手するとの説明がされましたが、解体完了の時期、その後の見通し、また現在における区とＪＲ東日本の話し合いの状況についてお尋ねいたします。","respondent":"藤田都市環境部長","answer":"ＪＲとの話し合いの状況ですが、ＪＲとは、平成２４年１１月から開発構想に向けた検討会を設置し、開発の方針や道路ネットワークや、あるいは歩行者デッキなどの基盤整備など、にぎわいのあるまちづくりの検討を協働で進めてきたところです。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"安全な解体をやっていただきたい。そして、２年後の解体完了の時期から考えますと、東京オリンピック・パラリンピックに向けて、暫定的に集客施設の設置もＪＲに呼びかけていくことはできないでしょうか。例えば大規模なサーカスや移動遊園地などのアトラクションにより、東京に訪れた人々に品川に来てもらう企画を検討してみてもらいたいと思いますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"今後の事業スケジュールの中で、暫定的な利用となる期間が生まれるような場合につきましては、提案の趣旨も含めまして、大井町周辺のにぎわいにつながるような活用について、ＪＲとしっかりお話し合いをしていきたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これはＪＲの話ですから、区としてどこまでできるかというのはまた別になりますが、その辺を含めてよろしくお願いします。品川区として、都市計画の手法を用いた土地利用計画などは持っているのでしょうか。用途地域の見直し、一団地の認定を外すなど、容積率を最大に活かすなどの話し合いをＪＲ東日本とされているのでしょうか。ＪＲに対する交渉の大きな材料になると思いますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"その核にふさわしい、そして拠点性、そしてにぎわいのあるまちづくりが、この地域には必要だと考えています。当地区だけでなく、大井町は広がりを持って整備を進めていく必要がありますので、隣接する地区を含めて計画的なまちづくりを進めていくことが重要であると考えています。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ぜひ、にぎわいのまちづくりに向けて、東京都との調整もしていただきたいと思います。品川区として、区有施設の整備に向け、この土地を取得するお考えはお持ちでしょうか。建築費の捻出は、例えば高層住宅を複合化し、定期借地権の売却などにより建設費を捻出した、渋谷区・豊島区などの事例も検討できるのではないでしょうか。お考えをお聞きいたします。","respondent":"藤田都市環境部長","answer":"将来的には本庁舎の建替えについても行わなければならない時期が来る。こうしたこともあります。現段階ではさまざまな可能性について検討している段階です。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"劇団四季側の土地、国鉄清算事業団から取得した土地も含めてというお話があったのですが、例えばあそこの土地に対して、区庁舎を建てて活用する、そこを高層化するということは考えられないのでしょうか。ただ、当然、人の流れの中で、商店街との連携という問題も出てきますので、その辺は十分検討が必要だと思うのですが、お考えとしていかがでしょうか。","respondent":"藤田都市環境部長","answer":"そうした中で、トータル的なまちづくりとしての、ペデストリアンデッキの検討といったことも含めて、まちづくりの検討を進めているところです。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。トータル的な検討ということで理解はしました。ただ、もう一つ、この点に関して、東急との調整。その点についても教えてください。この辺につきましても、大井町のにぎわいに向けて区としてどう考えていくのか、お聞きしたいと思います。大井町の東口側、Ｂ地区、Ｃ地区の検討につきましても、今後どのように考えていくのか、その点もお願いいたします。","respondent":"藤田都市環境部長","answer":"発生する交通量を整理するためには、１６線側との接続についても検討していく必要があると考えています。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に、教育に関して質問いたします。平成１８年の日野学園以来、６校の施設一体型小中一貫校に取り組んできました。２月の初めに、小学校ＰＴＡ会長の方、十数名と、品川区議会自民党・子ども未来の議員でお話を伺う場を設定し、公明党の議員の方にもご参加いただきました。教育委員会としての説明はされたのでしょうか。新入学児童の保護者に対して、学校選択のための情報提供は十分であったのでしょうか。","respondent":"本城教育次長","answer":"ただ、今回の新たな制度の節目ですので、今後もさらに丁寧な対応に努めていきたいと考えているところです。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"スタートする義務教育学校がうまく進めていくためにも、保護者に対するご理解、うまくこれからも続けていっていただきたいと思いますので、よろしくお願いします。今までの小中一貫教育と何か変わったところを強調しているのでしょうか。この資料をもとに款別審査の際にも質問があったと思いますが、この資料は保護者の方を対象にして作成されたのでしょうか。","respondent":"本城教育次長","answer":"今までの小中一貫教育の成果を含めて、品川区の一貫教育の成果ということでご説明するもので、一貫校のみの、取り出して強調した成果という、ＰＲをする趣旨ではございません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"このキックオフが、ちょっと保護者向けに、また何か変わったのかなというふうに見えるところがあったもので、その点もお聞きさせていただきました。まだ保護者の方から、どうしても、義務教育学校と分離型の学校にカリキュラムの違いが出てくるのではないか。義務教育学校に転入する生徒に心配が起きないことを望み、ブロック連携の今後の考え方についてお伺いいたします。","respondent":"本城教育次長","answer":"今後も老朽化の状況に応じて適切に対応していきたいと考えているところですが、このような施設のハード面のこととあわせまして、例えばタブレット端末の導入等々、教育事業の展開の面でも支援を行っていき。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"単独校の支援ということでは、ハードだけではなくて内容面での充実をぜひお願いしたいと思います。義務教育学校の成果を、ぜひ分離型の学校に活かしていっていただきたいということもお願いいたします。地域で育てる９年間の義務教育を目標にした品川コミュニティ・スクールがスタートして、実績も上がっているという状況だと思います。","respondent":"中島教育長","answer":"ＰＴＡとの役割分担、ＰＴＡとのかかわりですけれども、この学校支援地域本部は、従来のＰＴＡ活動にはなかった、例えば授業の支援ですとか、それから補修学習の実施といったような活動にも取り組むことができます。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ＰＴＡの方にもその辺が十分理解できるように、新しく進めていっていただきたいと思います。品川らしい、地域とともにある学校の創生、品川教育ルネサンスのためには、地域やＰＴＡ、また教育委員会、学校を応援することは皆必要になってくると思いますので、ぜひよろしくお願いしたいと思います。改めて品川区行政として、地域連携についてのお考えをお聞きしたいと思います。","respondent":"濱野区長","answer":"学校へのかかわり方の沿革というのもあって、コミュニティ・スクールというものが、制度設計は十分に考えてスタートするわけでありますけれども、やはり地域特性といったものも十分に考えていかなければいけないものだということで。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すみません。最後、ちょっと質問の仕方が悪かったのですが、教育のみならず各部門での、区行政と町会関係の地元地域の協力ということでお聞きしたつもりなのですが、今、教育の部門でも十分わかりましたので、これからもぜひ推進をよろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"本多委員","kind":"質問","question":"質問の１点目は、環境対策について伺います。「言葉ではなく行動で示してください」と、約７分間、環境について述べました。温暖化による都市の水没、集中豪雨、洪水、異常気象。１自治体としても、私たち自身の行動を心がけるべきです。未来館では、どう行動すればいいのかを大きく取り上げていたり、環境保全に主体的に取り組む人材を育成する方針がありますが、この点についても考え方をお聞かせください。","respondent":"藤田都市環境部長","answer":"個別具体的な施策につきましては、低炭素や水と緑など、区が積極的に取り組む、またそれぞれの主体として取り組みやすいものをご紹介したり、あるいは助成事業として支援したり、今後も引き続き、こちらについては展開していきたいと考えています。","id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"人材を増やしていくということで、さらに推進していただきたいと思います。この視察で、コンクリートの、夏場６８度まで熱が上がるけれども、屋上緑化では３４度まで下がるという、これはもうどこも、全国的にももうこういったことは基本になっておりますけれども、改めて、あえてやはりそういうことをぜひ推進していただければと考えています。","respondent":"藤田都市環境部長","answer":"品川区の中では、自然、それから文化遺産の観点といたしましては、関連部署とまた連携しながら取り組んでまいりたいと考えています。","id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"これはなかなか難しいとは思うのですけれども、夏場を中心によく考えて、その辺の取組みというのは今後どういうふうになるのでしょうか。教えてください。","respondent":"藤田都市環境部長","answer":"屋外機からのＣＯ２等の排出量が多いということは、やはりエアコンの利用が多くなっているということで、こうしたことを少しでも控える取組みが必要であると考えています。","id":"exchange-021"},{"speaker":"本多委員","kind":"意見","question":"鈴木真澄委員が款別審査で取り上げました、ＪＲ品川車両基地跡地開発のクライメット・ポジティブ開発プログラム、低炭素都市の実現に向けたモデルとなる開発事業を認証する制度の、温室効果ガスの排出がゼロ以下を目指す都市開発の具体的手法や、このような着眼点をどのように考えていくのかお知らせください。","respondent":"藤田都市環境部長","answer":"電力を買ったりガスを買ったりというような中では、なかなか難しいと考えています。そうした中で、地域の中にある資源、未利用のエネルギーを活用することにつなげることで、ゼロ以下を目指すです。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"環境の中の住環境という視点からお聞きしますけれども、今、そういう技術も日進月歩で、いろんな手法がどんどん新しくなっていきますけれども、住環境でこれまでの風対策、風被害とか、そういう、いろいろ課題があったのですけれども、そういった従来からある課題とか、そういった視点とかは何か新しい手法などがあるのかないのか、その辺を教えていただきたいのと、あわせまして。","respondent":"藤田都市環境部長","answer":"平成２８年度から、環境計画などの３つの環境にかかわる計画見直しをしたいということで、予算のご審議をいただいているところですけれども、こうした計画の策定の中で、区役所というよりも、区民と事業者と区の連携の形、品川区としてシンボルになれるよう。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"区役所を中心に品川区でチョウチョウの生息ができるように、特にミドリシジミなどが羽ばたくような品川区になっていただきたいと要望して、次の質問に移ります。質問の２点目は、思いやりのある区の施策について伺います。「わ！私は、「わ！乗り越えるという、そういった一つ一つについて、お答えできる範囲で結構ですので、その思いや施策に反映できないものでしょうか。その点についてお知らせください。","respondent":"榎本福祉部長","answer":"困ったときは助けてと言えるような形で、支え合いのまちづくりをみんなで進めていく運動という形で進めているところです。そういった意味で、やはり思いやりを持った形でのいろんな対応というものを進めていきたいと考えています。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問・要望","question":"思いやりということで投げかけさせていただきました。お答えできる範囲で、本当にありがとうございました。１つ、あまり使っていただきたくないなという言葉を今述べます。その課題に対して、例えば１人で御飯を食べてはいけない。１人で食べるよりは大勢で食べるほうがいい。ですから、できればこの言葉を使わないで進めていっていただきたいなと思います。その点について、いかがお考えでしょうか。","respondent":"榎本福祉部長","answer":"ただ、ここの部分につきましては、やはり世界と比較してどうなっているかというところもありまして、実態としては親の貧困ということでどういうふうに対策を打っていくのかということですけれども、やはり経済的な面、それからあとは。","id":"exchange-025"},{"speaker":"本多委員","kind":"意見","question":"教育費の款別審査で、学校給食の食材の放射能測定を平成２３年度より５カ年実施されてきて、平成２８年度も行うとのことですが、これまで福島産品など風評被害も起きていましたが、実は現在では日本一チェックされている食材が、日本一安全な食材という分析と、学校給食に限らず、品川区政を進めていく上で、福島産品を中心とする食材の活用について、それと、５年が経ちましたけれども、復興という思いから。","respondent":"榎本福祉部長、本城教育次長","answer":"今後も区として安全な食材としての活用に努めていきたいと考えています。学校給食につきましても、現在、いずれの地域のものでも安心なものとして提供しています。このような取組みを通じて今後とも対応していきたいと考えているところです。","id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"わかりづらくてすみません。そういう思いから質問させていただきました。その展開です。ただし、消費者、区民、都民も、選べることが必要かと思うんです。すみません。質問がちょっと増えていってしまったかもしれませんが、その辺の思いやりです。復興という、掲げたものと、実際それが行動にできるかという、その辺についてお聞かせいただければと思います。","respondent":"榎本福祉部長","answer":"やはり復興支援ということで、東北の物産を取り入れながらお祭りに参加している方についても、そういう形での、ＰＲをして応援していこうという形での事業を継続して行ってまいりたいと思います。","id":"exchange-027"},{"speaker":"本多委員","kind":"質問","question":"できる範囲でよろしくお願いいたします。次の質問に移ります。予算委員会３日目、総務費の成人式の受け付け対応に関して、あくつ委員の発言を聞いて、思いが伝わってきました。品川区は、障害を理由とする差別の解消の推進に関する法律の施行に関して、全職員を対象に研修など行っていくようですが、その執行・取組み計画ですとか、その狙いや決意についてお伺いいたします。","respondent":"田村総務部長、安藤文化スポーツ振興部長","answer":"それぞれ職場単位で職場研修というのをやっていますので、それも支援していこうと考えています。新規採用職員なども８０人程度を予定していますので、ユニバーサルマナー研修というのも新たに実施していこう。今後もこの日本ブラインドサッカーについては、ブラインドサッカー協会と連携いたしまして、より皆さんに周知していきまして、２０２０年の東京で開催される、品川区で開催されるブラインドサッカーの応援スタンドを。","id":"exchange-028"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問に移ります。思いやり、おもてなしの観点からお聞きします。地域振興基金、指定寄附、ふるさと納税への理解を広げ、実績向上および流出抑制に向けた施策を講じていただきたいのですが、その点と、ふるさと納税への特典として、品川区内のホテル、旅館の宿泊券を活用できないものでしょうか。あわせてお聞かせください。","respondent":"田村総務部長","answer":"確かに、返礼品として、宿泊していただければ、品川区の魅力を体験してもらえる、あるいは地域自体が活性化するというような効果も見込めると考えております。一方で、２０２０年のオリンピック・パラリンピックが４年後に控えている。","id":"exchange-029"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ前向きにお願いいたしたいと思います。質問を次にいきます。質問の３点目は、公園等の活用について伺います。品川区内における品川区立の公園・児童遊園、全てを対象に、あまり使われていない状況ですとか、それぞれの課題などについてお聞かせいただきたいと思います。","respondent":"松代防災まちづくり部長","answer":"区としましては、経年によりまして、施設の老朽度をはじめ、見通しの問題やバリアフリーへの対応など、各公園の実情に応じた改善等を図っており、おおむね２０年から３０年を経過した公園を中心に改修工事を実施しております。","id":"exchange-030"},{"speaker":"本多委員","kind":"意見","question":"今度、メリット的に、主要公園でのＷｉ－Ｆｉ等を活用したりする計画がありますけれども、公園のメリットを伸ばす点について、また、主要公園のＷｉ－Ｆｉにしても、今までの使い方からいろいろと取組みがレベルアップされてきていると思うのですが、その辺の目的、今までの公園の目的と、目的外使用といいますか、その辺の展開の可能性について、その辺についてお知らせいただければと思います。","respondent":"松代防災まちづくり部長","answer":"今後も防災面だけではなくて、観光面、また様々な需要を捉えながら、オリンピック・パラリンピック等の開催も念頭に置いて、公園の活用について検討してまいりたいと考えておるところです。","id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"公園がさらに有効活用されることを願います。次の質問にいきます。しながわ区民公園内の保育園設置計画、平成３０年度より開設ということで、今後の都市公園の保育園整備計画を、具体化に向けた公園改修および保育園設置計画について、この西大井としながわ区民公園の計画はプレス発表等で理解しておりますので、その後の設置計画の検討状況ですとか今後の展開等、現況でお答えできる範囲でお願いいたします。","respondent":"松代防災まちづくり部長","answer":"今後の計画等につきましては、今申し上げましたように、今後、公園を整備・改修等をすること。あわせて、先ほど言いました要件等を十分に緩和しながら、どういった形で展開できるのか、十分に検討して進めていきたいと考えているところです。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問・要望","question":"新しい動きが何かありましたらお知らせいただければと思います。公園の活用とさらなる待機児童解消に向けて努めていただきたいと思います。最後に１つ質問します。テロ対策について伺います。国は平成２８年度の予算のポイントとして、事前防災・減災対策の充実や老朽化対策など、国土強靭化を推進。お願いします。","respondent":"曽田危機管理担当部長","answer":"区としては、これらの措置を的確に実施できるよう、私、危機管理担当部長のもと、危機管理室を中心に、関係機関との連携体制の整備や、組織としての全庁的な対処能力の向上に努めているところであります。","id":"exchange-033"},{"speaker":"本多委員","kind":"質問","question":"何かもう少しはっきりした答弁がいただけないのかなと思いましたけれど、もう一度だけ聞いていいですか。","respondent":"曽田危機管理担当部長","answer":"したがいまして、危機管理室が指令的な役割となり、それを担うということが、現状の体制でいいのかと考えておりますが、委員のご指摘もありますので、引き続き、より望ましい体制については、今後検討していきたいと考えているところであります。","id":"exchange-034"},{"speaker":"つる副委員長","kind":"意見","question":"区議会公明党を代表して、こんの委員とともに総括質疑を行います。未曾有の大地震と巨大津波、原子力事故災害をもたらした東日本大震災から５年を迎えました。そこで改めて、これまでの５年間で取り組んでこられた被災地支援や区内の防災力強化の取組みなどをお知らせいただくとともに、これからの取組みとして品川区の課題を明示いただき、その対策にどのように取り組んでいかれるのかお知らせください。","respondent":"曽田災害対策担当部長","answer":"平成２６年度からは重点課題としてこれらを充実・強化するとともに、新たに帰宅困難者対策、水防対策などを進めてまいりました。これらの取組みにより、防災意識の向上、初期消火、緊急医療、避難所、津波避難の体制や関係機関との連携体制が強化されたものと認識しております。","id":"exchange-035"},{"speaker":"つる副委員長","kind":"確認","question":"新年度からの、次の５年間の「復興・創生期間」において、私も「心の復興」、「人間の復興」のために働いてまいります。次に、非核平和都市品川宣言事業に関連してお尋ねいたします。そこで、非核平和都市品川宣言は、品川区における「平和の準備」の根本だと捉えていますが、改めて宣言文の確認と宣言制定の経緯をお知らせください。","respondent":"田村総務部長","answer":"非核平和都市品川宣言についてお答えいたします。宣言の制定の経緯から、私からご説明を簡単にします。今から３０年前になりますが、昭和６０年当時、やはり核戦争の脅威が増大しつつあるという３０年前ですが、３５万区民の願いである核兵器の廃絶と恒久平和を確立しようと。","id":"exchange-036"},{"speaker":"つる副委員長","kind":"確認","question":"核兵器廃絶と恒久平和確立に対する品川区の強い思いを確認できました。同宣言文を今改めて拝聴し、平和憲法である日本国憲法の憲法三原則とも響き合う内容であると思いました。そこで、これまでの取り組んできた主な事業とあわせて、平成２８年度に行う事業について、確認を含めて改めてお知らせください。現在地球上に核兵器は、どの国にどれくらいあるのかお知らせください。","respondent":"田村総務部長","answer":"平成２８年度、今年度、今の事業も継続していますが、今年度の特徴とすると、品川の平和の花壇の拡大をしたいということで、ＪＲ西大井駅前の平和の誓いの像周辺を整備したいと考えておりますし、あと中学校と義務教育学校の中にも。","id":"exchange-037"},{"speaker":"つる副委員長","kind":"提案","question":"「我々の問題は人間がつくり出したものです。直後の定例会で私も、しながわ平和の花壇を小中学校やオリンピック・パラリンピック会場近くなどへの拡大を提案していた者として、新年度から中学校義務教育学校に拡大されることは大変喜ばしく思っています。平和の誓い像や宣言の英語版のレリーフの設置についても検討してはいかがでしょうか。","respondent":"田村総務部長","answer":"お尋ねの、各競技場近くの品川の平和の花壇を拡大してはということなので、これから、今後オリンピック・パラリンピックが近づいてきますので、やはりそれにあわせて、委員もご指摘のとおり、一部無電柱化ということが考えられますので、可能でしたら。","id":"exchange-038"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先日の３月１１日、ベラルーシ共和国の一行が品川区を表敬訪問されました。そこで、例年行われている非核平和パネル展ですが、全世界の方に非核平和を訴える好機とも言える２０２０年のオリンピック・パラリンピックの開催期間に合わせて、特別展示などを実施してはいかがでしょうか。その展示を、児童、生徒、学生など青年世代の方に、語り部ボランティアとして活躍していただいてはいかがでしょうか。","respondent":"田村総務部長","answer":"ですから、その前段階として、委員よりご指摘のあった、オリンピック・パラリンピックに合わせての特別展というのは、時期だとか場所は、ちょっと今の段階では、一番効果の上がるやり方というのはここというのは、まだ申し上げられませんけれど。","id":"exchange-039"},{"speaker":"つる副委員長","kind":"質問・要望","question":"特別展の展示、積極的にご検討いただきたいと思います。そこで、品川区として、亡くなった区民の方々の追悼にあわせ、非核や平和について考える機会の一環として、最も被害の大きかった５月２４日を「品川区平和の日」として制定し、黙祷の実施などを検討してはいかがでしょうか。制定に際して、啓発パンフレットを活用して周知を図ってはいかがでしょうか。","respondent":"田村総務部長","answer":"それで、品川区の平和の日の、あるいは黙祷の実施というご提案ですが、７０年後の今なので、突然、この日を平和の日にしましたというわけにはなかなかいかないと思うので、やはり『品川区史』のＰＲだとか、あるいはホームページで。","id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問","question":"「地域包括ケアシステム」や「ネウボラネットワーク」など、福祉についてお聞きします。本定例会の一般質問でも、公明党のあくつ委員から、「全世代・全対象型地域包括支援体制」の検討の着手について、区の認識を伺いました。「今後は、高齢者をはじめ障害者や子どもたちが世代を超えてともに福祉サービスを利用する多世代交流型の共生型福祉施設の設置も望まれる」と、区の認識を伺いました。","respondent":"榎本福祉部長","answer":"ここでいろいろと、地域交流事業ですとか子育て支援事業を行いますので、その辺の推移を見て、多世代間交流について今後、何ができるかということの検討を進めていきたいと考えています。","id":"exchange-041"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ヘルパーとして、区内在住の２名の産後ドゥーラと提携される予定ですが、現場で私がお受けする期待の声の大きさから考えると、強力な体制を築くことが求められます。担い手養成が求められることから、ドゥーラを養成するドゥーラ協会とも連携し、さらに幅広いニーズに応えられるよう、多様な担い手を養成する仕組みを構築してはいかがでしょうか。","respondent":"金子子ども未来部長","answer":"このヘルパーは、育児・家事の支援だけでなく、母親の心と体についてもケアできる、そういった内容にしておりまして、現在のところ、この全てのメニューを対応するように考えておりますけれども、ニーズとしては。","id":"exchange-042"},{"speaker":"つる副委員長","kind":"質問・要望","question":"育児と介護の担当部署が縦割りのため、連携が十分ではないのが現状かと思います。そこで、政府の実態調査を機会に、必要に応じて区としても調査を行い、また横浜市が、ＮＰＯ法人が主催する「ダブルケアサポーター」の養成講座を活用して、相談や応対の改善を行っているように、品川区も職員に同様の養成講座の受講を促し、ダブルケアに的確に対応できる体制をつくってはいかがでしょうか。","respondent":"榎本福祉部長","answer":"ダブルケアに対応できる体制づくりですけれども、やはり介護、保育、子育ての部分、それぞれ専門相談的なものがかなり多くなっております。","id":"exchange-043"},{"speaker":"つる副委員長","kind":"質問","question":"今後、それぞれ積極的に検討されることを期待して、以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問・要望","question":"初めに、青少年健全育成対策についてお聞きいたします。区内１３地区における青少年健全育成は、青少年対策地区委員会の方々が中心となって活動していただいていると認識しています。昭和３１年に制度が発足されており、今年で６０年を迎えるとお聞きしています。来年度は、その６０年の長きにわたる活動の栄誉をたたえ、記念の式典が企画されるとも伺っております。","respondent":"堀越地域振興部長、金子子ども未来部長","answer":"１３地区ごとに、各地区、工夫をしながら青少年の健全育成の一環として事業を実施しています。内容ですが、各種スポーツ大会、それから親子キャンプ、親子ハイキング、子どもまつりなど、年間で約１２０の事業を実施しております。今後ともこの基本方針を指針として、各所管あるいは関係団体とともに、さまざまな取組みを進めていく考えです。","id":"exchange-045"},{"speaker":"こんの委員","kind":"質問・要望","question":"さまざまな活動のご紹介、また基本方針の方向性、ありがとうあります。改善されないまま放置されている状態は、少年非行の温床となることが懸念され、一刻も早い改善が求められます。そこで、調査後の対応として、これまでどのような対策がとられてきたのでしょうか。実効性ある改善を講じていくためには、何らかの手だてが必要と考えますが、区のお考えをお聞かせください。","respondent":"堀越地域振興部長","answer":"ただ、いずれにいたしましても、こういった調査の重要性は私ども十分認識しておりまして、継続して取り組むこと、それから店舗の意識啓発を図っていくこと、これが必要であると考えているところです。","id":"exchange-046"},{"speaker":"こんの委員","kind":"提案","question":"青少年の健全な育成には良好な社会環境が欠かせないと考えています。そこで、少年非行につながりかねない危険な環境の改善を今後も事業者に求めるとともに、品川区から具体的な働きかけとして改善を促す支援策を検討することを提案します。青少年の健全育成のため、また青少年対策地区委員会の調査の活動のご苦労が報われますよう、一日も早い健全な環境整備を要望します。品川区のご見解をお聞かせください。","respondent":"堀越地域振興部長","answer":"しかしながら、青少年健全育成については、委員よりご紹介いただいたような、様々な検討策がいろいろありますので、今後のいろいろな事業の進捗の中で、そういうことも含めて、可能性についても含めて、いろいろ調査研究をするとともに。","id":"exchange-047"},{"speaker":"こんの委員","kind":"質問・要望","question":"この改善策には、やはり地区委員の方々のご苦労もあっての独自の調査とも伺っておりますので、どうか改善されるように品川区の取組みをお願いしたいと思います。こうした現状から、各関係機関と連携した少年非行対策のさらなる強化が求められます。そこで、品川区における少年非行の現状についてはどのような状況でしょうか。","respondent":"金子子ども未来部長","answer":"青少年対策地区委員会や青少年委員の地域での取組み、学校やＰＴＡでの取組み、また居場所づくりや相談の場として児童センターやすまいるスクール、非行の原因の一つである虐待の防止対応を対応する子供家庭支援センター。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問","question":"こうした対応には児童相談所との連携・協力が不可欠と考えます。先ほども鈴木真澄委員より質問がありましたけれども、そうした中で、国では今後、児童相談所を東京２３区に設置できるようにする法改正を進めるとしています。実際、少年非行対策には、児童相談所をかなめとする各関係機関との連携が重要ですが、品川区の果たすべき役割分担と、連携を図る上での課題についてもお聞かせください。","respondent":"金子子ども未来部長","answer":"品川区の役割分担の連携を図る上での課題ですけれども、虐待のところでもいつもご説明しているとおりなのですが、二元体制によりまして、それぞれの機関の温度差や、あるいはきめ細やかな対応に困難さがあるということが課題と捉えているところです。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"少年非行の背景の児童虐待、そうしたことが、児童相談所による予防対策と、そのように理解します。少年非行問題への迅速な対応を図るため、移管されるまでの間は、今後とも、児童相談所や警察など各関係機関と連携し、総力を挙げて青少年の健全育成に取り組んでいただきたいと思いますが、重ねて要望いたします。品川区のご見解をお願いいたします。","respondent":"金子子ども未来部長","answer":"こういった非行防止あるいは虐待対応など、青少年の健全育成につきましては、今後とも区としましては、各所管がそれぞれ連携し、また外の関係機関とも緊密に連携した上で、積極的にさまざまな事業で取り組んでいきたいと考えています。","id":"exchange-050"},{"speaker":"こんの委員","kind":"提案","question":"次の質問にまいります。次は、食品ロス削減についてお聞きいたします。先日、款別審査で我が会派の新妻委員より、ＳＨＩＮＡＧＡＷＡ“もったいない”プロジェクト事業における食品ロス削減について質問し、庁舎内の食堂への認証ステッカーの掲示等提案に対し、担当課長から、取り組むとのご答弁をいただきました。今なぜ食品ロス削減なのか、品川区のご認識をお聞かせください。","respondent":"藤田都市環境部長","answer":"今回のプロジェクトでは、この中で区内の商店街としての小売業者や飲食店に着目いたしまして、食品ロスの削減、まさしく、もったいないの精神から、食べ残さないよう、ハーフサイズや小盛りメニューの導入、食品販売においては。","id":"exchange-051"},{"speaker":"こんの委員","kind":"確認","question":"品川区の取組みのご認識を確認させていただきました。さて、世界では９人に１人が栄養不足という現状で、その多くは女性と子どもです。そこで、品川区における食品廃棄物や食品ロスの発生量、また推計状況はどのような現状でしょうか。例えば、可燃ごみに占める、家庭や企業から廃棄される食品ロスの調査などを実施し、現状の食品ロスの見える化を図ってはいかがでしょうか。お願いします。","respondent":"藤田都市環境部長","answer":"このため、分析調査を実施している自治体もまだ少数にとどまっているところでございまして、当面の間は、国の調査数値などをもとに、区の食品ロスについて推計していくのがいいかなと考えています。","id":"exchange-052"},{"speaker":"こんの委員","kind":"質問・要望","question":"なかなか見える化が難しい、自治体はやっているところが少ないということですが、できている自治体もありますので、何とかご検討いただきたいと思います。現在、食品ロスの問題は国連でも取り上げられ、２０３０年までに世界全体の１人当たりの食品ロスを半減させる目標が採択されております。そこで、今後の事業展開はどのようにお考えでしょうか。","respondent":"藤田都市環境部長","answer":"環境、清掃、それからリサイクルの観点から、引き続き取り組んでいく必要があると考えています。","id":"exchange-053"},{"speaker":"こんの委員","kind":"提案","question":"消費者庁による食品ロス削減の普及啓発方針には、消費者の日常生活や家計に結びついたわかりやすい問題提起と、楽しく実践できる方策の提案を通じて、食品ロスの認知度向上と、削減に向けた協力を促すとあります。幼いころからの教育が大事です。保育園、幼稚園、小中学校など、年代に合わせた“もったいない”教育などの実施も要望いたします。品川区のご見解をお聞かせください。","respondent":"藤田都市環境部長","answer":"もったいないの観点・考え方は、食品ロスだけでなく様々な分野でも活用していかなければならないと考えています。平成２８年度より検討を進める品川環境計画などの３つの計画の中でも取り上げて検討を進めたいと考えています。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"この食品ロスの削減運動は、私たち日本人が、一人一人が意識を持ってしていくことによって、先ほどもご紹介いたしました、世界各国の子どもの命を救う。ロスに削減をするように頑張っていきたいと思いますが、区民の皆さんにも品川区からぜひ発信していただき、この食品ロス削減運動を全区展開していただきますよう要望いたします。以上で私の質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"日本共産党品川区議団を代表して総括質問をいたします。前半は私が、後半は安藤委員が行います。よろしくお願いします。市街地上空の低空飛行は中止せよと国に求めよ。この質問です。こんな計画は絶対に認められません。私は反対の立場から質問します。なぜ、当時は品川区上空を飛行してはいけないと主張したのか、改めて伺います。","respondent":"藤田都市環境部長","answer":"昭和４０年代ですけれども、当時の旧Ｃ滑走路の離着陸は、モノレールの線路よりも海側を通るようにというような形で、国と品川区の間に約束を交わされていたというようなことが確認されてあります。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"まとめて質問するのを忘れていまして、すみませんでした。一問一答にならないように頑張ります。これが飛行ルートです。なぜ今、先ほどは騒音被害があるということで配慮されてきたというふうなお話でしたけれども、今回もますます騒音被害というのは、やはり同じように残ると思います。なぜ当時と同じように、品川区上空を飛行してはいけないと言わないのか。それについて伺います。","respondent":"藤田都市環境部長","answer":"しかしながら、過去の地域との約束の基本的な考え方は踏まえながら、さらなる検討を進めたいというような形の話をされてあります。一方、これまで、品川区だけでなく各地域からの意見も合わせますと、２４０件余りの意見が国のほうに提出されております。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"墜落の危険、そして落下物の危険。したがって、やはり当時よりももっと内陸部に入るこの飛行計画はやめるべきだと、品川区上空は飛行しないでほしいということを言うべきだと思っているのですけれども、改めてこの点について伺いたいと思います。もう一つが、４０年当時のようにということで言わないでほしいということを思っています。こういうことを言うべきです。この点について再びお願いします。","respondent":"藤田都市環境部長","answer":"大気汚染であるとか資産価値の低下も、先ほど申した２４０ほどの意見の中に、様々な形で国に対して意見が出ておりますので、こうしたことに対して国としてしっかりと回答していくような形に、まずはするべきだと考えています。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、品川区の区長が反対すれば、この計画は中止になるのではないでしょうか。今の計画はさらにひどい内容ですから、国に対して、品川区上空を飛行するなと強く求めるべきだと私は思います。このことを改めて要望して、この羽田の質問は終わります。次に、高すぎる国保料、引き下げを求めての質問です。これが国保の実態です。改めて確認しますけれども、所得に占める保険料は重いと認めますか。","respondent":"矢野健康推進部長","answer":"委員ご指摘のように、急速な高齢化の進展や非正規労働者や低所得者が多いこと、他の制度と比べて被保険者の年齢構成も高く、医療費の水準が高いといった構造的な問題を抱えており、所得に占める保険料負担の割合も高くなっている状況であることは。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれ財政的支援をしているからというお話ですけれども、高いのかどうかを認めるかというこの質問に答えていません。答弁してください。私はやはり、そこのところが基本だと思うんです。したがって、その点についてはきちんと答弁を求めたいと思います。それから、区の資料の国民健康保険制度の現状問題点。重いと認めなければ、この資料とも反するものだと私は思いますので、この点についても伺います。","respondent":"矢野健康推進部長","answer":"先ほどお答えしましたように、所得に占める保険料の負担割合は高くなっている、イコール重くなっているということは、国も課題としていることですし、区としても認識しています。","id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"重い。こういうふうに認識しているということで確認していいですね。それによって、１人当たり保険料引き下げ可能額は４,０００円となっています。この点について答弁を求めたいと思います。そして、保険料についての重い負担、こういうものが区として認識があるということでありますので、私はやはりきちんとした負担軽減、そういう対策をとるべきだと考えていますけれども、その点についても伺います。","respondent":"矢野健康推進部長","answer":"特別区においては統一保険料方式というものを用いておりますので、委員のようなご意見もあろうかとは思いますが、現在の時点では、保険料引き下げにこのようなものを利用する考えというのはないという状況にあります。","id":"exchange-061"},{"speaker":"南委員","kind":"質問","question":"高いという認識がありながら、また全国の知事会でも高く限界だと指摘して公費が投入された、それをなぜ保険料引き下げに使わなかったのか。品川区がなぜこのお金を使って引き下げに努力しようとしなかったのか。そこについて改めて伺いたいと思います。そういう状況なのに、なぜ引き下げをしなかったのか、引き下げが可能だと言いながらしなかった理由と、公費を投入しないでいったその理由、２つを伺います。","respondent":"矢野健康推進部長","answer":"区といたしましては、既に４６億円の繰入金を入れているということで、また特別区全体といたしましても、統一保険料率というものを採用しておりますので、その中で、特別区全体の中で財政基盤を整備するというところにこれは使われるということになったです。","id":"exchange-062"},{"speaker":"南委員","kind":"質問・要望","question":"その点についてどういうふうに理解をしているのかということで、なぜ使わなかったのかということを私は繰り返し言っていますので、その点についてしっかりと答弁していただきたいと思います。それと、２３区全体の合意があれば、保険料引き下げはできる。したがって、２３区、引き下げ可能だというところでの検討はしなかったのかどうか、その点についても伺います。","respondent":"矢野健康推進部長","answer":"この交付金が来る時点が、申請が１０月以降でございましたし、保険料の率を検討するのは７月ぐらいから始まっていたということで、これを繰り入れることは困難だったと思いますし、あと特別区全体の財政状況を見ると、そのような意見が出てこなかったです。","id":"exchange-063","title":"町会・自治会支援"},{"speaker":"南委員","kind":"提案","question":"２倍、１.７倍、こういう状況です。区長会でぜひ引き下げに使おうという提案をしていただいて検討し、実施に移せるよう努力していただきたいと思います。こういう状況でいいのでしょうか。改めて、３億６,０００万円は保険料引き下げに使うよう強く求めたいと思います。こういうやり方、区のやり方なのでしょうか。質問したいと思います。そして、これは法律に反していると思わないのでしょうか。伺います。","respondent":"矢野健康推進部長","answer":"差し押さえは最終手段であり、同じような所得の方でもきちんと納めていただいている一方で、何年にもわたって納めていただけなく相談もできない状況の方もいらっしゃいますので、このような対応をとらせていただいております。","id":"exchange-064"},{"speaker":"南委員","kind":"質問","question":"法律にのっとってとおっしゃるけれども、こういう差し押さえは徴収法に反しているではないですか。そこを聞いているのです。答弁してください。生活を窮迫させるおそれのあるときは処分を停止する。この国の原則に、品川区のやっていることは反していると考えないでしょうか。伺います。このやり方は私はやめるべきだと思っていますが、いかがでしょうか。この立場に立つべきだけれども、どうでしょうか。","respondent":"矢野健康推進部長","answer":"そのような前提のもとで、原則としては差し押さえをしていますところですが、私どもでも厚生労働省の通達などもきちんと対応しておりまして、困っている方には適切な対応をしようということで努めているところです。","id":"exchange-065"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところは、金額そのものも明確に法に反しているではないですか。その点について、幾ら後で相談する、ゆったり相談を聞くといっても、それでは全然、実情に合わないではないですか。強く求めておきたいと思います。それで、なぜ区はこんな厳しい取り立てをするのでしょうか。そういう中で、平成２５年度と平成２６年度の差し押さえ件数は何件でしょうか。そして平成２６年度の交付金は幾らか伺います。","respondent":"矢野健康推進部長","answer":"平成２５年度の差し押さえ件数は３５１件、平成２６年度は７２０件です。都の報奨金に関しましては、まだ交付決定がしていないので見込み金額ですが、３,０００万円です。","id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"国保料そのものがますます高くなって払えない。国からの公費が来たのに引き下げに使わない。加えて、払えなくなった人には違法な差し押さえをする。命を守るはずの国民皆保険制度が、命を奪うものに今はなっています。国の悪政から暮らしや命を守るという、地方自治体本来の姿勢に立ち返ることを強く求めて私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からはまず、今年４月、保育園に入れず行き場のない子どもを一人も出さない対策を求め、質問します。品川でも、今年４月の保育園入園の１次・２次募集の結果が出ました。待機児の実態について伺います。そのうち入園が内定した人数と、その内訳、年齢別内訳も伺います。２次を終え、不承諾通知を発送した数と、その年齢別内訳を伺います。そのうち、０から２歳児枠は何人だったのか伺います。","respondent":"金子子ども未来部長","answer":"平成２８年４月の保育園の入園申し込みについてのお尋ねにお答えします。保育園の入園申し込み、現時点での状況ですが、１次・２次の合計の申請数が３,４８３人です。そのうち内定した方が２,２８１人です。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"ある認証では、１次発表後、１５０人の応募がありました。何で、働いて税金も払っているのに保育園に入れないのですか。伺います。区は何人と予測しているのでしょうか。昨年の予算総括でも、こうした方はどうすればいいのですかと伺ったところ、区は、様々な認可外保育施設の活用などもお願いしなければならない。相談すれば区はどこかに入れてくれるのでしょうか。以上、３点について伺いたいと思います。","respondent":"金子子ども未来部長","answer":"これは単に数というわけではなくて、私どもも重く受けとめているところでありますが、今年は、待機児童対策、３００人保育園をはじめ例年にない数字で保育の入園枠を確保した結果、この２５０人については、今のところの見込みですけれども、減少すると考えております。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"どこにも行けない方が必ず出る。どちらを選べというのでしょうか。どうしたらよいのでしょうか。伺います。その上、利用料は平均で１０万円とはるかに高いのです。伺います。区は、認可にも地域型にも子どもが入れなかった親、認証にも入れなかった親は、こうした無認可の施設に預けるか、それとも仕事を辞めるか、どちらかを選べと言っていることに等しいのではないでしょうか。これも伺います。","respondent":"金子子ども未来部長","answer":"窓口にお越しになったお客様に対しては丁寧な対応をするというような基本的な考え方で対応しております。今後とも待機児童対策については積極的に対応するとともに、お客様に対しては丁寧に対応していきたいと考えています。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"こうした方々にどちらかを選べと迫っていることだと私は伺いました。この苦しみがわかるのでしょうか。しかし、こうした事態になっていることに反省があるのかどうか伺います。区は、昨年秋の時点で、去年を超える申し込みがあることを予測しながら、４月の対策に必要な追加策をとらなかったことが原因ではないでしょうか。なぜ今年４月、待機児ゼロに向けて必要な追加対策をとらなかったのか伺います。","respondent":"金子子ども未来部長","answer":"しかしながら、現実にはご指摘のとおり待機児童は出るというふうな状況に今ありますけれども、今後とも引き続き積極的な努力をしていきたいと考えております。","id":"exchange-071"},{"speaker":"安藤委員","kind":"提案","question":"款別審査では、区は基金、ため込み金を、当初予算の７１４億円から８４５億円に１３０億円も増やしたことが明らかになりました。保育園１園当たりの建設費は２億５,０００万円、１年の運営経費は２億円です。待機児ゼロへ、共産党提案の認可保育園２０園増設は、合わせても９０億円でできます。以下の抜本対策と緊急対策の追加実施を提案します。以上、４点を求めますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"しかしながら、私どもとしましては、それらを乗り越えて、例えば公園の活用であるとか、あるいは国有地をはじめとした公有地の活用、あらゆる手段を駆使しながら待機児童対策に取り組むというふうな姿勢を堅持しつつやってまいりましたけれども。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"区の姿勢の転換を強く求めて次の質問に移ります。次は、保育士の低賃金を招き、保育士不足や保育園不足をつくる区立保育園の民営化の中止を求め、質問します。区は、区立認可園を当面５園程度、やがて相当数は残すが売却も含め民営化する方針を発表しました。民営化の目的は運営費の削減とのことですが、１園民営化すると幾ら削減できるのか、また最終的な削減目標は幾らなのか伺います。","respondent":"金子子ども未来部長","answer":"こういう意味で、歳入については全体の経費の４分の１強の違いがある。これほど大きなものであるということを、私どもとしましては、今後、民営化を実施しながら、様々な問題点、課題についても検証しつつ進めていこうと考えているところです。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"今、保育園が増えない原因の一つとして、先ほど部長も言いました保育士不足が挙げられておりますが、この保育士不足の原因は何でしょうか。何よりも保育士の低賃金が原因です。保育士の平均年収は３２３万円で、全産業平均年収に比べ、１６６万円も低い。伺います。区立を民間に置きかえることは、この保育士の低賃金を一層加速させることになり、保育園不足も加速させることになりますが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"加えまして、家賃補助についても充実してきておりますし、私どももこれについては取り組み、また上乗せをしているところでありますので、少なくとも平成２７年度以降については、一概に民立・民営の人件費が低いとは言えないだろうと考えております。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"区立を民間に置きかえることは低賃金を加速させることにならないかということを伺いましたが、答えはありません。さらに、全国的にもこの１０年間で、公立の認可保育園は１万２,３５８人から９,９７１人に減少。伺います。伺います。保育園不足と人材不足を同時に解決するためには、これ以上、区立保育園を減らす民営化は中止し、区立保育園の増設こそ必要ですが、いかがでしょうか。","respondent":"金子子ども未来部長","answer":"それで、今後も品川区の待機児童対策につきましては、保育園の開設については民立・民営を基本として、状況に応じて例外的に区立・民営とすることもありますけれども、様々な手法を駆使して、また認可保育園、小規模保育事業、認証保育所等。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"そんな中で、みずから保育園不足を深刻化させる民営化は中止するよう重ねて強く求め、次の質問に移ります。こうした認識、自覚はあるのですかと質問しましたが、区長の答弁は、激励会の開催自体がこうした事態を招来しないというものでした。区長のこの態度は、送った先が海外の戦場であろうが、そこで品川の若者、自衛隊員が、殺し、殺される事態に直面しようが知りませんということなのでしょうか。","respondent":"田村総務部長","answer":"その際にも、本会議場でも再質問されて、正確に申し上げますと、激励会自体が、言われるような事態を招来するとは考えておりませんというお答えをしているのであって、委員ご指摘の、そういう内容は一切お答えしていない。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと私は、今、違うのだとおっしゃいましたが、私が紹介した内容と、今、総務部長が紹介した内容が、違いが全くわかりません。同じだというふうにしか聞こえませんが、もう一度、その辺については違いをお伺いします。これは戦後日本の原点です。品川区はこうした事態をまた繰り返すのでしょうか。あわせて伺います。","respondent":"田村総務部長","answer":"それで、そこの中には、国際社会における国家の存立にかかわる事柄は国の専権事項とされているということで明記されておりますので、外交、防衛等についてはそれに当たるだろうということで。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"先日の款別審査でこのことを尋ねると、区は、ガイドラインの自治体の協力は、それぞれでできる協力をすると書かれていると認識しており、当然、協力するなどと答えました。驚きました。そこで質問します。当然、協力するとの区の答弁は、日本が直接攻撃を受けていない、存立危機事態のもとでも協力するということなのか伺います。私は協力は断るべきだと思いますが、いかがでしょうか。","respondent":"田村総務部長","answer":"それと、それについての反対というのですが、これ以上の中身、通知については一切来ておりませんので、そういう、あくまで想定の中での質疑で、軽々にこういう公式の場でお答えする立場にはないと考えております。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の答弁は重大だと思います。国が求めるものに当然協力する。こうした態度。戦後に確立された地方自治の態度とかけ離れています。そして、区民を危険に巻き込むのです。戦争放棄を定め、武力行使を禁じた憲法９条を踏みにじる戦争法を追認し、区民を危険にさらすことは断じて許せません。戦争法の廃止を国に求めるよう強く求め、私からの質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"木村委員","kind":"意見","question":"私は、いながわ委員とともに総括質疑をします。は教育費からですが、本区では、日本で最初の小中一貫校をスタートさせ、はや１０年になりますが、小中一貫校に移行したきっかけ、また、なぜ一貫校になったのか、お聞かせを願いたいと思います。","respondent":"本城教育次長","answer":"そこで、平成１４年に、特色ある教育を行う１つの学校としまして、小中一貫教育をより具現化します小中一貫校の設置をし、小中一貫教育の実施をしたところです。","id":"exchange-080"},{"speaker":"木村委員","kind":"質問","question":"中学校に行けば、他の小学校からたくさんの同級生が集まるわけですから、わくわくする反面、またどきどきを体感する従来の教育。そこでお聞きしますが、この１０年間やってこられて、小中一貫校ならではの問題や課題はあったでしょうか。子どもたちの心の成長を感じながら、小中一貫校にしてよかったなと思うことはあったでしょうか。どのような問題が立ち塞がると思っているのでしょうか。お聞かせください。","respondent":"本城教育次長、中島教育長","answer":"今後の、区としては、それらの３つの講師間のバランスですとか、あるいは就学人口の動向等を見て、幅広い見地から、これからの学校配置のあり方を整理する中で検討を進めていきたいと考えているものです。こういうシステムの中で、品川のコミュニティ・スクールの流れに沿いながら進めていきたいと考えているところです。","id":"exchange-081"},{"speaker":"木村委員","kind":"提案","question":"平成２８年度施政方針の中で、基本方針および施策で、２３区初となる「町会および自治会の活動活性化の推進に関する条例」の提案がございました。本区の町会・自治会の加入率は６割ぐらいとお聞きしております。他の自治体と比べて６割という数字は高いようですけれども、町会・自治会はどのように、会員募集活動や、住民が積極的に参加しようと思えるような活動を行ってきているのでしょうか。","respondent":"堀越地域振興部長","answer":"今、町会および自治会の方々の会員募集活動、それから活動についてですが、既に町会ごとに、当然のことながら加入促進活動を行っていただいてございまして、基本的にはマンション事業者への働きかけですとか、個人のお宅への訪問・説明が基本となっています。","id":"exchange-082","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"お聞きしますけれども、地域と行政とをつなぐ役目が、今お話がありました地域連絡調整員だと思いますが、調整員とは具体的にどのような役目なのかお聞かせください。住民が積極的に参加していただくためには、どのような活動とお考えでしょうか。お聞かせください。住民はどのようなことを考え、１住民として町会やご近所と接していくと予想されるでしょうか。お考えをお聞かせください。","respondent":"堀越地域振興部長","answer":"町会・自治会の主体的な取組みを支援するという意味で、加入促進に関する助成ですとか、新規の事業の応援助成ですとか、そういった取組みを考えていきたいと、今、予定しています。","id":"exchange-083","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"この条例制定を押しつけととる人もいるみたいであります。区民の参加・協力がなければ、条例制定の意味がありませんし、それを押しつけと言うのでしょうか。なぜこれが押しつけになると思うのか、行政としてのお考えをお聞かせください。このことをきっかけに、区は、地域コミュニティの核である町会・自治会の活動がさらに活発になるよう、しっかりと支援してほしいと思うのですけれども、いかがでしょうか。","respondent":"堀越地域振興部長","answer":"あわせて、さらに活発化していくような支援ですが、町会・自治会、それから区民の皆さんの主体的な活動を踏まえつつ、先ほどの地域連絡調整員、それから助成による支援のほか、マンションの管理者等の協力ですとか、実際の不動産の賃貸・売買の場合における。","id":"exchange-084","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"マイナンバーについて質問です。平成２７年１０月にマイナンバーの通知が始まり、制度の本格運用が順次開始されようとしています。そういう現場レベルで想定される問題に対して、本区の見解をお聞かせください。会社の対応に疑問等があった場合、どのようにすればよいのでしょうか。対応は考えているのでしょうか。お聞かせください。","respondent":"中山企画部長","answer":"したがいまして、区といたしましては、こういう行政分野での公平・公正な給付と負担の確保というのは、マイナンバーの目的の重要なものの一つと考えておりますので、法に従って適切に対応していただくよう、様々な面で周知を進めていきたいと考えておるところです。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問","question":"マイナンバー制度には、便乗した不正な勧誘や個人情報を引き出そうとする事案が発生しているそうですが、本区としては、現在の状況をしっかりと把握しているのでしょうか。お聞かせください。","respondent":"中山企画部長","answer":"今後とも区民の方が被害に遭うことがないように、しっかりと周知あるいは啓発等についてさらに努めていくとともに、区民の方のセキュリティ確保については全力を尽くしてまいりたいと考えております。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"ぜひ、区民の皆さんのセキュリティというものに対して、行政としてしっかりお願いしたいと思います。次に、オリンピック・パラリンピックについてお聞きします。区内では３つの競技が行われることが決定しております。お聞きしますけれども、まずは公共交通機関から会場までの間の安全確保が大事です。これらについてどのように対応していくおつもりでしょうか。３点のご回答をお願いいたします。","respondent":"安藤文化スポーツ振興部長","answer":"そんな中で、大会組織委員会、東京都、それから国が主催しまして、アクセシビリティ協議会というものを、平成２６年１１月に設置してまいりました。そこでは、誰もがアクセス可能なような形になるということを考える機関ですけれども、そこで検討していると聞いてあります。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問・要望","question":"このシステムに基づいて、介護医療、在宅医療、介護の連携、認知症施策、生活支援、介護サービスの基盤整備、高齢者の居住安定などが求められています。現時点において、医療・介護の連携、認知症施策、生活支援、介護予防サービスの基盤整備、高齢者の居住安定に関して、我々議員が区民に対してしっかりと答えやすいような具体例をお示しいただきたいと思いますが、お考えをお聞かせください。","respondent":"榎本福祉部長","answer":"特にこの２つが、今回の地域包括ケアシステムの中では重点的に進めているものです。ほかにも、介護予防事業等ありますけれども、その分は従前から、第５期の段階からやってきておりますので、まず第６期ではこの２つを大きく進めていきたいと考えているところです。","id":"exchange-088"},{"speaker":"いながわ委員","kind":"質問","question":"木村委員に引き続き、民主党・無所属クラブの総括質疑を行います。私からは、今後の外国人観光客等の増加への対応について、外国人観光客等の動向についてを、初めにお伺いいたします。この統計結果をどのように受けとめておられるのか、企画部と文化スポーツ振興部、それぞれの視点でお伺いいたします。お願いします。","respondent":"中山企画部長、安藤文化スポーツ振興部長","answer":"裏返せばＷｉ－Ｆｉや様々な案内等、区の施策についても今後工夫していく余地が出てくると考えているものです。外国人向けの観光プロモーションの実施や、またコンテンツの充実、そしてショートトリップの推進など、外国人の観光客の取組みを積極的に推進していく必要性を感じております。","id":"exchange-089"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ここからは、品川区の独自の観光統計についてお伺いしてまいります。これらの数値は、宿泊旅行統計調査の結果を用いていると思いますが、この記載されている数値の根拠、そして、なぜ実宿泊者数を用いているのか、ご所見をお伺いします。観光戦略を考えると、やはり早期に観光に関するマーケティング調査を実施する必要性があると考えますが、本区のご所見をお伺いします。","respondent":"中山企画部長、安藤文化スポーツ振興部長","answer":"私は前半の、総合戦略に用いた数値にお答えいたします。そんなことから、早急な独自調査を行う必要性は低いと考えておりますけれども、しかしながら、今後設置予定の（仮称）品川区観光振興協議会に加盟する、たくさんの多岐にわたる事業者の皆様から得られる品川独自の様々な推定値を。","id":"exchange-090"},{"speaker":"いながわ委員","kind":"質問・要望","question":"その辺はぜひ品川区も幅広い観点で考えていただきたいと思います。ぜひそれは続けて進めていただきたいと思います。大田区のマーケティング調査では、南大井の宿泊施設が４施設入っております。それを入れ込むことによって、宿泊施設の足りないという部分は、ある程度の方向性は出るのではないかなと考えていますが、その辺、一言何かあればお答えいただきたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"しかしながら、どうでしょうか、日本人・外国人を問わず観光客の目線で考えますと、いかに品川区に昼間来ていただいて観光していただくかということに着目いたしますれば、例えば港区の品川駅の高輪口ですか、あの辺も、港区ではありますけれども、あそこから。","id":"exchange-091","title":"町会・自治会支援"},{"speaker":"いながわ委員","kind":"質問・要望","question":"続きまして、東京オリンピック・パラリンピック開催に向けてのまちづくり、そして区内宿泊施設の現状と課題についてお伺いしてまいりたいと思います。この数値が、多少の誤差はあると思うのですが、現状で宿泊施設が不足していると言えるのか、もし不足しているとお考えなのであれば、どのような施策をもって解決されるのかご所見をお伺いしたいと思います。","respondent":"中山企画部長","answer":"対応ですけれども、これは一義的には、民間事業者による施設の確保・建設というものが基本と考えていますが、区といたしましては、例えばご議論になっております資産の有効活用としての民泊であるとか、あるいはボリュームの問題はありますけれども。","id":"exchange-092"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この件に関しては、ぜひ幅広い視点でいろいろ物事を考えていっていただきたいなと考えています。本区における簡易宿所または特区民泊は、外国人観光客の宿泊施設の救世主となるとお考えなのか、いま一度ご所見をお聞かせいただきたいと思います。ホテルの整備には、関連する法規制等が多くあります。品川区版のホテル整備に関する法令等の緩和策も１つの手法と考えますが、区のご所見をお聞かせください。","respondent":"中山企画部長","answer":"そういう中ですけれども、様々な規制の緩和の動きも見ながら適切な対応を考えておりますけれども、審査期間の短縮等については、現在も審査や検査については所管のほうで迅速に進めておるところですけれども、今後例えば消防であるとか関係機関との連携をより密にして。","id":"exchange-093"},{"speaker":"いながわ委員","kind":"質問・要望","question":"一番いいのは、新たなホテルを１棟整備することで全てが解消されるのではないかなというのは僕の個人的な見解でありますが、また、これも幅広い視点でお考えいただきたいと思います。こうした状況から、やはり特区による民泊に関する条例、もしくはそれに類する制度の制定を行い、行政がその営業等を把握し、違法な営業に対して指導を行うことが必要と考えますが、区のご所見をお伺いいたします。","respondent":"中山企画部長","answer":"違法もしくはそれに近い民泊というものは、区民の安全安心あるいはまちづくりの観点ということからも、しっかりと規制すべきものと考えております。そういう行為をできるだけ排除するよう努めてまいりたいと考えておるところです。","id":"exchange-094"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば、区内公衆便所へ便所使用の注意事項、路上等への、たんや唾を吐くことの禁止、歩きたばこの禁止、路上喫煙やかみたばこの禁止等の注意喚起、観光中におけるごみの分別、これは公園のごみ箱等を指します、などの多言語表示にすることや、視覚記号の一つであるピクトグラムの双方を用いた区内のサイン整備を行う必要があると考えますが、区のご所見をお伺いします。","respondent":"中山企画部長","answer":"今後ですけれども、オリンピック・パラリンピックに向けてのしっかりとした整備のありようについてもあわせて考えてまいりたいと考えているものです。","id":"exchange-095"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しっかりとした整備を進めていただきたいと思います。本来であればもう一点、質問したいところでありますが、最後に児童相談所について、区内設置についてお伺いしたいと思います。我が会派では、児童相談所の区への移管について都度質問し、金沢にも視察を行い、早期の実施を求めてまいりました。国の方針を受け、本日も他会派より質問がございましたが、１点確認させていただきたいと思います。","respondent":"金子子ども未来部長","answer":"実際に移管となれば、また精緻な検討が必要になるとは思いますけれども、様々な課題がありまして、この法改正がされれば、大きな追い風として、今後とも児相の移管については積極的に取り組んでまいる考えです。","id":"exchange-096"},{"speaker":"いながわ委員","kind":"質問・要望","question":"まさに１つの追い風でありますので、部長がおっしゃったように、積極的に進めていただきたいと思います。それぞれのご答弁ありがとうございました。以上で、民主党・無所属クラブの総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"シティプロモーションについて伺います。区長も、施政方針で一番最初に述べられるなど、その熱意が感じられ、今年度も２,６７４万円の予算計上となっております。しかし、シティプロモーションを行うにしても、ある程度の具体的な数値目標を持って行うべきだと考えます。シティプロモーションの精神的な効果はわかりますが、経済的な効果はどのようなものになるか、区の分析、お考えをお答えください。","respondent":"中山企画部長","answer":"ただ、具体的な目標とすべき指標あるいは測定方法につきましては、様々今後、検討を進めてまいりたいと考えておるところです。なお、昨年１１月に大井町アトレにおきまして、「わ！","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問・要望","question":"「わ！しながわ」の意味をわかりやすく伝えるべく、私も拝見しましたが、まだまだ不十分な区のホームページの解説をもっとわかりやすく直して、改めて区民へのわかりやすい周知を図るべきと考えますが、いかがでしょうか。」の後にどのような言葉を入れたほうがよいのか、例文を使うなど、区民に使い方のレクチャーを、区のホームページやポスター、動画に掲載するべきと考えますが、いかがでしょうか。","respondent":"中山企画部長","answer":"「わ！しながわ」のネーミングあるいはロゴですけれども、ご指摘のとおり、周知というのは重要なことで、まだまだこれから力を入れていかなければいけないと認識しています。","id":"exchange-099"},{"speaker":"筒井委員","kind":"質問・要望","question":"したがって、区、区長は、国土交通省に対し、この新飛行ルート案の撤回の主張をまず行うべきと考えますが、いかがでしょうか。撤回に至らない場合は、区民の不安を払拭すべく、防音対策、落下物防止対策、テロ対策、そして中長期的には新飛行ルート案の定期的な見直しの機会を設けること、羽田空港滑走路の角度変更工事を行っていくことを国土交通省に積極的に求めるべきだと考えますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"国が今示している方策の中では、平成３２年以降の海側への滑走路の増設の検討の話も出てありますので、新たな技術革新なども含めまして、国との連絡体制の継続に努めてまいりたいと考えています。","id":"exchange-100"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただ、一方、私が先ほど述べましたマイナスの効果、デメリットも確実に出てくると思われますので、国に対して、品川区のメリット・デメリット、そうした、ある意味、計算というか測定などもしっかりと求めていただきたいと考えております。大田区とは異なった状況での品川区のメリット、経済効果の生み出しについて、区はどうお考えでしょうか。航空機対策の専門部署などを設けるおつもりはあるのでしょうか。","respondent":"藤田都市環境部長","answer":"しっかりと協力して、地域の方々の声にも今までも対応してまいってきておりますので、現段階では、さらなる協力体制の強化に努めてまいりたいと考えています。","id":"exchange-101"},{"speaker":"筒井委員","kind":"質問","question":"リオデジャネイロオリンピック視察について伺います。予算書において２,１３２万３,０００円と計上されておりますが、視察の目的、費用の内訳、そして誰が何人で何日間、行かれるのでしょうか。それぞれお答えください。","respondent":"安藤文化スポーツ振興部長","answer":"そんな中で、現地に直接行きまして、競技会場の自治体としての対応だとか、また競技は当然ではありますけれども、様々なボランティアの活動、またはスタッフ等、そしてまたサイン関係、様々なものを見聞していきたいと考えています。","id":"exchange-102"},{"speaker":"筒井委員","kind":"質問","question":"ですから、視察に行かれるのだったら、ぜひとも、かかった費用、そして行ったところのリオでの見た内容を、しっかりと東京オリンピック・パラリンピックの品川区での開催にあたり活かしてほしいと考えておりますが、その点、いかがでしょうか。ですから、区のほうでも、ホームページ、広報等で区民へのこの視察の結果の周知・報告をすべきだと考えておりますが、いかがでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"区民に対する説明責任ですけれども、これも行政の裏方としての仕事を見聞して視察していくわけですから、区民に対してどこまで情報提供できるかわかりませんけれども、その辺も考えていきたいと考えています。","id":"exchange-103"},{"speaker":"筒井委員","kind":"提案","question":"ぜひとも区民へのそうした視察の報告・周知を行っていただきたいと考えております。次に主権者教育について伺います。現在でも、８・９年生の市民科では、項目１２の地方自治への施策提案、項目２６の社会の一員としての活動が行われていますが、さらに選挙を意識した、より丁寧に深めた授業を行うべきと考えますが、いかがでしょうか。それぞれ区の見解をお聞かせください。","respondent":"本城教育次長","answer":"ただ、小学校あるいは中学校について申せば、現在、１８歳の選挙権が開始されたということで、直接的にかかわる高校生については、今、モデル的に文科省のほうでも検討が始まったところで、小学生については、これから文科のプロジェクト等も発足するですので。","id":"exchange-104"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。積極的に、市民科のこれからの自立の研究を行っていただきたいと考えております。次に、投票率向上のための投票所の設置、選挙割について伺います。品川区でも、こうした区内の商業・文化施設を利用した期日前投票所の設置を行うべきと考えますが、いかがでしょうか。区も、商店街連合会や協力商業施設への選挙割を積極的に推奨すべきと考えますが、いかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"いずれにいたしましても、選挙の公平性の確保に十分留意しつつ、その中で有権者の動向に着目いたしまして、投票所の効果的な配置という観点で、他自治体での取組みや実績などを踏まえまして検討してまいりたいと考えています。","id":"exchange-105"},{"speaker":"筒井委員","kind":"質問","question":"区民人口増加による、子育て・教育・高齢者施設不足対策について伺います。これに向けての、区としてはどのような対策をお考えでしょうか。学校の増改築での対応でしょうか。限られた土地での対応と同時に区内経済の活性化も図れるので、多世代多施設複合型施設に商業施設を組み合わせるということも可能でしょうか。特に待機児童対策が急務と思われますが、区としてはどのようにお考えでしょうか。","respondent":"本城教育次長、中山企画部長、金子子ども未来部長","answer":"様々な大規模なマンション等の開発等の計画段階からその情報をつかむことをもとにして、どの程度のキャパシティーを持った学校が必要かどうか等を。それから最後に、東京一極集中に向けての好意的対応等々とありますけれども、この点につきましては、これは様々、区の中でできること。今後とも人口と保育ニーズの動向を見きわめ、待機児童対策につきましては積極的に取り組んでいく考えです。","id":"exchange-106"},{"speaker":"筒井委員","kind":"質問","question":"待機児童問題の解決は地方分権の推進による解決ということについて、ご担当の子ども未来部長としてはどうお考えでしょうか。子ども未来と名づけられていますが、子どもの未来についてどうお思いでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問","question":"待機児対策、羽田空港増便計画、パブリックコメントについて、区の見解を伺いたいと思います。品川区の待機児対策について伺います。品川区は待機児対策に取り組んでいるにもかかわらず、なぜ保育を希望する方たちの願いが一向にかなわないのでしょうか。事業促進中の再開発で計画上の住宅戸数は一体どのぐらいになっているのでしょうか。伺います。区の把握状況について伺います。","respondent":"藤田都市環境部長","answer":"平成２７年４月からは、東京都において「新しい都市づくりのための都市開発諸制度活用方針」というものが定められまして、この中で、市街地再開発事業などの都市計画を定める事業については、子育て支援施設の必要性等について事前確認をすることが義務づけられておりますので。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"今後も把握状況をしっかり確認していただき、待機児対策と再開発などの政策をすり合わせて進めていくことを要望いたします。ですから、民営化を否定はしません。品川区の保育園の民営化がコスト削減一辺倒であるならば再考を求めます。区からは、国土交通省に対して要望を出されているというような発言がありますが、具体的に何を国土交通省に要望しているのか伺います。区の見解を伺います。","respondent":"金子子ども未来部長、藤田都市環境部長","answer":"ただ、私どもがこれから進める保育園の民営化におきましては、当然、事業者について、今の段階ですけれども、公募という形をとっていきたいと考えておりまして、それについては数々の事業者の中に提案をいただいて。こうしたことについてしっかりと今後、騒音対策あるいは安全の対策等についても、国からどのように２４０の意見について対応していくのか、こういったことをしっかり区民にお答えしてほしいというようなことを。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"次に騒音について伺います。そのときの八潮の騒音の数値を幾らと公表されていたのか伺います。そのときに区は、一般財団法人空港環境整備協会に対策や補償を求めるのでしょうか。区はどのようにお考えなのでしょうか。こういう補助もあったのだと初めて知りましたが、対象の６校とはどこでしょうか。合わせて、区は、どういう対策を法人に対して求めてきたのか伺います。確認させてください。","respondent":"藤田都市環境部長、本城教育次長","answer":"区のほうといたしましては、先ほど委員からもお話がありましたとおり、２４時間で評価すればそうであるということはそうなのですけれども、１回ごとの騒音については、やはり大きいというのは事実ですので。こちらについては、この助成制度、前身となる制度が平成２０年にできて、現在の制度としては平成２２年からの助成制度となっておりますが、趣旨といたしましては、空港の円滑な運用を確保する観点から、空港周辺の住民地を。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"国土交通省が、２００９年羽田空港拡張に伴う、品川上空を通過する飛行ルート案を２００４年に出したときには、品川区は国土交通省にさまざまな確認を事前に行い、同年５月にその計画の撤回を求めていました。以下、紹介します。これを遵守してほしいということが、まず１つの区の考え方です。区は方針転換をしてしまったということでしょうか。方針転換をしたのだとしたら、いつでしょうか。伺います。","respondent":"藤田都市環境部長","answer":"平成１６年当時のお話です。その当時の状況について、まずちょっとご確認の意味も含めて説明します。その当時は、羽田空港の状況としては、国内空港需要のほう、やはり増大しておりまして、早急に対応するために再拡張事業について着手していきたいと言っていたときです。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"区は、２００４年当時のように、区民を守るという姿勢に立ち戻ってほしいと要望いたします。３点目に、パブリックコメントの実施について伺います。そのためには、区民が条例案の中身を決定前に知り意見を出すということが、策定過程には必要ではないでしょうか。品川区がパブリックコメントを行う目的は何ですか。そして、なぜ条例案をパブリックコメントの対象にしないのでしょうか。その理由を伺います。","respondent":"中山企画部長","answer":"品川区のパブリックコメントですけれども、平成１９年度に品川区区民意見公募手続の実施に関する要綱を定めまして、区の基本的計画等についてパブリックコメントの制度化を行い、実施しています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一度言います。そして、２３区のパブリックコメントの状況を調べました。２３区中、条例案をパブリックコメントの対象にしている区が１２区ありますが、品川区同様に条例案をパブリックコメントの対象にする根拠を持たない自治体であっても、５区が条例案をパブリックコメントの対象とする実績がありました。品川区もパブリックコメントの対象に条例案を加えることを求めます。見解を伺います。","respondent":"中山企画部長","answer":"いずれにしても、区民参加の手順というのは、様々な手法の中で区はしっかり確保していく。こういう観点の中で進めているものです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"つまり、要綱だからこそ、必要に即応して変えることができるという意味だと理解しています。すぐにも要綱の中に、パブリックコメントの対象として条例案を入れることを求めます。見解はいかがでしょうか。","respondent":"中山企画部長","answer":"パブリックコメントは、ご案内のとおり、一定期間の周知期間等々を考えると、これはまた議案の議決までの期間の問題、あるいは条例の即応性というものも含めて総合的に考えていくべきものと考えておるものです。","id":"exchange-114"},{"speaker":"渡辺委員","kind":"提案","question":"本委員会で我が会派委員が指摘・質問した特別支援教育への支援、子ども・子育て応援券などの在宅子育て支援、介護保育の人材確保、ＪＲ広町アパート跡地有効活用、拠点駅のセーフティ化、ＡＥＤの管理と設置、学校選択制などの発展的な見直しと子どもの体力向上などの要望提案を、濱野健区長をはじめ理事者におかれましては、これらを真摯に捉え、今後の施策・予算措置への具体化を強く望むものであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"提案","question":"最後に、本予算特別委員会で会派委員から提案・要望した、障害者への合理的配慮の職員への徹底、非核平和施策の充実、食品ロス対策の充実、文化スポーツ振興基金の効果的な活用、オリジナル婚姻届・出生届の導入、知的障害者への選挙支援、がん教育の充実、商店街装飾灯ＬＥＤ化支援、品川区の教育に対する保護者理解の促進などの提案・要望を真摯に受けとめ、今後の施策に十分反映されますよう強く要請し。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"},{"speaker":"中塚副委員長","kind":"提案","question":"日本共産党は、過去最高の１,６７９億円もの新年度予算案に対し、格差と貧困を拡大する安倍政権の暴走から、地方自治の発揮で区民の暮らしを守り抜く区政の実現に踏み出すよう、切実な住民要望や声を紹介、具体的提案とともにその実現を求めてきました。濱野区長は国に、市街地上空を通過しない海上ルートへの変更を求めるべきです。この先１,０００億円を目指す考えも再び示されました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"あべ委員","kind":"提案","question":"文化スポーツ振興基金の適切な運用、オリンピック・パラリンピック開催に向けた公園や水族館等の活用、駅前へのＷｉ－Ｆｉスポットの拡大、民泊に向けた慎重な検討、なぎさ会館等、公共施設のあり方の見直し、羽田空港と新ルート案に関連した環境調査等の早期実施、ネットいじめ対策や不登校対策のさらなる充実、児童相談所の早期設置に向けた検討をはじめ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"筒井委員","kind":"質問・要望","question":"平成２８年度予算に対する維新・無所属品川の意見表明を行います。維新・無所属品川は、平成２８年度の品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計の各予算に賛成します。さらに、本年２月からの日銀のマイナス金利政策は、先が全く見えない状況です。こうした中で、区民生活に最も密着した区政には、様々な生活のレベルアップが区民ニーズとして求められています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"吉田委員","kind":"提案","question":"予算執行にあたり、各款別審査で生活者ネットワークが指摘・提案させていただいた意見を活かしていただくことを要望し、さらに、以下何点か意見を申し上げます。ぜひ改善を求めます。ぜひスピード感を持った温暖化対策を求めたいと思います。そのことがとても大切です。今後もさらに区民の声を聞くこと、区民への情報提供を充実させることを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"石田（秀）委員長","kind":"提案","question":"区長の発言が終わりました。この間、優秀なる、つる・中塚副委員長には、皆様の質問を全て控えていただくというような、私からの要望も全て受け入れていただきまして、助けていただくことができました。ここに改めて厚く御礼申し上げます。今、濱野区長からもお話がありましたように、理事者の方々もそうでありますが、我々委員から、様々な要望、また提案等をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/257095?Template=document&Id=1050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":118505,"voices":270}},{"id":"h28-20160322-10","meetingId":"h28-cm03","date":"2016年3月22日","dateIso":"2016-03-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年第１回定例会","agenda":"平成２８年第１回定例会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"監査委員ですけれども、監査委員は常勤の方と、外部監査委員と、その他の監査委員ということになっていると思いますけれども、この方はどういう監査委員での選任同意なのか、ひとつお聞かせいただきたい。それから、人権擁護委員の後藤基さんの賞罰のところで感謝状が二つ出されていますけれども、どんなことで感謝状を受けられているのか、わかったら教えていただきたいと思います。","respondent":"濱野区長","answer":"代表のみが常勤です。それから、２点目でありますけれども、感謝状につきましては、詳しい内容は存じておりませんけれども、おそらくでありますけれども、永年の勤続についての感謝状ではないかと推察しておるところです。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/457598?Template=document&Id=5174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":10652,"voices":63}}]);
